import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-e-001","clusterId":"E","werkstueckRef":"E.1.1","stufe":1,"question":"Du liest eine Schlagzeile und merkst, dass dich eine Meldung sofort wütend macht. Du willst gleich einen empörten Kommentar schreiben. Welche Reaktion ist am klügsten?","options":["Eine Nacht abwarten, bis die Wut verflogen ist, und den Kommentar dann in ruhigerem Ton schreiben, auch wenn du nur die Überschrift kennst.","Die Wut als Warnsignal nehmen, erst den Artikel hinter der Schlagzeile mit seinen Zahlen und Quellen lesen und dann entscheiden, ob und was du kommentierst.","Den Kommentar sachlich und ohne Beleidigungen formulieren und deine eigenen Erfahrungen mit den Radwegen deiner Stadt als Beispiel anführen.","Die Schlagzeile an Bekannte weiterleiten, abwarten, wie viele genauso empört reagieren, und erst danach deinen Kommentar schreiben."],"correctIndex":1,"explanation":"Eine starke, sofortige Emotion bei einer einfach gestrickten Meldung ist ein typisches Zeichen dafür, dass das schnelle, automatische Denken die Führung hat. Das schnelle Denken ist für Routine nützlich, aber bei neuen oder wichtigen Urteilen anfällig für Fehler. Das langsame, anstrengende Prüfen muss man bewusst einschalten, von allein springt es nicht an. Wer nur die Überschrift kennt, weiß weder, wie hoch die Summe wirklich ist, noch, was sie umfasst oder womit sie zu vergleichen ist. Das Gefühl ist also ein Anlass, innezuhalten und zu prüfen, kein Beweis. Deshalb hilft es, erst die Fakten zu lesen und danach zu urteilen. Ein Gefühl der Stimmigkeit ist kein Wahrheitsbeleg. Eine Nacht abzuwarten beruhigt zwar, ändert aber nichts daran, dass der Kommentar weiter nur auf der Überschrift beruht. Ein sachlicher Ton mit eigenen Erfahrungen klingt fair, sagt aber nichts darüber, wie hoch die Summe ist und was sie umfasst. Die Reaktionen von Bekannten zeigen nur deren Stimmung, nicht die Faktenlage.","coreRule":"⚡ Starkes Gefühl plus Eile ist ein Signal zum Innehalten: Erst bewusst prüfen, dann urteilen.","quote":"Du spürst eine starke, sofortige emotionale Reaktion auf eine Information.","quoteLabel":"Merksatz:","beleg":"Werkstück E.1.1 (Kernidee; Kontext & Tiefe); Fn. gl-e-zweisystem (Kahneman 2012, Teil I, Kap. 1: „fiktive Figuren“)","status":"entwurf","scenario":"Die Schlagzeile lautet: „Skandal: Stadt verschwendet Millionen für nutzlose Radwege!“ Du hast nur die Überschrift gelesen, spürst aber sofort ein klares Urteil.","kurz":"Wer nur die Überschrift kennt, weiß weder, wie hoch die Summe wirklich ist, noch, was sie umfasst. Starke Wut ist deshalb ein Anlass, innezuhalten und die Fakten zu lesen, kein Beweis für das Urteil.","prueffrage":"Welche Angaben zu Summe, Umfang und Vergleich findest du in der Überschrift, und welche fehlen?","rueckmeldung":[{"option":0,"text":"Eine Nacht Abstand dämpft die Wut und macht den Ton ruhiger. Der Kommentar beruhte aber weiter nur auf der Überschrift: Wie hoch die Summe ist und was sie umfasst, wüsstest du dann immer noch nicht."},{"option":2,"text":"Ein sachlicher Ton und eigene Erfahrungen machen einen Kommentar fairer und nachvollziehbarer. Sie sagen aber nichts darüber, wie hoch die Summe ist, was sie umfasst und womit sie zu vergleichen ist."},{"option":3,"text":"Die Empörung anderer wirkt wie eine Bestätigung, zeigt aber nur deren Stimmung und nicht die Faktenlage. Zudem verbreitest du eine Meldung weiter, die du selbst noch nicht geprüft hast."}],"familie":"innehalten-bei-druck","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality: A Perspective on Intuitive Judgment and Choice. Nobelpreis-Vortrag, Nobel Foundation","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"PDF-S. 3, 5–6","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Kahneman, D. (2012): Schnelles Denken, langsames Denken. München: Siedler, Teil I","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"a1f492bb9065a326"}},{"id":"qx-e-002","clusterId":"E","werkstueckRef":"E.1.1","stufe":2,"question":"Du bemerkst, dass du fast automatisch klicken würdest. Was ist in dieser Lage der klügste nächste Schritt, und warum?","scenario":"Du bekommst eine Nachricht: „Ihr Konto wird in einer Stunde gesperrt – jetzt sofort bestätigen!“ Dein Puls steigt, und du willst nur noch schnell klicken.","options":["Kurz innehalten und die Sperrung über die offizielle App deiner Bank prüfen statt über die Nachricht, weil der Druck dich vom Prüfen abhalten soll.","Dem Absender antworten und um Bestätigung bitten, dass die Kontosperrung echt ist, weil eine echte Bank das umgehend bestätigen würde.","Die Nachricht auf Rechtschreibfehler und holprige Sätze durchsehen, weil sich Betrugsnachrichten meist an schlechter Sprache erkennen lassen.","Die Absenderadresse mit früheren Mails deiner Bank vergleichen und bei Übereinstimmung auf den Link tippen, weil gefälschte Adressen sofort auffallen würden."],"correctIndex":0,"explanation":"Zeitdruck und starke Gefühle wie Angst oder Gier sind ein bewährtes Mittel von Betrügern: Wer unter Druck steht und aufgeregt ist, greift eher auf schnelle, automatische Reaktionen zurück, statt die Lage in Ruhe zu prüfen. Die wirksamste Gegenmaßnahme ist, die Situation zu verlangsamen und die Behauptung unabhängig zu überprüfen, also nicht über den Link in der Nachricht, sondern über einen Kanal, den du selbst kennst. Ein starkes Alarmgefühl ist kein Beweis für eine echte Gefahr, denn es lässt sich gezielt erzeugen. Erst prüfen, dann handeln. Die Antwort an den Absender klingt nach Rückfrage, fragt aber genau den, der lügen könnte, sodass seine Bestätigung nichts wert ist. Die Sprachprüfung klingt nach Sorgfalt, doch gute Fälschungen sind sprachlich einwandfrei. Der Adressvergleich klingt nach Kontrolle, doch Absenderadressen lassen sich fälschen.","coreRule":"⚡ Je schneller und emotionaler man dich zu einer Entscheidung drängt, desto dringender brauchst du eine Denkpause und eine unabhängige Prüfung.","beleg":"Werkstück E.1.1 (Anwendung & Relevanz: Bei Betrugsmaschen; Red Flags)","status":"entwurf","kurz":"Wer unter Druck und Aufregung steht, reagiert automatisch, und genau darauf zielt die Nachricht. Ein starkes Alarmgefühl beweist keine echte Gefahr, es lässt sich erzeugen. Deshalb verlangsamen und über einen Kanal prüfen, den du selbst kennst.","prueffrage":"Was weißt du über den Absender sicher, abgesehen von dem, was die Nachricht selbst über sich behauptet?","rueckmeldung":[{"option":1,"text":"Eine Rückfrage wirkt wie sorgfältiges Prüfen. Du fragst damit aber genau den, der lügen könnte, und seine Bestätigung ist nichts wert. Geprüft ist erst, was du über einen Kanal klärst, den du selbst kennst."},{"option":2,"text":"Holprige Sprache ist bei plumpen Betrugsnachrichten tatsächlich öfter zu finden. Gute Fälschungen sind aber sprachlich einwandfrei, und fehlende Fehler beweisen nichts. Vor allem bleibt der Druck unbeachtet, der dich zum schnellen Klicken drängt."},{"option":3,"text":"Der Vergleich ist ein Schritt in Richtung Prüfen, aber Absenderadressen lassen sich fälschen, eine Übereinstimmung beweist also wenig. Der Plan endet zudem beim Link in der Nachricht, dem Weg, den du meiden solltest."}],"familie":"innehalten-bei-druck","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Federal Trade Commission (FTC): How To Avoid a Scam","oeffentlich":true,"url":"https://consumer.ftc.gov/articles/how-avoid-scam","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality: A Perspective on Intuitive Judgment and Choice. Nobelpreis-Vortrag, Nobel Foundation","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"PDF-S. 5–6","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"ba5784ba6e06ca32"}},{"id":"qx-e-003","clusterId":"E","werkstueckRef":"E.1.1","stufe":3,"question":"In welcher dieser Situationen ist es am riskantesten, dich auf dein schnelles Bauchgefühl zu verlassen?","options":["Du entscheidest über deine Ersparnisse allein nach dem Gefühl, das ein einfach klingendes Anlageversprechen bei dir auslöst.","Du sagst für eine Mietwohnung zu, allein weil sie dir bei der ersten Besichtigung auf Anhieb ein gutes Gefühl gegeben hat.","Du kaufst eine teure Waschmaschine, allein weil dir der Verkäufer im Laden auf Anhieb kompetent und ehrlich vorkommt.","Du beauftragst einen Handwerker mit einer kleinen Reparatur, allein weil er dir am Telefon auf Anhieb zuverlässig vorkommt."],"correctIndex":0,"explanation":"Anders bei Geld, Gesundheit oder politischen Weichenstellungen, in denen man selbst keine Erfahrung mit Rückmeldung hat: Hier geht es um viel, die Lage ist komplex oder neu, und gerade ein „einfach klingendes“ Versprechen ist ein typischer Köder für das Bauchgefühl. Wo viel auf dem Spiel steht und die Situation ungewohnt ist, lohnt sich das langsame, bewusste Nachprüfen, weil ein Fehlurteil teuer wird.","coreRule":"⚡ Bei Routine mit geringem Einsatz darf das Bauchgefühl entscheiden; bei hohen Einsätzen oder Neuem lohnt sich das langsame, bewusste Prüfen.","beleg":"Werkstück E.1.1 (Der Kipppunkt; Kontext & Tiefe: Zuständigkeit von System 1)","status":"entwurf","scenario":"","kurz":"Bei Ersparnissen steht viel auf dem Spiel, die Lage ist oft undurchsichtig, und ein einfach klingendes Versprechen spricht gezielt das Gefühl an. Dort wird ein Fehlurteil teuer, deshalb lohnt hier das langsame Nachprüfen.","prueffrage":"Wie oft hast du jede dieser Entscheidungen schon getroffen, und wie schnell würdest du jeweils merken, dass du falsch lagst?","rueckmeldung":[{"option":1,"text":"Ein Besichtigungsgefühl ist ein echtes Signal, und eine Wohnung ist vielen aus Erfahrung vertraut. Mietvertrag, Nachfragen und die Möglichkeit zu kündigen begrenzen das Risiko deutlich, anders als bei Ersparnissen."},{"option":2,"text":"Eine teure Anschaffung wirkt riskant, doch eine Waschmaschine ist ein bekanntes, gut vergleichbares Produkt, und Garantie und Rückgabe fangen einen Fehlgriff ab. Der Schaden bleibt begrenzt und überschaubar."},{"option":3,"text":"Ein Telefoneindruck ist dünn, aber bei einer kleinen Reparatur ist wenig zu verlieren. Ergebnis und Rechnung zeigen schnell, ob die Wahl gut war, und ein Fehlgriff lässt sich leicht korrigieren."}],"familie":"faustregel-oder-rechnen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality: A Perspective on Intuitive Judgment and Choice. Nobelpreis-Vortrag, Nobel Foundation","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"PDF-S. 3, 5","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Kahneman, D. (2012): Schnelles Denken, langsames Denken. München: Siedler, Teil I","oeffentlich":false},{"typ":"literatur","kurz":"Kahneman, D.; Klein, G. (2009): Conditions for intuitive expertise: A failure to disagree. American Psychologist","oeffentlich":false,"doi":"10.1037/a0016755"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"a94a8ab12803383c"}},{"id":"qx-e-004","clusterId":"E","werkstueckRef":"E.1.1","stufe":4,"question":"Wie gehst du mit der Zahl um?","options":["Du behandelst sie als ungeprüft, weil auch häufiges Wiederholen in Marketingbüchern eine Zahl ohne nachprüfbare Studie nicht zum Befund macht.","Du übernimmst sie vorläufig, weil 90, 95 und 98 Prozent sich ähneln und die Übereinstimmung mehrerer Quellen für ihre Richtigkeit spricht.","Du hältst sie für plausibel, weil intuitives Denken schnell abläuft und deshalb den größten Teil des Alltags bestimmen dürfte, auch ohne genaue Prozentzahl.","Du akzeptierst sie, weil die Agentur einen bekannten Psychologen nennt, und prüfst nur noch, ob er in der Präsentation richtig zitiert wurde."],"correctIndex":0,"explanation":"Eine glatte Prozentzahl ohne nachvollziehbare Studie dahinter ist zunächst nur eine Behauptung. Dass sie in vielen Marketingtexten steht, ist kein Beleg: Die Zahl lässt sich auf keine belastbare Studie zurückführen und kursiert vor allem im Marketing. Die richtige Reaktion ist deshalb: nach der Originalstudie fragen und die Zahl bis dahin als ungeprüft behandeln. Die leicht abweichenden Werte (90, 95, 98 %) klingen nach Übereinstimmung, sind aber keine Bestätigung durch mehrere Messungen, sondern eher ein Zeichen, dass eine Zahl weitergereicht und dabei abgewandelt wird. Dass intuitives Denken im Alltag sehr häufig ist, klingt einleuchtend, rechtfertigt aber keine feste Prozentzahl. Ein berühmter Name klingt nach Gewähr, ersetzt aber keine Quelle, und die richtige Zitierung macht die Zahl nicht belegt.","coreRule":"⚡ Eine glatte Prozentzahl ohne Studie dahinter ist eine Behauptung, kein Befund.","beleg":"Werkstück E.1.1; Fn. gl-e-95prozent; Fn. gl-e-hirnenergie (Raichle & Gusnard 2002, S. 10237–10238)","status":"entwurf","scenario":"Eine Werbeagentur wirbt mit der Aussage: „Unser intuitives Denken steuert 95 % unserer Entscheidungen.“ Die Zahl steht in einer Präsentation, mit der sie ihren Kunden „neurowissenschaftlich fundiertes Marketing“ verkauft. Eine Studie nennt die Agentur nicht, sie verweist nur auf einen bekannten Psychologen. Auf Nachfrage heißt es, die Zahl stehe „in jedem Marketingbuch“, und je nach Quelle seien es 90, 95 oder 98 %.","quote":"","quoteLabel":"","kurz":"Eine glatte Prozentzahl ohne nachvollziehbare Studie ist zunächst nur eine Behauptung. Dass sie in vielen Marketingtexten steht, ist kein Beleg; sinnvoll ist, nach der Originalstudie zu fragen und die Zahl bis dahin als ungeprüft zu behandeln.","prueffrage":"Lässt sich verfolgen, woher die 95 % ursprünglich stammen, und warum nennen andere Bücher 90 oder 98 %?","rueckmeldung":[{"option":1,"text":"Die ähnlichen Werte wirken wie eine Bestätigung durch mehrere Quellen. Es sind aber keine unabhängigen Messungen: Wenn jeder dieselbe Zahl abschreibt und dabei leicht abwandelt, entstehen genau solche Abweichungen, ohne dass ein Befund dahintersteht."},{"option":2,"text":"Dass intuitives Denken schnell abläuft und im Alltag sehr häufig ist, stimmt und leuchtet ein. Daraus folgt aber nicht, dass sich sein Anteil auf eine feste Prozentzahl beziffern lässt; dafür bräuchte es eine Messung, und die nennt die Agentur nicht."},{"option":3,"text":"Ein bekannter Name klingt nach Gewähr, ersetzt aber keine Quelle. Wer nur nachprüft, ob der Psychologe richtig zitiert wurde, klärt die Zitierung, nicht die Zahl: Selbst ein korrektes Zitat macht sie nicht belegt."}],"familie":"zahl-zur-quelle","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Harvey, C. (2025): 3 dangerous behavioural science myths – and what to do about them. Research World (ESOMAR)","oeffentlich":true,"url":"https://researchworld.com/articles/3-dangerous-behavioural-science-myths-and-what-to-do-about-them","abruf":"2026-10-12"},{"typ":"url","kurz":"Fletcher, W. (2003): Sigmund fells trendy straw men (Rezension zu Zaltman, How Customers Think). Times Higher Education","oeffentlich":true,"url":"https://www.timeshighereducation.com/books/sigmund-fells-trendy-straw-men/177940.article","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Zaltman, G. (2003): How Customers Think. Boston: Harvard Business School Press","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"22c70aca621755d1"}},{"id":"qx-e-005","clusterId":"E","werkstueckRef":"E.1.2","stufe":1,"question":"Welche Erklärung beschreibt den Kern ihres Verhaltens am sparsamsten?","options":["Weil das Auto teuer war, will sie das ausgegebene Geld nicht verloren geben und hält deshalb an ihrer Entscheidung für das Modell fest.","Sie verlässt sich auf ihre tägliche Erfahrung mit dem Auto und hält sie für aussagekräftiger als den Test und den Hinweis des Freundes.","Die Zweifel an ihrer Kaufentscheidung sind unangenehm, und sie rückt ihre Überzeugung zurecht, statt die Entscheidung zu prüfen.","Sie hält die Kritiker tatsächlich für neidisch auf ihr teures Auto und nimmt deren Einwände deshalb nicht als sachliche Hinweise ernst."],"correctIndex":2,"explanation":"Der Widerspruch zwischen „Ich habe klug entschieden“ und „Es gibt Hinweise, dass die Wahl schlecht war“ erzeugt eine unangenehme Spannung (kognitive Dissonanz). Sie lässt sich auf mehreren Wegen verringern: das Verhalten ändern (Auto zurückgeben), die Überzeugung ändern, neue stützende Gründe suchen oder den Widerspruch herunterspielen; oft ist es am einfachsten, bestätigende Informationen zu suchen, statt die Entscheidung zu prüfen. Dazu passt eine klassische Befragung von Ehrlich und Kollegen (1957), über die Festinger berichtet: Neuwagenkäufer lasen 65 % der ihnen aufgefallenen Anzeigen für das eigene Modell, aber nur 34 % der Anzeigen für Modelle, die bei ihrer Wahl keine Rolle gespielt hatten. Anzeigen für die verworfenen Modelle mieden sie allerdings nicht: Belegt ist das Suchen nach Bestätigung, nicht das Meiden von Kritik.","coreRule":"⚡ Wenn Kritik an einer eigenen Entscheidung vor allem unangenehm ist, lohnt die Frage: Ist sie falsch, oder löse ich gerade Spannung auf, indem ich meine Geschichte zurechtrücke?","beleg":"Werkstück E.1.2 (Kernidee; Anwendung: Nach einer wichtigen Entscheidung; Anti-Denkmuster); Fn. gl-e-dissonanz (Festinger 1957, S. 3 und 13), gl-e-autokauf (Festinger 1957, S. 50–53)","status":"entwurf","scenario":"Mara hat sich für ein teures Auto entschieden. Seitdem kommen ihr Zweifel, ob die Wahl klug war: Ein Freund hat auf Mängel hingewiesen, ein Test bewertet ein anderes Modell besser. Mara liest nun nur noch Tests, die ihr Modell loben, und sagt: „Kritiker sind doch nur neidisch. Mein Auto ist die richtige Wahl, das sehe ich jeden Tag.“","kurz":"Maras Zweifel erzeugen eine unangenehme Spannung, die sich am leichtesten durch Bestätigung lindern lässt: Sie sucht Lob und wertet Kritik ab, statt die Entscheidung zu prüfen. Der Preis oder ihr Alltag erklären das allein nicht.","prueffrage":"Prüft Mara den Inhalt der Kritik, oder erklärt sie nur, warum die Kritiker sie äußern?","rueckmeldung":[{"option":0,"text":"Wer viel bezahlt hat, hält oft ungern eine Entscheidung für falsch, das kann mitspielen. Es erklärt aber nicht, warum Mara gezielt nur noch lobende Tests liest und Kritiker abwertet. Dahinter steht die Spannung zwischen Entscheidung und Zweifeln, nicht der Geldbetrag allein."},{"option":1,"text":"Eigene Erfahrung ist ein echter Hinweis, nur zeigt ein einzelner Alltagseindruck weder Mängel noch Vergleichswerte. Mara wägt Quellen aber gar nicht ab: Sie liest nur noch lobende Tests. Ihr „das sehe ich jeden Tag“ stützt eher die schon gefasste Überzeugung."},{"option":3,"text":"Dass sie Neid unterstellt, steht im Szenario, doch es bleibt offen, ob sie das glaubt oder die Kritik damit nur klein macht. Diese Abwertung dient eher dazu, den Zweifel zu dämpfen. Sie ist ein Teil des Verhaltens, nicht dessen Kern."}],"familie":"selbstrechtfertigung-erkennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Tueanrat, Y.; Alamanos, E. (2026): Cognitive Dissonance Theory: A review. In: Papagiannidis, S. (Hg.): TheoryHub Book, Newcastle University","oeffentlich":true,"url":"https://open.ncl.ac.uk/theories/7/pdf/cognitive-dissonance-theory","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Festinger, L. (1957): A Theory of Cognitive Dissonance. Stanford: Stanford University Press","oeffentlich":false,"doi":"10.1515/9781503620766"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"2e4f4910d586707f"}},{"id":"qx-e-006","clusterId":"E","werkstueckRef":"E.1.2","stufe":2,"question":"Was tut Jonas mit seiner Antwort, und was ändert sich dadurch an seiner Lage?","scenario":"Dein Freund Jonas hat vor drei Wochen für 280 Euro eine Designerjacke gekauft und sie seitdem nie getragen. Als du ihn darauf ansprichst, sagt er: „Ach, das war doch nicht so viel Geld, das merke ich gar nicht.“","options":["Er spielt den Widerspruch herunter; damit lässt das unangenehme Gefühl nach, an der ungenutzten Jacke ändert sich aber nichts.","Er schätzt den Betrag nüchtern ein; damit besteht für ihn gar kein echter Widerspruch, und an seiner Lage muss sich nichts ändern.","Er weicht deiner Frage nur aus; damit ist das Thema beendet, das unangenehme Gefühl über den Kauf bleibt ihm aber erhalten.","Er spielt den Widerspruch herunter; damit ist der Fehlkauf erledigt, denn was ihm finanziell nicht wehtut, war auch kein Fehler."],"correctIndex":0,"explanation":"Jonas spielt die Wichtigkeit des Widerspruchs herunter. Zwischen „Ich habe viel Geld ausgegeben“ und „Ich brauche das Teil gar nicht“ besteht eine Spannung, die sich unangenehm anfühlt. Wenn das Geld plötzlich „nicht so viel“ war, schrumpft der Widerspruch, und das Gefühl lässt nach. An der Lage ändert sich dadurch nichts: Die Jacke hängt weiter ungenutzt im Schrank, und aus dem Kauf wird nichts gelernt. Bei kleinen Enttäuschungen ist solche Dissonanzreduktion meist harmlos. Gefährlich wird sie erst, wenn sie uns daran hindert, aus gravierenden Fehlern zu lernen. Zur Unterscheidung der Wege, übertragen auf die Jacke: Wer sie zurückgibt, ändert sein Verhalten. Wer sagt „Das ist ein Klassiker, der kommt wieder“, ändert seine Überzeugung. Wer sagt „Aber es war ein Schnäppchen“, fügt einen neuen Grund hinzu. Wer den Widerspruch für unwichtig erklärt, spielt das Problem herunter.","coreRule":"⚡ Dissonanz lässt sich auf vier Wegen mindern: Verhalten ändern, Überzeugung ändern, neue Gründe hinzufügen oder die Wichtigkeit des Widerspruchs herunterspielen.","beleg":"Werkstück E.1.2 (Kontext & Tiefe, vier Strategien; Werkbank-Frage); Fn. gl-e-dissonanz-wege (Festinger 1957, S. 6 und 18–22)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Jonas erklärt den Widerspruch zwischen teurem Kauf und Nichtgebrauch für unwichtig, und das entlastet ihn. Der Denkfehler: Das Gefühl lässt nach, aber die Jacke hängt weiter ungenutzt im Schrank, und aus dem Kauf wird nichts gelernt.","prueffrage":"Worauf bezieht sich Jonas' Satz genau, und hat er die Jacke seitdem getragen oder zurückgegeben?","rueckmeldung":[{"option":1,"text":"Jonas’ Satz klingt wie eine gelassene Einschätzung des Betrags. Der Widerspruch zwischen teurem Kauf und Nichtgebrauch ist damit aber nicht aufgelöst, er wird nur für unwichtig erklärt, damit er weniger stört. Dass sich nichts ändern muss, ist die Folge dieses Herunterspielens und keine Einsicht."},{"option":2,"text":"Jonas geht auf deine Frage ein, er antwortet sogar inhaltlich: Das Geld sei nicht viel. Gerade das nimmt dem Widerspruch die Schärfe, sodass das unangenehme Gefühl nachlässt statt bleibt. Ausgewichen wird dem Thema also nicht, sondern seiner Wichtigkeit."},{"option":3,"text":"Dass das Herunterspielen erkannt wird, stimmt. Erledigt ist der Fehlkauf dadurch aber nicht: Dass 280 Euro nicht wehtun, macht den Kauf nicht zu einem sinnvollen, und die Jacke hängt weiter ungenutzt im Schrank. Nur das Gefühl wird leichter, die Lage bleibt dieselbe."}],"familie":"selbstrechtfertigung-erkennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Tueanrat, Y.; Alamanos, E. (2026): Cognitive Dissonance Theory: A review. In: Papagiannidis, S. (Hg.): TheoryHub Book, Newcastle University","oeffentlich":true,"url":"https://open.ncl.ac.uk/theories/7/pdf/cognitive-dissonance-theory","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Festinger, L. (1957): A Theory of Cognitive Dissonance. Stanford: Stanford University Press","oeffentlich":false,"doi":"10.1515/9781503620766"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"dcb62428fa8b1d8e"}},{"id":"qx-e-007","clusterId":"E","werkstueckRef":"E.1.2","stufe":3,"question":"Was erklärt den Unterschied zwischen beiden Beobachtungen am sparsamsten?","options":["Die starken Stöße waren wohl zu viel: Ein gewisses Maß an Mühe wertet die Gruppe auf, zu große Belastung wertet sie ab.","Peinlichkeit und Schmerz wirken verschieden: Eine peinliche Prüfung bindet an die Gruppe, körperlicher Schmerz stößt eher ab.","Im zweiten Versuch übertrug sich das Unbehagen der Stöße auf die Gruppe, weil beides in derselben Situation erlebt wurde.","Im ersten Versuch war der Aufwand der Preis für die Aufnahme, im zweiten galten die Stöße nur als Teil des Versuchs."],"correctIndex":3,"explanation":"Mühe wertet ein Ziel nur auf, wenn sie als Preis für dieses Ziel erlebt wird. Wer sich für eine Aufnahme gequält hat, muss den Aufwand vor sich selbst rechtfertigen und findet die Gruppe deshalb besser, als sie ist. Gilt die Strapaze dagegen als bloßer Teil eines Versuchs, entfällt der Anlass zur Aufwertung; die Gruppe wurde nach starken Stößen tendenziell sogar schlechter bewertet als nach schwachen. Im Sinn der Dissonanztheorie ist das die sparsamste Erklärung. Wichtig bleibt eine Einschränkung: Eine konkurrierende Deutung sieht im ersten Effekt nur einen Kontrast zum unangenehmen Vorlauf, die Rechtfertigungs-Erklärung ist also nicht die einzig mögliche.","coreRule":"⚡ Aufwand wertet nur auf, was als Ziel des Aufwands erlebt wird – sonst fehlt der Anlass zur Rechtfertigung.","beleg":"Werkstück E.1.2 (Anwendung & Relevanz); Fn. gl-e-aufwand (Harmon-Jones & Mills 2019, S. 6–7; Harmon-Jones u. a. 2024, S. 1–2 und 12); Aronson, E. (1969): The theory of cognitive dissonance: A current perspective. Advances in Experimental Social Psychology 4, 1–34, hier S. 9–11 (zu Gerard & Mathewson 1966, J. Exp. Soc. Psychol. 2, 278–287): „No Initiation“-Bedingung (starke Stöße ohne Aufnahmebezug) bewertete die aufgezeichnete Diskussion tendenziell schlechter als die Bedingung mit schwachen Stößen; Bedingung „Initiation“ (starke Stöße für die Aufnahme) bewertete sie besser. Von Sturm als Scan geliefert, am 12.10.2026 per OCR gelesen. Konkurrierende Deutung (Chapanis & Chapanis 1964: Erfolgsgefühl) dort ebenfalls dargestellt.","status":"entwurf","scenario":"Zwei Beobachtungen zur Frage, ob Mühe das Ergebnis aufwertet: (1) Menschen, die für die Aufnahme in eine Gruppe eine peinliche Prüfung ablegen mussten, fanden die Gruppe danach anziehender als Menschen mit einer kaum peinlichen Aufnahme, obwohl sich die Gruppe als ziemlich langweilig erwies. (2) In einem anderen Versuch bekamen Teilnehmende schmerzhafte oder schwache Stromstöße, die keine Bedingung für die Aufnahme in die Gruppe waren. Sie bewerteten die Gruppe danach nach den starken Stößen tendenziell schlechter als nach den schwachen.","kurz":"Mühe wertet ein Ziel nur auf, wenn sie als Preis dafür erlebt wird. Wer sich für die Aufnahme quälte, rechtfertigt den Aufwand; wer Stöße nur als Teil eines Versuchs erträgt, hat dazu keinen Anlass. Das ist die sparsamste, nicht die einzig mögliche Deutung.","prueffrage":"Worin unterscheiden sich die beiden Fälle außer in der Art der Strapaze?","rueckmeldung":[{"option":0,"text":"Dass beide Ergebnisse zusammen eine Kurve ergeben, wirkt stimmig. Das Szenario nennt aber nur „schmerzhaft“ und „schwach“, nichts von einem Zuviel, und die Kurve erklärt nicht, warum Stöße ohne Aufnahmebedingung anders wirken als die Prüfung."},{"option":1,"text":"Peinlichkeit und Schmerz sind tatsächlich verschiedene Belastungen. Der Versuch unterscheidet sie aber auch darin, ob sie Voraussetzung für die Aufnahme waren, und dieser Unterschied reicht für die Erklärung, ohne eine eigene Wirkungsart anzunehmen."},{"option":2,"text":"Abfärbendes Unbehagen würde das schlechtere Urteil nach starken Stößen erklären. Dann hätte aber auch die peinliche Prüfung im ersten Versuch abfärben müssen. Dort wurde die Gruppe trotzdem besser bewertet, die Übertragung erklärt den Unterschied also nicht."}],"familie":"selbstrechtfertigung-erkennen","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Harmon-Jones, E.; Matis, S.; Angus, D. J.; Harmon-Jones, C. (2024): Does Effort Increase or Decrease Reward Valuation? Considerations from Cognitive Dissonance Theory. Psychophysiology 61(6), e14536","oeffentlich":true,"doi":"10.1111/psyp.14536","url":"https://osf.io/r7c82","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Harmon-Jones, E.; Mills, J. (2019): An Introduction to Cognitive Dissonance Theory and an Overview of Current Perspectives on the Theory. In: Harmon-Jones, E. (Hg.): Cognitive Dissonance. 2. Aufl. Washington, DC: APA, S. 3–24","oeffentlich":false,"doi":"10.1037/0000135-001"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"8e5a6e74e6efec92"}},{"id":"qx-e-008","clusterId":"E","werkstueckRef":"E.1.2","stufe":4,"question":"Was ist an diesem Schluss fehlerhaft?","options":["Er setzt voraus, dass eine klare Widerlegung den Glauben beendet. Wer viel investiert hat und Rückhalt bei anderen findet, kann sie umdeuten und den Glauben sogar verstärken.","Er urteilt zu früh. Wenig später lässt sich noch nicht erkennen, ob die Mitglieder dauerhaft an ihrem Glauben festhalten oder die Gruppe nach und nach doch wieder verlassen.","Er schließt vom Verhalten auf die Überzeugung. Ob jemand wirklich glaubt, lässt sich von außen aber kaum zuverlässig erkennen, deshalb bleibt diese Frage hier besser offen.","Er übersieht die Opfer der Mitglieder. Wer für die Vorhersage seine Arbeit und seinen Besitz aufgegeben hat, hat seinen Glauben bereits glaubhaft gezeigt, das wiegt hier mehr."],"correctIndex":0,"explanation":"Der Schluss behandelt „Widerlegung“ wie einen Schalter, der Glauben automatisch ausschaltet. Wer viel investiert hat (Arbeit, Besitz), erlebt die Widerlegung als schwer erträglichen Widerspruch; leichter, als den eigenen Irrtum einzugestehen, ist es oft, die Widerlegung umzudeuten und am Glauben festzuhalten, besonders mit Rückhalt durch andere Gläubige. Festinger, Riecken und Schachter beschrieben 1956 eine Gruppe, die für den 21. Dezember eine Flut vorhergesagt hatte: Wer nach dem Ausbleiben mit anderen zusammen war, warb eifriger als zuvor, wer allein war, gab den Glauben meist auf. Spätere Studien bestätigen vor allem das Festhalten durch Umdeuten; das verstärkte Werben gilt als schwächster Punkt der Untersuchung, und dass Gegenbeweise einen Glauben sogar verstärken, ist eher die Ausnahme. Der Fehler des Zuschauers liegt darin, das für ausgeschlossen zu halten und aus dem Festhalten auf mangelnde Überzeugung zu schließen.","coreRule":"⚡ Wer viel investiert hat und Rückhalt in einer Gruppe findet, kann eine Widerlegung umdeuten, statt sie anzunehmen. Daraus, dass jemand an einem widerlegten Glauben festhält, folgt nicht, dass er nicht wirklich überzeugt ist.","beleg":"Werkstück E.1.2 (Anwendung & Relevanz: Bei Kulten & Verschwörungsmythen); Fn. gl-e-prophezeiung (Festinger, Riecken, Schachter 1956, S. 3–4, 227–229); Fn. gl-e-luecke (Lewandowsky u. a. 2020, PDF-S. 9)","status":"entwurf","scenario":"Eine kleine Gruppe hat öffentlich vorhergesagt, an einem bestimmten Tag werde eine Flut die Welt verwüsten. Mehrere Mitglieder haben dafür ihre Arbeit aufgegeben und ihren Besitz verschenkt. Der Tag vergeht, nichts geschieht. Wenig später wirbt ein Teil der Mitglieder eifriger um neue Anhänger als zuvor. Ein Zuschauer folgert: „Wer so reagiert, glaubt gar nicht richtig. Wer wirklich überzeugt wäre, würde angesichts der Widerlegung sofort aufgeben.“","quote":"","quoteLabel":"","kurz":"Eine Widerlegung beendet einen Glauben nicht automatisch. Wer viel investiert hat und Rückhalt findet, deutet sie oft um und hält fest. Der Zuschauer schließt dagegen vom Festhalten auf fehlende Überzeugung und hält es für ausgeschlossen.","prueffrage":"Folgt aus dem eifrigeren Werben wirklich, dass die Mitglieder zweifeln, oder lässt sich ihr Verhalten auch anders lesen?","rueckmeldung":[{"option":1,"text":"Dass „wenig später“ noch wenig über die Zukunft der Gruppe sagt, stimmt. Der Schluss des Zuschauers bliebe aber auch nach Jahren falsch, denn sein Fehler liegt in der Annahme, Widerlegung beende den Glauben von selbst."},{"option":2,"text":"Dass sich Überzeugung von außen schwer erkennen lässt, ist ein vernünftiger Gedanke. Er lässt die Frage aber nur offen, statt den Kern zu treffen: Der Zuschauer hält fälschlich für ausgeschlossen, dass jemand trotz Widerlegung fest glaubt."},{"option":3,"text":"Die Opfer sind wichtig, aber an anderer Stelle: Sie erklären, warum das Umdeuten so naheliegt. Als Gegenargument taugen sie kaum, denn sie sagen nichts darüber, was eine Widerlegung mit dem Glauben macht."}],"familie":"selbstrechtfertigung-erkennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J.; Ecker, U. K. H. u. a. (2020): The Debunking Handbook 2020","oeffentlich":true,"doi":"10.17910/b7.1182","url":"https://skepticalscience.com/docs/DebunkingHandbook2020.pdf","seite":"PDF-S. 9","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Festinger, L.; Riecken, H. W.; Schachter, S. (1956): When Prophecy Fails. Minneapolis: University of Minnesota Press","oeffentlich":false},{"typ":"literatur","kurz":"Stone, J. R. (2014): Prophecy. In: Chryssides, G. D.; Zeller, B. E. (Hg.): The Bloomsbury Companion to New Religious Movements. London: Bloomsbury Academic","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"a18a0c68738cc5f0"}},{"id":"qx-e-009","clusterId":"E","werkstueckRef":"E.2.1","stufe":1,"question":"Eine Teamleiterin fragt reihum, ob ein Entwurf freigegeben werden soll. Drei Kollegen sagen nacheinander „Ja“, dann bist du an der Reihe. Du kennst die Gruppe seit Jahren und weißt, dass Widerspruch dort selten gut ankommt. Welche der folgenden Reaktionen wäre ein Fall von Konformität in dem Sinn, dass du dein Urteil dem Gruppendruck unterordnest?","options":["Du sagst „Ja“, obwohl du einen Fehler im Entwurf siehst, weil du als Einziger mit „Nein“ auffallen würdest.","Du sagst „Nein“ und nennst den Fehler klar, wählst aber vorsichtige Worte, weil Widerspruch hier selten gut ankommt.","Du sagst „Nein“, obwohl du keinen Fehler siehst, weil du in dieser Gruppe nicht einfach mitlaufen willst.","Du sagst „Ja“, weil du den Entwurf selbst gründlich gelesen hast und ihn genau wie die anderen für gelungen hältst."],"correctIndex":0,"explanation":"Konformität heißt, Verhalten oder Überzeugung an die Gruppe anzupassen, obwohl das eigene Urteil in eine andere Richtung zeigt, ausgelöst durch realen oder bloß eingebildeten Druck. Hier liegt das bei der ersten Reaktion vor: Du erkennst den Fehler und stimmst trotzdem zu, um nicht aus der Reihe zu fallen und nicht ausgegrenzt zu werden. Das ist normativer Einfluss: Du willst gemocht und akzeptiert werden, auch wenn du es besser weißt. Wer nach erneuter Prüfung zu dem Schluss kommt, dass der Entwurf in Ordnung ist, urteilt selbst; dass die Gruppe zufällig dasselbe sagt, macht das nicht zur Anpassung. Dasselbe gilt, wenn du dein Urteil schon vor den Antworten der anderen festgelegt hattest und dabei bleibst: Dein „Ja“ kommt dann aus deinem eigenen Urteil, nicht aus dem Druck der Gruppe. Wer widerspricht, tut das Gegenteil von Anpassung. Das Kennzeichen von Konformität ist also nicht, dass viele dasselbe sagen, sondern dass der Druck der Gruppe das eigene Urteil ersetzt.","coreRule":"Konformität ist die Anpassung des eigenen Verhaltens und der Überzeugungen an die Normen oder das Verhalten einer Gruppe, oft aus realem oder eingebildetem Druck. Prüfstein: Hättest du genauso entschieden, wenn du allein und ohne Blick der anderen geurteilt hättest?","beleg":"Werkstück E.2.1 (Kernidee)","status":"entwurf","scenario":"","kurz":"Konformität liegt vor, wenn der Gruppendruck dein eigenes Urteil ersetzt: Du siehst den Fehler und stimmst trotzdem zu, um nicht aufzufallen. Dass viele dasselbe sagen, macht dein „Ja“ noch nicht zur Anpassung.","prueffrage":"Was hat sich jeweils zwischen deiner eigenen Prüfung des Entwurfs und deiner lauten Antwort verändert, und wodurch?","rueckmeldung":[{"option":1,"text":"Dass du deine Worte vorsichtig wählst, zeigt, wie spürbar der Druck ist. Dein Urteil bleibt aber unverändert, und du äußerst es offen. Wer so widerspricht, passt sich gerade nicht an."},{"option":2,"text":"Auch hier lenkt die Gruppe dein Verhalten, doch Konformität heißt, sich ihr anzupassen. Wer widerspricht, tut das Gegenteil. Ob das „Nein“ sachlich trägt, ist eine andere Frage: Ein Fehler wird nicht gesehen."},{"option":3,"text":"Übereinstimmung mit der Gruppe wirkt schnell wie Mitlaufen. Hier kommt dein „Ja“ aber aus eigener gründlicher Prüfung. Dass die anderen zufällig dasselbe sagen, ersetzt dein Urteil nicht und ist keine Anpassung."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Open Social Psychology, Kap. 7: Conformity. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter21.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Asch, S. E. (1955): Opinions and Social Pressure. Scientific American 193(5) (Sonderdruck auf einer Lehrseite der University of Vermont, inoffizielle Kopie)","oeffentlich":true,"url":"https://pdodds.w3.uvm.edu/teaching/courses/2009-08UVM-300/docs/others/everything/asch1955a.pdf","seite":"PDF-S. 4","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"ea161bc536395e83"}},{"id":"qx-e-010","clusterId":"E","werkstueckRef":"E.2.1","stufe":2,"question":"Was erklärt dein Schweigen am sparsamsten, und wie lässt sich der Einfluss prüfen?","scenario":"Du bist neu im Team. In der Sitzung loben alle eine Idee, die du für fehlerhaft hältst. Du hast dir deine Einwände sogar schon zurechtgelegt, schweigst aber trotzdem, weil du fürchtest, als Einziger zu widersprechen und dafür schief angesehen zu werden. Später gibst du einer Kollegin gegenüber zu: „Ich hielt den Plan für falsch, wollte aber nicht auffallen.“","options":["Du willst im neuen Team dazugehören und Ablehnung vermeiden. Prüfen lässt sich das, indem du dein Urteil vorab schriftlich festhältst und fragst, ob du alleine im Raum genauso entscheiden würdest.","Du traust dem Team mehr Wissen zu als dir selbst. Prüfen lässt sich das, indem du fragst, welche Belege die anderen für ihr Lob haben und ob sie etwas wissen, was deinen Einwänden fehlt.","Du rechnest damit, dass jemand aus dem Team widerspricht, weil sich Verantwortung verteilt. Prüfen lässt sich das, indem du fragst, ob du auch geschwiegen hättest, wenn du allein zuständig wärst.","Du bist unsicher, ob deine Einwände überhaupt stimmen. Prüfen lässt sich das, indem du sie vorab einer vertrauten Kollegin vorlegst und fragst, ob sie einer Gegenrede standhalten."],"correctIndex":0,"explanation":"Die Sachlage spricht klar für einen normativen Einfluss: Du weißt es besser und hast deine Einwände schon formuliert, schweigst aber aus Furcht vor den Reaktionen der Gruppe. Dein Zugeständnis („wollte nicht auffallen“) zeigt dieselbe Triebfeder wie bei Aschs Linien-Versuchen, wo gerade die Angst, als Einziger aus der Reihe zu fallen, der am häufigsten genannte Grund fürs Nachgeben war. Informativer Einfluss würde bedeuten, dass du dem Urteil des Teams mehr traust als deinem eigenen. Das passt nicht, denn du hältst die Idee ja weiterhin für fehlerhaft. Verantwortungsdiffusion würde voraussetzen, dass du darauf baust, ein anderer werde für dich widersprechen; du schweigst aber, weil du selbst Ablehnung fürchtest. Auch Unsicherheit über die eigenen Einwände passt nicht, denn du hast sie schon zurechtgelegt und hieltest den Plan ausdrücklich für falsch. Auch bei eindeutiger Antwort gaben in Aschs Versuchen rund drei Viertel mindestens einmal der falschen Mehrheit nach. In einer Abwandlung des Asch-Versuchs gaben Versuchspersonen, die ihr Urteil vorher schriftlich festgehalten hatten, der falschen Mehrheit weit seltener nach. Die Kontrollfrage „Würde ich alleine genauso entscheiden?“ trennt das eigene Urteil vom Gruppendruck.","coreRule":"⚡ Wenn du es besser weißt und trotzdem schweigst, wirkt Angst vor Ausgrenzung, nicht Unsicherheit. Leg dein Urteil fest, bevor du die anderen hörst.","beleg":"Werkstück E.2.1 (Kontext & Tiefe, zwei Hauptgründe; Anti-Denkmuster); Fn. gl-e-einfluss (Deutsch & Gerard 1955, S. 629–633), gl-e-asch-gruende (Asch 1956, S. 32, 70), gl-e-selbstbindung (Deutsch & Gerard 1955, S. 632–634), gl-e-asch (Asch 1956, S. 10–11)","status":"entwurf","kurz":"Du weißt es besser und hast Einwände, schweigst aber aus Furcht, als Einziger aufzufallen. Das ist Anpassung aus Angst vor Ablehnung, nicht Zweifel am eigenen Urteil. Ob du alleine genauso entscheiden würdest, trennt Urteil und Gruppendruck.","prueffrage":"Was sagst du später der Kollegin über den Grund deines Schweigens, und was hältst du da vom Plan?","rueckmeldung":[{"option":1,"text":"Dem Team mehr zuzutrauen wäre eine plausible Erklärung für Nachgeben. Du hältst den Plan aber weiterhin für fehlerhaft, hast also gar nicht umgedacht. Vertrauen in das Wissen der anderen passt nicht zu einem Schweigen bei unverändertem Urteil."},{"option":2,"text":"Verantwortung verteilt sich in Gruppen tatsächlich oft. Das würde aber voraussetzen, dass du auf einen anderen baust, der widerspricht. Du schweigst, weil du selbst Ablehnung fürchtest, und das trägt diese Deutung nicht."},{"option":3,"text":"Eigene Einwände vorab gegenprüfen zu lassen ist ein guter Rat. Als Erklärung passt Unsicherheit aber nicht: Du hast die Einwände schon formuliert und hieltest den Plan ausdrücklich für falsch. Zweifel hat dich nicht gebremst."}],"familie":"urteil-vorab-festlegen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Asch, S. E. (1955): Opinions and Social Pressure. Scientific American 193(5) (Sonderdruck auf einer Lehrseite der University of Vermont, inoffizielle Kopie)","oeffentlich":true,"url":"https://pdodds.w3.uvm.edu/teaching/courses/2009-08UVM-300/docs/others/everything/asch1955a.pdf","seite":"PDF-S. 4–5","abruf":"2026-10-12"},{"typ":"url","kurz":"Open Social Psychology, Kap. 7: Conformity. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter21.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Deutsch, M.; Gerard, H. B. (1955): A Study of Normative and Informational Social Influences upon Individual Judgment. Journal of Abnormal and Social Psychology 51(3), S. 629–636","oeffentlich":false,"doi":"10.1037/h0046408"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"ba8e8fcab9eb33c6"}},{"id":"qx-e-011","clusterId":"E","werkstueckRef":"E.2.1","stufe":3,"question":"Du leitest diese Runde. Welche Maßnahme senkt den Konformitätsdruck am ehesten – und wie sicher darfst du dir ihrer Wirkung sein?","options":["Die erfahrenste Person äußert sich zuerst, damit sich die Runde an gesichertem Wissen ausrichtet. Sicher ist die Wirkung nur, solange die Erfahrene recht hat.","Alle stimmen offen per Handzeichen ab, damit ein öffentliches Bekenntnis Verantwortung schafft. Sicher ist die Wirkung nur, solange die Runde klein bleibt.","Die Runde diskutiert, bis alle einstimmig zustimmen, damit nur echter Konsens übrig bleibt. Sicher ist die Wirkung nur, solange lange genug diskutiert wird.","Alle halten ihr Urteil schriftlich fest, bevor die anderen sprechen, damit sie sich festlegen, ehe sie zuhören. Sicher ist die Wirkung nur begrenzt, weil sie hier aus einem frühen Versuch mit kleinen Gruppen stammt."],"correctIndex":3,"explanation":"Konformitätsdruck entsteht vor allem, wenn man unter den Augen der Gruppe antworten muss und nicht auffallen will. Wer sein Urteil festlegt, bevor er die anderen hört, nimmt dem Druck den Angriffspunkt. In einer Abwandlung des Asch-Versuchs (Deutsch & Gerard, 1955) gaben Personen, die ihre Einschätzung vorher auf einem Zettel festgehalten hatten, der falschen Mehrheit weit seltener nach. Der Befund stammt aber aus einem frühen Versuch mit nur 11 bis 15 Studierenden je Bedingung (101 insgesamt), und wer seine Notiz wieder löschte, profitierte deutlich weniger. Die Maßnahme ist also plausibel und gut begründet, ihre Stärke ist aber nicht gesichert. Offene Abstimmung und das Streben nach Einstimmigkeit verschärfen den Druck eher, weil Abweichen dann sichtbar und sozial riskant wird. Die erfahrenste Person zuerst sprechen zu lassen, liefert den anderen nur einen Anker, an dem sie sich orientieren.","coreRule":"⚡ Erst festlegen, dann zuhören: Ein schriftliches Urteil vor der Runde entzieht dem Gruppendruck den Angriffspunkt. Wie stark der Effekt ist, zeigen aber nur wenige kleine Versuche.","beleg":"Werkstück E.2.1 (Anti-Denkmuster: Die Taktik); Fn. gl-e-selbstbindung (Deutsch & Gerard 1955, S. 632–634). Gelesen 12.10.2026 im Volltext: Deutsch, M.; Gerard, H. B. (1955): A study of normative and informational social influences upon individual judgment. Journal of Abnormal and Social Psychology 51(3), 629–636, 101 Studierende der New York University, Bedingungen mit N = 11 bis 15 (Tab. 1–3); Zettel nach der Serie weggeworfen (Self-commitment) bzw. mit „Magic Pad“ gelöscht.","status":"zurueckgezogen","scenario":"Bei Entscheidungen in deiner Runde nennt zuerst jemand mit Nachdruck seine Meinung, und fast alle schließen sich an. Später räumen einzelne ein, sie hätten es eigentlich anders gesehen.","kurz":"Wer sein Urteil festhält, bevor er die anderen hört, nimmt dem Druck den Angriffspunkt. Sicher ist das aber nicht: Der Befund stammt aus einem frühen Versuch mit kleinen Gruppen, die Maßnahme ist plausibel, ihre Stärke offen.","prueffrage":"Was hält die Einzelnen in der Sitzung davon ab, ihre abweichende Sicht zu äußern, die sie später doch einräumen?","rueckmeldung":[{"option":0,"text":"Eine erfahrene Einschätzung ist oft hilfreich und kann wirklich richtig sein. Spricht sie aber zuerst, wird sie zum Anker, an dem sich alle ausrichten. Der Druck, sich anzuschließen, sinkt dadurch nicht, er bekommt nur eine Richtung."},{"option":1,"text":"Ein offenes Bekenntnis wirkt verbindlich. Wer abweicht, tut es dabei aber vor aller Augen und riskiert sozial etwas. Das verschärft den Druck eher, statt ihn zu senken, auch in einer kleinen Runde."},{"option":2,"text":"Wirklicher Konsens klingt nach dem Ziel jeder Runde. Verlangt man aber Einstimmigkeit, wird Abweichen riskant, und Zustimmung kann bloße Anpassung sein. Das verstärkt den Druck eher, auch wenn lange diskutiert wird."}],"familie":"urteil-vorab-festlegen","fertigkeit":"F5","quellen":[{"typ":"literatur","kurz":"Deutsch, M.; Gerard, H. B. (1955): A Study of Normative and Informational Social Influences upon Individual Judgment. Journal of Abnormal and Social Psychology 51(3), S. 629–636","oeffentlich":false,"doi":"10.1037/h0046408"},{"typ":"literatur","kurz":"Asch, S. E. (1956): Studies of Independence and Conformity: I. A Minority of One Against a Unanimous Majority. Psychological Monographs 70(9), Whole No. 416","oeffentlich":false,"doi":"10.1037/h0093718"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"e1ba651b87cbfa82"}},{"id":"qx-e-012","clusterId":"E","werkstueckRef":"E.2.1","stufe":4,"question":"Wie beurteilst du die Behauptung des Blogbeitrags?","options":["Sie trifft im Kern zu: 94 von 123 Personen sind rund drei Viertel, und diese Personen folgten in den kritischen Durchgängen der Mehrheit gegen ihre Augen.","Sie überdehnt die Zahl: 94 von 123 Personen gaben mindestens einmal nach, aber nur 36,8 % aller kritischen Antworten waren konform, nicht jedes Mal.","Sie lässt sich so nicht prüfen: 123 Versuchspersonen in einem einzigen Experiment sind zu wenige, um etwas über drei Viertel aller Menschen zu sagen.","Sie übertreibt: Richtig wäre, dass gut ein Drittel der Personen der Mehrheit folgte, denn 36,8 % der Antworten in den kritischen Durchgängen waren konform."],"correctIndex":1,"explanation":"Die rund drei Viertel messen „mindestens einmal nachgegeben“ (genau 76 %; 94 von 123 Personen), nicht „bei jeder Gelegenheit“. Wer eine Prozentzahl liest, muss fragen, was gezählt wurde: Personen mit mindestens einem Nachgeben oder Antworten insgesamt. Im Mittel waren nur gut ein Drittel der Antworten konform (36,8 %), und 24 % der Versuchspersonen widerstanden durchgehend. Der Blogbeitrag macht aus „mindestens einmal“ ein „immer“. Eine Replikation an der Universität Bern (Franzen & Mader 2023) fand mit 33 % falschen Antworten fast denselben Wert, die Zahl ist also kein Artefakt von 1956. Der Sog ist real, aber deutlich schwächer, als die Schlagzeile behauptet; er schwankt außerdem mit Zeit und Kultur, und schon eine einzige abweichende Stimme schwächt ihn deutlich. Wer die 94 Personen bestätigt sieht, übersieht, dass ein einziges Nachgeben schon reicht, um gezählt zu werden.","coreRule":"„Mindestens einmal nachgegeben“ ist etwas anderes als „immer nachgegeben“ – prüfe, was eine Prozentzahl tatsächlich misst.","beleg":"Werkstück E.2.1 (Abschnitt „Der Test mit den Linien“); Fn. gl-e-asch (Asch 1956, S. 10–11; Franzen & Mader 2023, S. 1 und 6–8). Franzen, A.; Mader, S. (2023): The power of social influence: A replication and extension of the Asch experiment. PLOS ONE 18(11), e0294325, https://doi.org/10.1371/journal.pone.0294325 (33 % falsche Antworten ohne Anreiz, 25 % mit Anreiz; Asch 1955: 36,8 %); gelesen 12.10.2026.","status":"entwurf","scenario":"Ein Blogbeitrag behauptet: „Drei Viertel aller Menschen folgen bei jeder Gelegenheit der Mehrheit, selbst gegen ihre eigenen Augen.“ Als Beleg nennt er das Linien-Experiment von Solomon Asch. Du schlägst die Angaben nach: 123 Versuchspersonen erlebten je zwölf kritische Durchgänge, in denen die Gruppe einstimmig eine falsche Linie nannte. 94 von ihnen gaben mindestens einmal nach, 29 nie. Von allen Antworten in den kritischen Durchgängen waren 36,8 % konform.","kurz":"Die Dreiviertel-Zahl zählt Personen, die mindestens einmal nachgaben, nicht Antworten: Insgesamt waren nur 36,8 % der kritischen Antworten konform. Der Beitrag macht aus „mindestens einmal“ ein „bei jeder Gelegenheit“.","prueffrage":"Was genau wurde hier gezählt: Personen, Antworten oder etwas anderes, und was musste dafür mindestens geschehen?","rueckmeldung":[{"option":0,"text":"Die Rechnung stimmt: 94 von 123 sind rund drei Viertel. Gezählt wurde aber, wer mindestens einmal nachgab, und das sagt wenig darüber, wie oft jemand folgte; „bei jeder Gelegenheit“ trägt die Zahl nicht."},{"option":2,"text":"Ein einzelnes Experiment mit 123 Personen ist tatsächlich eine schmale Basis für Aussagen über alle Menschen. Doch hier lässt sich die Behauptung schon an den genannten Zahlen widerlegen, und ein ähnlicher Wert ist in einer Replikation wiedergefunden worden."},{"option":3,"text":"Dass die Behauptung übertreibt, stimmt, und 36,8 % der kritischen Antworten waren konform. Das ist aber ein Anteil der Antworten, nicht der Personen: Tatsächlich gab mit 94 von 123 die große Mehrheit mindestens einmal nach."}],"familie":"zahl-zur-quelle","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Franzen, A.; Mader, S. (2023): The power of social influence: A replication and extension of the Asch experiment. PLOS ONE 18(11), e0294325","oeffentlich":true,"doi":"10.1371/journal.pone.0294325","abruf":"2026-10-12"},{"typ":"url","kurz":"Open Social Psychology, Kap. 7: Conformity. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter21.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Asch, S. E. (1956): Studies of Independence and Conformity: I. A Minority of One Against a Unanimous Majority. Psychological Monographs 70(9), Whole No. 416","oeffentlich":false,"doi":"10.1037/h0093718"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"5efe8e9a135fad04"}},{"id":"qx-e-013","clusterId":"E","werkstueckRef":"E.2.2","stufe":1,"question":"Welche Rückfrage prüft am besten, ob Marlene Brandt hier zu Recht als Autorität auftritt?","options":["Welche anderen Ursachen könnten erklären, dass Menschen, die das Mittel nehmen, seltener erkältet sind, und lassen sie sich ausschließen?","Welche Daten und Methoden stützen genau die Aussage, dass das Mittel Erkältungen verhindert, und könnten Dritte sie nachprüfen oder widerlegen?","Prüft die Redaktion des Podcasts vor der Sendung, ob Aussagen von Gästen wie Marlene Brandt zu Erkältungen sachlich stimmen, und hat sie das hier getan?","Wie viele von Brandts Kundinnen und Kunden berichten, dass sie seit der Einnahme des Mittels seltener erkältet sind, und decken sich ihre Berichte?"],"correctIndex":1,"explanation":"Echte Autorität beruht auf nachprüfbarer Kompetenz: Sie ist auf ein Fachgebiet beschränkt, ist provisorisch und offen für Kritik und lädt zur Überprüfung ein („Hier sind meine Daten, prüf sie nach.“). Marlene Brandt dagegen verlangt Vertrauen in ihre Person und weicht der Beleg-Frage aus. Die Frage nach Daten und Methoden zur konkreten Behauptung trennt beides: Sind sie vorhanden und prüfbar, ist Vertrauen ein sinnvoller Zeitgewinn; fehlen sie, bleibt nur Ausstrahlung.","coreRule":"⚡ Echte Expertise ist spezifisch, vorläufig und prüfbar – Autorität ohne diese drei Eigenschaften ist verdächtig.","beleg":"Werkstück E.2.2 (Kontext & Tiefe: Die zwei Gesichter der Autorität, Typ 1)","status":"entwurf","scenario":"In einem Podcast erklärt die Ernährungsberaterin Marlene Brandt mit großer Überzeugung, dass ein bestimmtes Nahrungsergänzungsmittel Erkältungen verhindert. Als die Moderatorin nach Belegen fragt, antwortet sie: „Ich arbeite seit 20 Jahren in dem Feld. Wer mir nicht vertraut, versteht nichts davon.“ Die Hörerin Jana überlegt, wie sie die Aussage einordnen soll.","kurz":"Echte Autorität lädt zur Überprüfung ein und zeigt Daten und Methoden zur konkreten Aussage. Brandt verlangt dagegen Vertrauen in ihre Person. Wer nach prüfbaren Belegen fragt, trennt Kompetenz von bloßer Ausstrahlung.","prueffrage":"Was antwortet Marlene Brandt genau auf die Frage nach Belegen, und was davon betrifft das Mittel selbst?","rueckmeldung":[{"option":0,"text":"Nach anderen Ursachen zu fragen ist wichtig, sobald es Daten zum Deuten gibt. Brandt nennt aber gar keine, sodass diese Frage vor der eigentlichen kommt: Wo sind die Belege, und sind sie prüfbar?"},{"option":2,"text":"Ob der Podcast Gäste prüft, sagt etwas über den Sender, aber nichts über Brandts Belege. Selbst eine gründliche Redaktion ersetzt nicht die Frage, was ihre konkrete Behauptung stützt."},{"option":3,"text":"Kundenberichte wirken nah an der Praxis. Einzelne Erfahrungen können aber Zufall oder andere Ursachen nicht von einer Wirkung des Mittels trennen und lassen sich nicht nachprüfen. Sie ersetzen keine Daten."}],"familie":"autoritaet-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"The Royal Society: History of the Royal Society („Nullius in verba“)","oeffentlich":true,"url":"https://royalsociety.org/about-us/who-we-are/history/","abruf":"2026-10-12"},{"typ":"url","kurz":"Kim, S. H.: Max Weber. Stanford Encyclopedia of Philosophy, Abschnitt 6.1 „Domination and Legitimacy“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/weber/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"76bd7993c63070b5"}},{"id":"qx-e-014","clusterId":"E","werkstueckRef":"E.2.2","stufe":2,"question":"Woran lässt sich bei diesem Auftreten am besten erkennen, dass sich die Autorität des Kanal-Betreibers nicht auf Evidenz stützt?","scenario":"Ein Kanal-Betreiber erklärt in jedem Video Politik, Medizin und Ernährung mit absoluter Gewissheit. Wer Zweifel äußert, sei „vom System gekauft“, und die Zuschauer sollen „ihm vertrauen, nicht den Fakten“.","options":["Er äußert sich zu Politik, Medizin und Ernährung, und auf so vielen Gebieten ist kaum jemand zugleich vom Fach.","Er spricht mit absoluter Gewissheit, während Fachleute, die sich auf Daten stützen, meist vorsichtiger reden.","Er verlangt Vertrauen in seine Person statt in Fakten und behandelt Zweifel an ihm als Verrat.","Er verbreitet seine Thesen in eigenen Videos, wo sie anders als in Fachzeitschriften kein Gutachter prüft."],"correctIndex":2,"explanation":"Evidenzbasierte Autorität ist spezifisch, vorläufig und lädt zur Überprüfung ein („Hier sind meine Daten, prüf sie nach“). Der Kanal-Betreiber zeigt das Gegenteil: Er verlangt Vertrauen in seine Person statt in nachprüfbare Methoden und Daten und behandelt Zweifel als Verrat.","coreRule":"⚡ Wer überall Bescheid weiß und Zweifel als Verrat behandelt, beruft sich auf Position oder Ausstrahlung, nicht auf Evidenz.","beleg":"Werkstück E.2.2 (Kontext & Tiefe: Typ 2; Red Flags)","status":"entwurf","kurz":"Entscheidend ist, wie er mit Prüfung umgeht: Er verlangt Vertrauen in seine Person statt in nachprüfbare Daten und wertet Zweifel als Verrat. Evidenzbasierte Autorität dagegen ist vorläufig und lädt zum Nachprüfen ein.","prueffrage":"Was bietet der Betreiber seinen Zuschauern an, damit sie eine seiner Aussagen selbst überprüfen können?","rueckmeldung":[{"option":0,"text":"Wer so viele Gebiete abdeckt, ist tatsächlich selten überall Fachmann. Das ist aber nur ein Hinweis auf die Breite, nicht darauf, wie er mit Belegen und Zweifeln umgeht, und darauf kommt es an."},{"option":1,"text":"Absolute Gewissheit ist ein Warnsignal, und Fachleute reden meist vorsichtiger. Doch der Ton allein sagt wenig über den Umgang mit Prüfung. Aussagekräftiger ist, ob Zweifel zugelassen oder als Verrat gewertet werden."},{"option":3,"text":"Ohne Gutachter fehlt eine Prüfstufe, das stimmt. Der eigene Kanal ist aber kein Beleg gegen Evidenz: Entscheidend ist, ob Daten und Methoden offenliegen und Zweifel willkommen sind, nicht der Ort der Veröffentlichung."}],"familie":"autoritaet-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Kim, S. H.: Max Weber. Stanford Encyclopedia of Philosophy, Abschnitt 6.1 „Domination and Legitimacy“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/weber/","abruf":"2026-10-12"},{"typ":"url","kurz":"The Royal Society: History of the Royal Society („Nullius in verba“)","oeffentlich":true,"url":"https://royalsociety.org/about-us/who-we-are/history/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"ee27d4c09e20cd9b"}},{"id":"qx-e-015","clusterId":"E","werkstueckRef":"E.2.2","stufe":3,"question":"Ein Vorgesetzter sagt einem Mitarbeiter, der Bedenken gegen eine Anweisung äußert: „Ich übernehme die volle Verantwortung. Du führst nur aus.“ Wie wirkt dieser Satz auf das Verhalten des Mitarbeiters, und warum?","options":["Er macht eher weiter, weil er sich nun als bloßes Werkzeug seines Chefs statt als moralisch Handelnder sieht.","Er macht eher weiter, weil es ihm schwerfällt, sich einer direkten Anweisung seines Vorgesetzten zu widersetzen.","Er zögert eher weiter, weil der Satz nur die Haftung regelt und an seinen Bedenken gegen die Änderung nichts ändert.","Er macht eher weiter, weil er aus der Zusage schließt, dass sein Chef die Änderung selbst für rechtens hält."],"correctIndex":0,"explanation":"Der Satz lässt die Verantwortung scheinbar bei einer anderen Person. Genau das erlaubt es dem Mitarbeiter, sich nicht mehr als moralisch Handelnden, sondern als bloßes Werkzeug der Anweisung zu sehen. In Milgrams Experimenten war diese Verantwortungsübernahme einer der Faktoren, die das extreme Verhalten förderten. Die vollständige Abgabe der Verantwortung ist zudem der Kipppunkt zum gefährlichen Gehorsam. Die Furcht um die Stelle klingt naheliegend, doch der Chef droht mit nichts, er bietet an, die Verantwortung zu tragen. Ein Gefallen mit Gegenleistung wäre ein Tausch, hier wird aber nichts verlangt oder erwidert. Dass der Chef die Änderung geprüft hätte, sagt der Satz nicht, er betrifft allein, wer geradesteht.","coreRule":"⚡ Wer Verantwortung vollständig an eine Autorität abgibt, wird vom Handelnden zum Werkzeug.","beleg":"Werkstück E.2.2 (Die situativen Faktoren des Gehorsams; Der Kipppunkt)","status":"entwurf","scenario":"Ein Mitarbeiter soll auf Anweisung seines Chefs Kundendaten ändern, was ihm nicht geheuer ist. Er zögert und sagt, er wolle dafür nicht geradestehen. Der Chef antwortet: „Ich übernehme die volle Verantwortung. Du führst nur aus.“","kurz":"Der Satz nimmt dem Mitarbeiter das Gefühl, selbst geradestehen zu müssen, und so sieht er sich als Werkzeug statt als moralisch Handelnder. Der naheliegende Fehler ist, hier Druck oder Absicherung zu vermuten, obwohl nur die Verantwortung verschoben wird.","prueffrage":"Wogegen richtete sich das Zögern des Mitarbeiters, und auf welchen Teil davon antwortet der Chef?","rueckmeldung":[{"option":1,"text":"Dass Vorgesetzte Gewicht haben, stimmt allgemein. Hier gibt es aber weder Drohung noch Druck: Der Chef bietet an, die Verantwortung zu tragen. Das Zögern löst sich durch dieses Angebot auf, nicht durch Furcht vor Folgen."},{"option":2,"text":"Rechtlich bleibt die Änderung tatsächlich dieselbe, und die Bedenken in der Sache verschwinden nicht von selbst. Das Gefühl, selbst dafür geradestehen zu müssen, nimmt der Satz dem Mitarbeiter aber ab. Genau deshalb zögert er eher weniger."},{"option":3,"text":"Dass jemand Verantwortung übernimmt, klingt nach einer sorgfältigen Prüfung. Der Satz sagt darüber aber nichts: Er betrifft allein, wer geradesteht, nicht ob die Änderung rechtens ist."}],"familie":"verantwortung-benennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Uzelac, E.; Yang, Y.-F. (2026): Obedience to Authority. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter4.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Milgram, S. (1974): Obedience to Authority: An Experimental View. New York: Harper & Row","oeffentlich":false},{"typ":"url","kurz":"Milgram, S. (1963): Behavioral Study of Obedience. Journal of Abnormal and Social Psychology 67(4), S. 371–378 (Kopie auf einer Seite der University of Miami)","oeffentlich":true,"url":"https://www.psy.miami.edu/_assets/pdf/rpo-articles/milgram-1963.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"ff22e796e45e10b8"}},{"id":"qx-e-016","clusterId":"E","werkstueckRef":"E.2.2","stufe":4,"question":"Ein Podcast sagt: „Milgram bewies: Zwei Drittel aller Menschen gehorchen immer, bis es tödlich wird.“ Was ist an dieser Aussage vor allem problematisch?","options":["Sie macht aus dem Ergebnis einer einzelnen Versuchsanordnung ein Gesetz, das angeblich in jeder Situation gilt.","Sie spricht von einem Beweis, obwohl ein psychologisches Experiment eine Annahme nur stützen, nicht beweisen kann.","Sie dramatisiert mit „bis es tödlich wird“ und erzeugt eher Angst, als sachlich über den Versuch zu informieren.","Sie nennt nur den Anteil der Gehorsamen und lässt offen, warum sich das übrige Drittel der Anweisung verweigerte."],"correctIndex":0,"explanation":"Die Zahl selbst ist belegt: In der Basisanordnung von 1963 gingen 26 von 40 Teilnehmern (65 %) bis zum 450-Volt-Schalter. Aber Milgram testete rund zwanzig Variationen, und dort schwankte die Quote zwischen null und über neunzig Prozent; die Situation (Legitimität der Autorität, Übernahme der Verantwortung, schrittweise Eskalation, Distanz zum Opfer) verschiebt sie erheblich. „Immer“ ist deshalb der Fehler: Aus einem Ergebnis unter bestimmten Bedingungen wird eine Naturkonstante gemacht, und das Gegenteil davon ist nicht „nie“, sondern „je nach Lage“. Mit der Frage „Unter welchen Bedingungen wurde das gemessen?“ lässt sich jede berühmte Zahl prüfen.","coreRule":"⚡ Eine berühmte Zahl gehört zu einer bestimmten Anordnung – ändere die Anordnung, und sie ändert sich.","beleg":"Werkstück E.2.2 (Einstieg; Situative Faktoren); Fn. gl-e-milgram (Milgram 1963, S. 371–378; Burger 2009, S. 1 f.); Fn. gl-e-milgram-varianten (Milgram 1974; Haslam & Reicher 2012)","status":"entwurf","scenario":"","kurz":"Die 65 % stammen aus einer bestimmten Anordnung, und in Milgrams Variationen lag die Quote zwischen null und über 90 %. Aus einem Ergebnis unter bestimmten Bedingungen wird so eine Konstante, obwohl die Lage den Ausschlag gibt.","prueffrage":"Wo und mit wem wurde die Zahl ermittelt, und für wen soll sie laut Podcast gelten?","rueckmeldung":[{"option":1,"text":"„Bewies“ ist bei einem Experiment tatsächlich zu stark, es kann eine Annahme nur stützen. Auch mit „zeigte“ bliebe die Aussage aber falsch, solange das „immer“ stehen bleibt. Das Hauptproblem liegt in der Verallgemeinerung."},{"option":2,"text":"„Bis es tödlich wird“ ist zugespitzt: Die Teilnehmer glaubten das nur, tatsächlich floss kein Strom. Das ist eine Frage des Tons. Der eigentliche Denkfehler liegt im „immer“ und in der Gleichsetzung einer Anordnung mit allen Situationen."},{"option":3,"text":"Warum sich manche verweigerten, wäre eine gute Anschlussfrage. Die Aussage ist aber nicht deshalb fehlerhaft, weil sie das offenlässt, sondern weil sie eine Quote aus einer Anordnung als Regel für alle Situationen ausgibt."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Milgram, S. (1963): Behavioral Study of Obedience. Journal of Abnormal and Social Psychology 67(4), S. 371–378 (Kopie auf einer Seite der University of Miami)","oeffentlich":true,"url":"https://www.psy.miami.edu/_assets/pdf/rpo-articles/milgram-1963.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Uzelac, E.; Yang, Y.-F. (2026): Obedience to Authority. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter4.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Haslam, S. A.; Reicher, S. D. (2012): Contesting the ‚Nature‘ of Conformity: What Milgram and Zimbardo’s Studies Really Show. PLOS Biology 10(11), e1001426","oeffentlich":true,"doi":"10.1371/journal.pbio.1001426","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"34d716e03ca99994"}},{"id":"qx-e-017","clusterId":"E","werkstueckRef":"E.2.3","stufe":1,"question":"Welcher Denkmechanismus erklärt das Verhalten der Passantin am besten, und was wäre die wirksamste Gegenmaßnahme?","scenario":"Auf einem vollen Bahnsteig sackt jemand zusammen. Zwanzig Menschen stehen herum, alle sehen hin, keiner bewegt sich. Eine Passantin sagt hinterher: „Ich dachte die ganze Zeit, das ist schlimm. Aber ich habe gar nicht erst gerufen, denn bei so vielen Leuten hat bestimmt schon jemand den Notruf gewählt.“","options":["Sie deutet die Ruhe der Umstehenden als Zeichen, dass nichts Ernstes vorliegt. Gegenmaßnahme: Selbst genau hinsehen, ob jemand Hilfe braucht.","Sie scheut die Blamage vor den Umstehenden, falls es kein Notfall ist. Gegenmaßnahme: Sich klarmachen, dass Fehlalarme selten bestraft werden.","Sie sieht ihre Verantwortung auf die zwanzig Anwesenden verteilt. Gegenmaßnahme: Selbst handeln oder eine Person direkt ansprechen.","Sie wartet auf eine zuständige Person, die auf dem Bahnsteig das Kommando übernimmt. Gegenmaßnahme: Sich dieser Person ausdrücklich unterordnen."],"correctIndex":2,"explanation":"Die Passantin hält die Lage ja für schlimm, sie schätzt sie also nicht als harmlos ein. Ihr Gedanke „bestimmt hat schon jemand angerufen“ zeigt, dass sie die Verantwortung auf die anderen Anwesenden abgibt: Je mehr Menschen dabei sind, desto kleiner fühlt sich der eigene Anteil an. Das nennt man Diffusion der Verantwortung. Wirksam gegen die Diffusion ist, die Verantwortung wieder zu personalisieren: selbst anpacken oder eine konkrete Person direkt ansprechen, etwa „Sie da, rufen Sie bitte den Notruf!“. Eine allgemeine Bitte um Hilfe lässt die Verantwortung dagegen weiter in der Menge verschwinden.","coreRule":"⚡ „Wird schon jemand anders tun“ – so verschwindet die eigene Verantwortung in der Menge. Gegenmittel: selbst handeln oder gezielt eine Person ansprechen.","beleg":"Werkstück E.2.3 (Kernidee; Kontext & Tiefe, drei Hauptgründe; Verbindungen)","status":"entwurf","kurz":"Die Passantin hält die Lage für schlimm und rechnet doch damit, dass jemand anderes schon gerufen hat: Je mehr Zuschauer, desto kleiner fühlt sich der eigene Anteil. Dagegen hilft, selbst zu handeln oder eine Person direkt anzusprechen.","prueffrage":"Was sagt die Passantin selbst darüber, wie sie die Lage einschätzt, und worauf stützt sie ihre Entscheidung, nicht zu rufen?","rueckmeldung":[{"option":0,"text":"Dass Ruhe der anderen als Entwarnung gelesen wird, kommt vor. Hier passt es aber nicht: Die Passantin hielt die Lage die ganze Zeit für schlimm. Ihr Grund ist die Annahme, es habe schon jemand gerufen."},{"option":1,"text":"Die Angst vor einem Fehlalarm bremst tatsächlich viele Menschen. Die Passantin nennt aber einen anderen Grund: Sie rechnet damit, dass bei so vielen Leuten schon jemand den Notruf gewählt hat."},{"option":3,"text":"Auf eine Autorität zu warten ist eine eigene Form, Verantwortung abzugeben. Die Passantin erwartet aber keine Anweisung, sondern glaubt, dass schon jemand gehandelt hat. Sich unterzuordnen würde daran nichts ändern."}],"familie":"verantwortung-benennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Barleben, L.; O’Mahony, A. (2026): Bystander Effect. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter13.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Bundeskriminalamt Österreich (2024): Mehr Zivilcourage – 6 Tipps für den Ernstfall. Wien","oeffentlich":true,"url":"https://www.bundeskriminalamt.at/212/service/files/200_2024_broschuere_zivilcourage_a5_v20240624_ansicht.pdf","seite":"S. 7","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Fischer, P.; Krueger, J. I.; Greitemeyer, T. u. a. (2011): The bystander-effect: A meta-analytic review on bystander intervention in dangerous and non-dangerous emergencies. Psychological Bulletin 137(4), S. 517–537","oeffentlich":false,"doi":"10.1037/a0023304"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"4454c0675b316d0f"}},{"id":"qx-e-018","clusterId":"E","werkstueckRef":"E.2.3","stufe":2,"question":"Was ist an diesem Vorgehen das Hauptproblem – und was wäre die wirksamere Alternative?","options":["Der Ruf richtet sich an niemanden Bestimmten, daher fühlen sich die Passanten nur zum Teil zuständig. Wirksamer wäre es, eine einzelne Person direkt mit einer konkreten Bitte anzusprechen.","Ein einzelner Ruf ist schnell vorbei, daher gehen die Passanten nach einem kurzen Blick weiter. Wirksamer wäre es, den Ruf mehrmals hintereinander zu wiederholen, bis endlich jemand stehen bleibt.","Weil alle ringsum ruhig wirken, halten die Passanten den Sturz für harmlos. Wirksamer wäre es, so zu rufen, dass die Dringlichkeit unüberhörbar wird, etwa mit dem Ruf „Notfall!“.","Der Ruf sagt nicht, welche Hilfe er braucht, daher wissen die Passanten nicht, was zu tun ist. Wirksamer wäre es, laut in die Menge zu rufen, jemand solle bitte einen Krankenwagen holen."],"correctIndex":0,"explanation":"Wer „Kann mir jemand helfen?“ ruft, macht niemanden persönlich zuständig: Jeder kann denken, ein anderer werde schon helfen, und die gefühlte Verantwortung verteilt sich auf alle Anwesenden. Dass alle ruhig bleiben, wirkt zudem wie ein Signal, dass nichts Schlimmes passiert ist. Wer eine einzelne Person direkt anspricht und ihr eine konkrete Bitte nennt, personalisiert die Verantwortung und macht Hilfe wahrscheinlicher. Das Prinzip gilt auch für Zeugen: die Führung übernehmen und Aufgaben verteilen („Ich kümmere mich um den Verletzten, können Sie bitte den Notruf wählen?“). Dass der Ruf im Lärm untergeht, klingt plausibel, passt aber nicht dazu, dass einige Passanten kurz hinschauen, er wurde also gehört. Die Angst, etwas falsch zu machen oder haftbar zu werden, ist ein bekanntes Hindernis, im Szenario gibt es dafür aber keinen Hinweis. Eine Unterstellung wie Trunkenheit kann Hilfsbereitschaft bremsen, wird hier aber nicht angedeutet, und der Mann bittet ausdrücklich um Hilfe.","coreRule":"⚡ Aus „Kann mir jemand helfen?“ wird „Sie da, rufen Sie bitte den Notarzt“ – Verantwortung braucht einen Namen.","beleg":"Werkstück E.2.3 (Das Anti-Denkmuster: Wenn du Hilfe brauchst; Wenn du Zeuge bist)","status":"entwurf","scenario":"Ein Mann stürzt in einer belebten Fußgängerzone und kann sich nicht mehr aufrichten. Vor Schmerzen ruft er laut in die Menge: „Kann mir bitte jemand helfen?“ Dutzende Menschen gehen vorbei, einige schauen kurz hin, niemand bleibt stehen. Alle wirken ruhig.","kurz":"Wer „jemand“ ruft, macht niemanden zuständig, und jeder kann denken, ein anderer werde schon helfen. Wirksamer ist es, eine einzelne Person direkt anzusprechen und ihr eine konkrete Bitte zu nennen.","prueffrage":"Wie viele Menschen hören den Ruf, woran ist zu erkennen, dass sie ihn bemerkt haben, und was tun sie dann?","rueckmeldung":[{"option":1,"text":"Wiederholung kann Aufmerksamkeit wecken, aber der Ruf bleibt an alle gerichtet. Gehört wurde er ohnehin, einige schauen hin; was fehlt, ist jemand, der sich persönlich zuständig fühlt."},{"option":2,"text":"Dass alle ruhig wirken, kann tatsächlich wie ein Signal wirken, dass nichts Schlimmes passiert ist. Ein dringlicherer Ruf wendet sich aber weiter an alle und macht niemanden zuständig, und genau das ist das Hauptproblem."},{"option":3,"text":"Eine konkrete Bitte ist hilfreich, und „Krankenwagen holen“ ist sogar eine sinnvolle Aufgabe. Wird sie aber wieder in die Menge gerufen, bleibt unklar, wer gemeint ist. Außerdem hat der Mann klar um Hilfe gebeten, sodass es daran nicht lag."}],"familie":"verantwortung-benennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Bundeskriminalamt Österreich (2024): Mehr Zivilcourage – 6 Tipps für den Ernstfall. Wien","oeffentlich":true,"url":"https://www.bundeskriminalamt.at/212/service/files/200_2024_broschuere_zivilcourage_a5_v20240624_ansicht.pdf","seite":"S. 7","abruf":"2026-10-12"},{"typ":"url","kurz":"Barleben, L.; O’Mahony, A. (2026): Bystander Effect. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter13.html","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"7529b7554dff4165"}},{"id":"qx-e-019","clusterId":"E","werkstueckRef":"E.2.3","stufe":3,"question":"Wie solltest du mit dieser Behauptung umgehen und warum?","options":["Die Geschichte ist als erledigt zu betrachten, denn die Prüfung der Gerichtsakten hat ihre Kernpunkte widerlegt; ihre weite Verbreitung in Lehrbüchern sagt nichts über ihre Richtigkeit.","Die Geschichte bleibt im Kern bestehen, denn dass sich die Zahl 38 nicht belegen lässt, betrifft nur ein Detail, nicht die Aussage, dass viele zusahen und niemand half.","Die Geschichte bleibt vorerst gültig, denn die Beweislast liegt bei dem, der eine seit Jahrzehnten gelehrte Aussage bestreitet, und eine einzelne Aktenprüfung reicht dafür nicht.","Die Geschichte ist erledigt, und damit gilt auch als widerlegt, dass Menschen in größeren Gruppen seltener helfen, denn die Akten zeigen, dass Anwohner durchaus eingriffen."],"correctIndex":0,"explanation":"Eine Behauptung wird nicht dadurch wahr, dass sie oft wiederholt wird. Entscheidend ist, ob sie einer Prüfung an den Quellen standhält. Die Auswertung der Gerichtsakten zeigte: Kaum jemand konnte den Angriff als Ganzes sehen, mindestens zwei Anwohner riefen die Polizei, eine Nachbarin lief hinunter und hielt die Sterbende im Arm, bis der Rettungswagen kam, und die Zahl 38 stammt aus keiner belegbaren Zählung. Die Erzählung ist damit in ihren Kernpunkten falsch. Dass sie trotzdem zur Gründungsgeschichte der Forschung darüber wurde, wann Zuschauer eingreifen, zeigt nur, wie zählebig eine eingängige Geschichte ist. Ob Menschen in Gruppen seltener helfen, muss man an anderen Belegen prüfen, etwa an kontrollierten Experimenten, nicht an dieser Erzählung. Dass nur die Zahl 38 wackelt, stimmt nicht: Auch das Wegsehen aller und das Ausbleiben von Hilfe sind durch die Akten widerlegt. Die Beweislast bei dem zu sehen, der eine alte Aussage bestreitet, hilft nicht weiter, denn die Akten sind genau dieser Beleg. Die Akten widerlegen die Erzählung, aber nicht den Befund aus Experimenten, dass Menschen in größeren Gruppen seltener helfen.","coreRule":"⚡ Eine eingängige Geschichte ist kein Beleg – auch ein oft wiederholter Klassiker kann ein Mythos sein; prüfe die Quelle, nicht die Verbreitung.","beleg":"Werkstück E.2.3 (Einstieg); Fn. gl-e-genovese (Manning, Levine, Collins 2007, S. 555–562; Gansberg 1964, NYT)","status":"entwurf","scenario":"In einem Seminar sagt jemand: „Es ist bewiesen, dass 38 Menschen in New York einen Mord beobachtet und alle weggesehen haben. Das zeigt, wie herzlos Großstädter sind.“ Er beruft sich darauf, dass diese Geschichte in vielen Lehrbüchern steht und seit Jahrzehnten erzählt wird. Eine Nachprüfung der Gerichtsakten ergab später: Kaum jemand konnte den Angriff als Ganzes sehen, mindestens zwei Anwohner riefen die Polizei, und eine Nachbarin hielt die Sterbende im Arm, bis der Rettungswagen kam. Die Zahl 38 stammt aus keiner belegbaren Zählung.","quote":"","quoteLabel":"","kurz":"Eine Behauptung wird nicht wahr, weil man sie oft wiederholt, sondern wenn sie an den Quellen standhält. Hier hielten die Gerichtsakten den Kernpunkten nicht stand: Kaum jemand sah den ganzen Angriff, und es wurde geholfen.","prueffrage":"Welche Teile der Geschichte bleiben stehen, wenn man nur gelten lässt, was sich an den Akten belegen lässt?","rueckmeldung":[{"option":1,"text":"Dass sich die Zahl 38 nicht belegen lässt, wirkt wie ein Nebenpunkt. Die Akten widersprechen aber auch dem Kern: Kaum jemand sah den ganzen Angriff, mehrere Anwohner riefen Hilfe, und eine Nachbarin hielt die Sterbende im Arm."},{"option":2,"text":"Eine Aussage, die seit Jahrzehnten gelehrt wird, wirkt gesichert, und Vorsicht gegenüber Einzelbefunden ist grundsätzlich sinnvoll. Hier sind die Akten aber der Beleg selbst, während für die Erzählung nur ihre Wiederholung spricht, keine Quelle."},{"option":3,"text":"Dass die Erzählung nicht trägt, stimmt. Daraus folgt aber nichts über Gruppen allgemein: Ob Menschen dort seltener helfen, zeigen andere Belege wie kontrollierte Experimente. Diesen Befund berühren die Akten nicht."}],"familie":"lehrgeschichte-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Clark, R. P. (2016): Misremembering Kitty Genovese. Poynter Institute","oeffentlich":true,"url":"https://www.poynter.org/reporting-editing/2016/misremembering-kitty-genovese/","abruf":"2026-10-12"},{"typ":"url","kurz":"Barleben, L.; O’Mahony, A. (2026): Bystander Effect. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter13.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Manning, R.; Levine, M.; Collins, A. (2007): The Kitty Genovese Murder and the Social Psychology of Helping: The Parable of the 38 Witnesses. American Psychologist 62(6), S. 555–562","oeffentlich":false,"doi":"10.1037/0003-066X.62.6.555"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"6ed0c9b48b211d45"}},{"id":"qx-e-020","clusterId":"E","werkstueckRef":"E.2.3","stufe":4,"question":"Ein Kollege sagt zur Klimakrise: „Es gibt so viele andere, was kann ich als Einzelner schon tun?“ Welcher psychologische Mechanismus steckt am ehesten hinter diesem Gedanken?","options":["Pluralistische Ignoranz: Jeder hält das Problem insgeheim für harmlos, weil alle anderen nach außen ruhig bleiben.","Eine besonders starke Wirkung des Zuschauereffekts: Je mehr Menschen anwesend sind, desto weniger greift in einem Notfall überhaupt noch jemand ein.","Eine realistische Einschätzung: Diffusion der Verantwortung tritt nur bei Notfällen mit direkter Lebensgefahr auf und passt hier nicht.","Diffusion der Verantwortung: Bei einem riesigen Problem mit vielen Beteiligten verteilt sich das Verantwortungsgefühl, die eigene Rolle wirkt winzig."],"correctIndex":3,"explanation":"Der Satz zeigt das Muster der verteilten Verantwortung: Wenn ein Problem riesig ist und sehr viele andere ebenfalls betroffen sind, fühlt sich der Einzelne nur noch für einen winzigen Anteil zuständig und denkt, jemand anderes werde schon etwas tun. Das ist die gleiche Logik wie bei einem Unfall mit vielen Umstehenden. Die Annahme der Pluralistischen Ignoranz passt nicht, denn der Kollege hält das Problem nicht für harmlos, sondern seinen eigenen Beitrag für bedeutungslos. Auch die Behauptung, in großen Gruppen greife meist niemand mehr ein, trägt nicht: Der Zuschauereffekt beschreibt nur, dass die Wahrscheinlichkeit sinkt, dass eine einzelne Person hilft. In gefilmten Konflikten im öffentlichen Raum (219 Fälle in drei Ländern, Philpot u. a. 2020) griff in gut neun von zehn Fällen mindestens ein Umstehender ein. Und dass der Mechanismus nur bei Notfällen mit direkter Lebensgefahr auftrete, widerspricht dem Buch: Es nennt „Was kann ich als Einzelner schon tun?“ ausdrücklich als klassischen Gedanken der diffundierten Verantwortung bei großen gesellschaftlichen Problemen.","coreRule":"⚡ „Was kann ich als Einzelner schon tun?“ ist der Satz, mit dem Verantwortung verteilt wird und verschwindet.","beleg":"Werkstück E.2.3 (Anwendung & Relevanz: Bei großen gesellschaftlichen Problemen); Fn. gl-e-philpot (Philpot u. a. 2020, American Psychologist 75(1), S. 66–75)","status":"entwurf","scenario":"In einer Gesprächsrunde wird über die Klimakrise gesprochen. Ein Kollege winkt ab: „Es gibt so viele andere, was kann ich als Einzelner schon tun?“","quote":"","quoteLabel":"","kurz":"Wenn ein Problem riesig ist und viele betroffen sind, schrumpft das eigene Zuständigkeitsgefühl auf einen winzigen Anteil, und man denkt, andere werden es schon richten. Der Kollege hält die Krise nicht für harmlos, er hält nur seinen Beitrag für bedeutungslos.","prueffrage":"Ist in dem Satz von einem akuten Notfall die Rede, und was sagt der Kollege über die Gefahr selbst?","rueckmeldung":[{"option":0,"text":"Dass andere ruhig bleiben, kann tatsächlich dazu verleiten, eine Lage für harmlos zu halten. Der Kollege nennt die Krise aber nicht harmlos; er bezweifelt nur, dass sein eigener Beitrag etwas ausrichtet."},{"option":1,"text":"Hier steckt ein wahrer Kern: Mit der Zahl der Anwesenden sinkt die Chance, dass eine einzelne Person hilft. Daraus folgt aber nicht, dass überhaupt niemand mehr eingreift. In Studien zu realen Konflikten griff meist mindestens ein Umstehender ein."},{"option":2,"text":"Die klassischen Experimente dazu stellten tatsächlich Notfälle nach. Verteilte Verantwortung kann aber überall wirken, wo viele beteiligt sind und jeder denkt, die anderen kümmern sich, auch bei großen gesellschaftlichen Problemen wie dem Klima."}],"familie":"verantwortung-benennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Philpot, R.; Liebst, L. S.; Levine, M.; Bernasco, W.; Lindegaard, M. R. (2020): Would I Be Helped? Cross-National CCTV Footage Shows That Intervention Is the Norm in Public Conflicts. American Psychologist 75(1), S. 66–75 (Manuskriptfassung, Lancaster University)","oeffentlich":true,"doi":"10.1037/amp0000469","url":"https://eprints.lancs.ac.uk/id/eprint/134891/1/Would_I_be_Helped_Cross_National_CCTV_Footage_Shows_That_Intervention_Is_the_Norm_in_Public_Conflicts_Postprint.pdf","seite":"PDF-S. 2","abruf":"2026-10-12"},{"typ":"url","kurz":"Barleben, L.; O’Mahony, A. (2026): Bystander Effect. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter13.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"9e113021368ce587"}},{"id":"qx-e-021","clusterId":"E","werkstueckRef":"E.2.4","stufe":2,"question":"Mit welcher Planung sorgst du am ehesten dafür, dass die Aufmerksamkeit der Gruppe zur Tragweite der Themen passt?","scenario":"Du leitest die Budgetrunde deines Vereins. Auf der Tagesordnung stehen der Kauf eines neuen Vereinsheims für 400.000 Euro und die Farbe des Kaffeeautomaten für 300 Euro. Aus früheren Sitzungen weißt du: Über die Farbe des Automaten wird erfahrungsgemäß lange und hitzig gestritten, beim Vereinsheim herrscht meist Schweigen, und der Kauf wird nach wenigen Minuten abgenickt.","options":["Du begrenzt jede Wortmeldung zum Kaffeeautomaten und zum Vereinsheim auf wenige Minuten, damit kein einzelnes Mitglied die Aussprache dominiert.","Du beginnst mit dem Kaffeeautomaten als kleinstem Punkt, damit die Gruppe mit einem schnellen Erfolg warm wird und Vertrauen für das Vereinsheim aufbaut.","Du legst vorab für Vereinsheim und Kaffeeautomat je ein festes Zeit-Budget fest, das sich an Kosten und Folgen des Themas orientiert.","Du gibst Vereinsheim und Kaffeeautomat je dieselbe Zeit, damit sich bei keinem der beiden Punkte ein Mitglied übergangen fühlt."],"correctIndex":2,"explanation":"Das Muster beschrieb C. Northcote Parkinson 1957 als „Gesetz der Trivialität“, heute ist es auch als „Bikeshedding“ bekannt: Die Zeit, die eine Gruppe auf einen Punkt verwendet, verhält sich umgekehrt zur Summe, um die es geht. Ein Teil der Erklärung liegt bei den Menschen: Beim Kaffeeautomaten kann jeder mitreden und sich risikofrei einbringen, beim 400.000-Euro-Kauf schweigt man lieber, um sich nicht mit einer „dummen“ Frage zu blamieren. Ein vorab festgelegtes Zeit-Budget nach Kosten und Folgen lenkt die Aufmerksamkeit dorthin, wo viel auf dem Spiel steht. Eine Redezeitbegrenzung bremst einzelne Vielredner, verteilt die Zeit aber nicht nach Tragweite, denn der Kaffeeautomat bliebe mit vielen kurzen Beiträgen weiter ein Dauerthema. Mit dem kleinsten Punkt zu beginnen wärmt nur auf, wenn er kurz bleibt; hier ist er aber genau der Punkt, an dem sich die Runde festbeißt. Gleiche Zeit für beide Punkte klingt gerecht, ignoriert aber, dass 300 Euro und 400.000 Euro nicht gleich viel Aufmerksamkeit verdienen.","coreRule":"⚡ Die Redezeit gehört dorthin, wo die Folgen liegen, nicht dorthin, wo jeder mitreden kann.","beleg":"Werkstück E.2.4 (Das Härten im Feuer: Aktivierungs-Frage und Schmiede-Übung)","status":"entwurf","kurz":"Ein vorab festgelegtes Zeit-Budget nach Kosten und Folgen lenkt die Aufmerksamkeit dorthin, wo viel auf dem Spiel steht. Sonst gilt das Gesetz der Trivialität: Beim Kaffeeautomaten redet jeder mit, beim Vereinsheim schweigt man.","prueffrage":"Wie verteilte sich die Redezeit in früheren Sitzungen auf Automat und Vereinsheim, und ergab sich das von selbst oder nach Plan?","rueckmeldung":[{"option":0,"text":"Eine Redezeitbegrenzung bremst Vielredner, das stimmt. Sie sagt aber nichts darüber, wie viel Zeit jeder Punkt bekommt: Der Automat bliebe mit vielen kurzen Beiträgen ein Dauerthema, beim Vereinsheim schwiege man weiter."},{"option":1,"text":"Ein schneller Erfolg zum Aufwärmen kann helfen, wenn der Punkt kurz bleibt. Genau der Automat ist aber der Punkt, an dem sich die Runde festbeißt, und die Zeit fehlt dann beim 400.000-Euro-Kauf."},{"option":3,"text":"Gleiche Zeit klingt gerecht, behandelt aber 300 und 400.000 Euro gleich. Für den Automaten wäre das zu viel Zeit, für das Vereinsheim eher zu wenig. Gerecht ist hier eine Zeit, die der Tragweite folgt."}],"familie":"aufmerksamkeit-nach-folgen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Wikipedia: Law of triviality (Sekundärquelle)","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Law_of_triviality","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Parkinson, C. N. (1957): Parkinson's Law, and Other Studies in Administration. Boston: Houghton Mifflin, Kap. „High Finance, or The Point of Vanishing Interest“","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"31e37b73d62d60cb"}},{"id":"qx-e-022","clusterId":"E","werkstueckRef":"E.2.4","stufe":3,"question":"Du leitest ein Team, das sich zwei Stunden lang über die Gestaltung des Firmenlogos auf den Kaffeetassen gestritten hat. Die Frage, ob ein Lieferant für 1,2 Millionen Euro beauftragt wird, hat die Runde dagegen in drei Minuten ohne Rückfragen durchgewunken. Gegen solche Detaildebatten ist an sich nichts einzuwenden. Woran erkennst du, dass die Diskussion hier ein echtes Problem geworden ist?","options":["Daran, dass beim Lieferanten niemand eine Rückfrage stellte, denn eine Entscheidung, zu der keine einzige Nachfrage kommt, ist nicht ausreichend geprüft.","Daran, dass das Tassenlogo zwei Stunden in Anspruch nahm, denn so viel Zeit für eine Nebensache zeigt, dass die Sitzung schlecht geleitet wurde.","Daran, dass der Vertrag über 1,2 Millionen Euro in drei Minuten beschlossen wurde, denn eine so hohe Summe verlangt eine längere Beratung.","Daran, dass die Aufmerksamkeit unproportional zur Bedeutung verteilt ist, denn das Logo bindet die Denkkraft, während der Vertrag ungeprüft bleibt."],"correctIndex":3,"explanation":"Eine kurze Detaildebatte kann nützlich sein: Ein lösbares kleines Problem gibt der Gruppe ein schnelles Erfolgserlebnis, schafft Vertrauen und wärmt für schwierigere Themen auf. Schädlich wird es erst, wenn die Zeit nicht mehr im Verhältnis zur Tragweite der Themen steht. Dann ist die gemeinsame Denkkraft an Belangloses gebunden, während Entscheidungen mit hohen Kosten und möglichen Folgeschäden unbesehen durchgehen. Das Warnsignal ist also nicht, dass Details besprochen werden, sondern ein Missverhältnis: am hitzigsten bei den einfachen Themen, am ruhigsten bei den komplexen.","coreRule":"⚡ Aufwärmen ist erlaubt – ein Problem wird es, wenn die Gruppe nie darüber hinauskommt.","beleg":"Werkstück E.2.4 (Das Adaptive Talent; Der Kipppunkt; Red Flags)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Entscheidend ist das Missverhältnis: Das Logo bindet zwei Stunden Denkkraft, während der Vertrag über 1,2 Millionen ungeprüft durchgeht. Weder ein Detail noch eine kurze Beratung ist für sich das Problem, sondern die Verteilung im Verhältnis zur Tragweite.","prueffrage":"Was stünde auf dem Spiel, wenn das Tassenlogo misslingt, und was, wenn der falsche Lieferant den Auftrag bekommt?","rueckmeldung":[{"option":0,"text":"Ausbleibende Rückfragen sind ein Hinweis, mehr nicht: Auch eine gut vorbereitete Entscheidung kann ohne Nachfrage durchgehen. Auffällig wird es erst im Vergleich zur Logo-Debatte, also am Missverhältnis zwischen Aufwand und Tragweite."},{"option":1,"text":"Zwei Stunden für eine Nebensache wirken wie ein Leitungsfehler. Eine längere Detaildebatte kann aber durchaus nützlich sein, etwa als Erfolgserlebnis oder Aufwärmen. Zum Problem wird sie erst im Verhältnis zur Tragweite der anderen Themen."},{"option":2,"text":"Bei 1,2 Millionen Euro scheinen drei Minuten zu wenig, und oft stimmt das auch. Eine feste Mindestdauer für hohe Summen gibt es aber nicht; entscheidend ist, ob die Zeit im Verhältnis zur Tragweite der Themen verteilt wurde."}],"familie":"aufmerksamkeit-nach-folgen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Wikipedia: Law of triviality (Sekundärquelle)","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Law_of_triviality","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Parkinson, C. N. (1957): Parkinson's Law, and Other Studies in Administration. Boston: Houghton Mifflin, Kap. „High Finance, or The Point of Vanishing Interest“","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"1f15d27c1e6c341e"}},{"id":"qx-e-023","clusterId":"E","werkstueckRef":"E.2.4","stufe":4,"question":"Du liest in einem Forum: Seit Tagen füllen Mitglieder Seite um Seite mit der Frage, ob ein gefilmter Lichtpunkt einen Bogen von 12 oder 15 Grad beschreibt. Ob die Theorie überhaupt mit der Physik vereinbar ist, fragt niemand. Welche Einordnung passt am besten zu dem, was du siehst?","options":["Die Gruppe verhandelt ausgiebig ein kleines, für alle greifbares Detail und umgeht damit die schwierige Frage, an der die ganze Theorie hängt.","Die Gruppe prüft die Theorie gründlich, denn wer eine Aufnahme bis auf wenige Grad genau vermisst, nimmt die Belege ernst und glaubt nicht blind.","Die Gruppe hat sich in einer Nebensache verloren, wie es in langen Forendebatten oft geschieht; dass die Physik fehlt, ist eher Zufall als Muster.","Die Gruppe klärt zuerst die Messung, denn solange der Bogen umstritten ist, lässt sich die Frage nach der Physik kaum sinnvoll beantworten."],"correctIndex":0,"explanation":"Hier verteilt sich die Aufmerksamkeit umgekehrt zur Bedeutung der Themen: Über das Detail kann jeder mitreden, es ist konkret, ungefährlich und bietet eine Bühne. Die physikalische Gesamtfrage ist anstrengend und riskant, denn wer sie stellt, könnte die eigene Unwissenheit preisgeben. Deshalb wird dort geschwiegen, wo es zählt. Die zweite Deutung scheitert, weil eine gründliche Prüfung irgendwo sichtbar sein müsste, im Beispiel aber gerade fehlt. Die dritte unterstellt, alle zweifelten privat; im Beispiel steht davon nichts, und das Verhalten wird durch die einfache Verteilung der Aufmerksamkeit besser erklärt. Die vierte unterstellt, andere hätten die Frage beantwortet, obwohl nirgends davon die Rede ist. Als nächsten Schritt kannst du fragen: Wie viel Diskussionszeit entfällt auf das Detail, und wie viel auf die Frage, ob das Ganze überhaupt stimmen kann?","coreRule":"⚡ Wer nur über Details streitet, die jeder versteht, umgeht oft gerade die Frage, an der alles hängt.","beleg":"Werkstück E.2.4 (Anwendung & Relevanz: In Verschwörungsgemeinschaften; Verbindungen)","status":"entwurf","scenario":"","kurz":"Über 12 oder 15 Grad kann jeder mitreden: konkret, ungefährlich, mit Bühne. Die Frage, ob die Theorie zur Physik passt, ist anstrengend und riskant, also bleibt sie unausgesprochen, obwohl an ihr alles hängt.","prueffrage":"Was müsste im Forum zu finden sein, wenn die physikalische Frage längst geklärt wäre, und findet es sich dort?","rueckmeldung":[{"option":1,"text":"Genaues Messen wirkt wie Sorgfalt. Eine Prüfung der Theorie wäre aber sichtbar, etwa als Frage nach der Vereinbarkeit mit der Physik, und genau die taucht im Forum nirgends auf."},{"option":2,"text":"Dass Debatten in Nebensachen abdriften, kommt vor. Hier sprechen Tage und Seiten für ein Muster: Das Detail ist greifbar und ungefährlich, die Physikfrage riskant, und die Aufmerksamkeit folgt diesem Gefälle."},{"option":3,"text":"Erst die Messung zu klären klingt methodisch. Im Szenario steht aber nichts davon, dass die Physikfrage danach folgen soll, und sie ließe sich ohnehin stellen, egal ob der Bogen 12 oder 15 Grad misst."}],"familie":"aufmerksamkeit-nach-folgen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Wikipedia: Law of triviality (Sekundärquelle)","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Law_of_triviality","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Parkinson, C. N. (1957): Parkinson's Law, and Other Studies in Administration. Boston: Houghton Mifflin, Kap. „High Finance, or The Point of Vanishing Interest“","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"ed5d0b6466e54bbe"}},{"id":"qx-e-024","clusterId":"E","werkstueckRef":"E.2.5","stufe":1,"question":"In einer Abteilung gilt seit Jahren die Regel, Entscheidungen erst nach drei Abstimmungsrunden zu treffen. Bei einer anonymen Umfrage stellt sich heraus: Fast alle halten die Regel privat für überflüssig, jeder dachte aber, die anderen fänden sie sinnvoll. Was beschreibt diese Lage am besten?","options":["Eine Mehrheit der Abteilung befolgt die Drei-Runden-Regel öffentlich, obwohl sie sie privat ablehnt, weil sie fälschlich annimmt, die anderen stünden dahinter.","Eine Minderheit der Abteilung passt sich öffentlich der offen geäußerten Mehrheitsmeinung zur Drei-Runden-Regel an, obwohl sie privat anders denkt.","Die Mitarbeiter befolgen die Drei-Runden-Regel aus Gehorsam gegenüber einer Anweisung der Leitung, obwohl sie sie privat ablehnen und nichts dagegen äußern.","Die Abteilung hält aus Gewohnheit an der Drei-Runden-Regel fest, weil jede Änderung riskanter erscheint als einige überflüssige Abstimmungsrunden."],"correctIndex":0,"explanation":"Typisch für diese Lage ist die Lücke zwischen privater Überzeugung und öffentlichem Verhalten. Jeder sieht nur das konforme Verhalten der anderen und deutet es fälschlich als deren echte Meinung. Das eigene Mitmachen wird dann von den anderen wiederum als Beleg gelesen, dass „alle“ die Regel stützen, und die Illusion verstärkt sich selbst. Anders als bei gewöhnlicher Konformität, wo sich eine Minderheit an eine tatsächliche Mehrheitsmeinung anpasst, passt sich hier eine Mehrheit an eine nur eingebildete Mehrheitsmeinung an. Die anonyme Umfrage ist das passende Prüfwerkzeug: Sie macht die privaten Überzeugungen sichtbar, die das öffentliche Schweigen verdeckt. Eine offen geäußerte Mehrheitsmeinung gibt es hier gerade nicht, denn niemand hat die Regel je kritisiert oder verteidigt. Von einer Anweisung der Leitung ist keine Rede. Gewohnheit könnte das Festhalten erklären, nicht aber die falsche Annahme über die anderen, die hier den Kern bildet.","coreRule":"⚡ Wenn alle schweigen oder mitmachen, weißt du noch nicht, was sie denken. Prüfe die private Überzeugung, nicht nur das sichtbare Verhalten.","beleg":"Werkstück E.2.5 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"Eine Abteilung hält an einer umständlichen Abstimmungsregel fest. Niemand hat sie je offen kritisiert. Erst die anonyme Umfrage zeigt, dass fast alle sie ablehnen.","kurz":"Fast alle lehnen die Regel privat ab, nehmen aber an, die anderen stünden dahinter, und stützen so mit ihrem Mitmachen den Anschein einer Zustimmung, die es nicht gibt. Der Fehler: Verhalten der anderen wird als deren echte Meinung gedeutet.","prueffrage":"Was wissen die Beteiligten über die tatsächliche Meinung der anderen, und woran würdest du das erkennen?","rueckmeldung":[{"option":1,"text":"Anpassung gegen die eigene Überzeugung gibt es hier tatsächlich. Dabei fügt sich aber keine Minderheit einer offen geäußerten Mehrheitsmeinung: Fast alle machen mit, und eine solche Meinung hat nie jemand geäußert."},{"option":2,"text":"Privat lehnen alle die Regel ab und schweigen, das stimmt. Eine Anweisung der Leitung nennt das Szenario jedoch nicht. Treibende Kraft ist die Annahme, die anderen fänden die Regel sinnvoll, nicht Gehorsam."},{"option":3,"text":"Gewohnheit kann erklären, warum eine Regel lange bleibt. Sie erklärt aber nicht, warum jeder die anderen für Befürworter hält. Genau diese falsche Annahme macht die Lage aus, nicht eine Abwägung von Risiken."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Schroeder, C. M.; Prentice, D. A. (1998): Exposing Pluralistic Ignorance to Reduce Alcohol Use Among College Students. Journal of Applied Social Psychology 28(23), S. 2150–2180 (Kopie Stanford SPARQ)","oeffentlich":true,"url":"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/schroeder_prentice_1998_-_exposing_pluralistic_ignorance.pdf","seite":"S. 2151–2153","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Prentice, D. A.; Miller, D. T. (1993): Pluralistic ignorance and alcohol use on campus. Journal of Personality and Social Psychology 64(2), S. 243–256","oeffentlich":false,"doi":"10.1037/0022-3514.64.2.243"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"d59f149ac2df90dd"}},{"id":"qx-e-025","clusterId":"E","werkstueckRef":"E.2.5","stufe":3,"question":"Welcher Satz fasst die Arbeit am besten vertretbar zusammen?","options":["„Männer passen sich dem vermuteten Trinkdruck an, Frauen dagegen nicht; das zeigte die wiederholte Befragung über ein ganzes Semester.“","„Die meisten vermuten bei anderen mehr Behagen beim Trinken, als diese selbst angeben; ob Männer sich eher anpassen, ist offen.“","„Die Arbeit ist wenig belastbar, denn eine ihrer vier Teilstudien beruht auf nur 50 telefonisch befragten Studierenden.“","„Die meisten vermuten bei anderen mehr Behagen beim Trinken, als diese angeben, und Männer passen sich dem eher an als Frauen.“"],"correctIndex":1,"explanation":"Zwei Teilbefunde tragen unterschiedlich viel. Dass Studierende die Haltung der anderen falsch einschätzen, zeigte sich in den vier Teilstudien derselben Arbeit: Die eigenen Werte streuten breit, die vermuteten Werte der anderen lagen dicht beieinander, und im Schnitt vermuteten die Befragten bei anderen mehr Wohlbehagen, als diese selbst angaben. Auch an einer anderen Universität zeigte sich im Grundmuster dasselbe. Der Geschlechterunterschied im Semesterverlauf dagegen stammt aus einer einzigen Teilstudie mit kleiner Stichprobe, war nicht vorhergesagt und lag statistisch knapp an der Signifikanzgrenze. So etwas kann Zufall sein und braucht Bestätigung, bevor man daraus ein Gesetz über Männer und Frauen macht; deshalb trägt der Satz, der die Lücke festhält und die Geschlechterfrage offenlässt. Der Satz über Männer und Frauen klingt konkret, stützt sich aber gerade auf den schwächsten Teil. Die ganze Arbeit zu verwerfen, wäre ebenso voreilig: Die kleine Telefonstichprobe betrifft nur eine der vier Teilstudien, und eine kleine Stichprobe schwächt die Sicherheit, sie macht einen Befund nicht wertlos.","coreRule":"⚡ Trenne gut gestützte Befunde von vorläufigen: Eine kleine Stichprobe und ein nicht vorhergesagter, knapper Unterschied verlangen Vorsicht, aber keine Verwerfung.","beleg":"Werkstück E.2.5 (Anwendung & Relevanz: Bei sozialen Normen); Fn. gl-e-prentice (Prentice & Miller 1993, S. 243–249; Vorbehalt S. 248 f.); Anmerkung anm-gl-e-prentice (Studie 1; Suls & Green 2003)","status":"entwurf","scenario":"Du sollst für den Newsletter der Studierendenvertretung eine Arbeit über Trinkgewohnheiten auf dem Campus in einem Satz zusammenfassen. Sie umfasst vier Teilstudien: Die meisten Befragten gaben an, die üblichen Trinkgewohnheiten seien ihnen selbst eher unangenehm, vermuteten beim durchschnittlichen Kommilitonen aber mehr Wohlbehagen; die eigenen Angaben streuten breit, die Schätzungen über andere lagen dicht beieinander. In einer dieser vier Teilstudien wurden 50 Studierende zu Semesterbeginn und gegen Semesterende telefonisch befragt: Die Männer näherten sich der vermuteten Norm an, die Frauen nicht; dieser Unterschied war nicht vorhergesagt und statistisch knapp. Ein Team an einer anderen Universität fand das Grundmuster der Fehleinschätzung ebenfalls.","kurz":"Tragfähig ist nur das Grundmuster: Die Befragten vermuten bei anderen mehr Behagen, als diese angeben. Der Geschlechterunterschied stammt aus einer kleinen, knappen, nicht vorhergesagten Teilstudie und kann Zufall sein; ihn als Befund zu melden, wäre voreilig.","prueffrage":"Aus wie vielen Teilstudien oder Untersuchungen stammt jeweils der Befund, den der Satz behauptet?","rueckmeldung":[{"option":0,"text":"Der Satz klingt konkret und lässt sich gut erzählen. Er stützt sich aber auf eine einzige Teilstudie mit zwei Befragungszeitpunkten, die nicht vorhergesagt und statistisch knapp war, und blendet den robusten Hauptbefund ganz aus."},{"option":2,"text":"Dass 50 Befragte wenig sind, stimmt. Das betrifft aber nur eine der vier Teilstudien. Das Grundmuster zeigte sich in allen vieren und auch an einer anderen Universität; eine kleine Stichprobe schwächt die Sicherheit, entwertet aber nicht die ganze Arbeit."},{"option":3,"text":"Die erste Hälfte trägt, sie ist der gut gestützte Hauptbefund. Die zweite hängt an einer kleinen Teilstudie, war nicht vorhergesagt und lag knapp an der Signifikanzgrenze. Beides in einem Satz stellt den schwachen Teil auf dieselbe Stufe wie den starken."}],"familie":"wiederholung-abwarten","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Schroeder, C. M.; Prentice, D. A. (1998): Exposing Pluralistic Ignorance to Reduce Alcohol Use Among College Students. Journal of Applied Social Psychology 28(23), S. 2150–2180 (Kopie Stanford SPARQ)","oeffentlich":true,"url":"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/schroeder_prentice_1998_-_exposing_pluralistic_ignorance.pdf","seite":"S. 2152–2153","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Prentice, D. A.; Miller, D. T. (1993): Pluralistic ignorance and alcohol use on campus. Journal of Personality and Social Psychology 64(2), S. 243–256","oeffentlich":false,"doi":"10.1037/0022-3514.64.2.243"},{"typ":"literatur","kurz":"Suls, J.; Green, P. (2003): Pluralistic Ignorance and College Student Perceptions of Gender-Specific Alcohol Norms. Health Psychology 22(5), S. 479–486","oeffentlich":false,"doi":"10.1037/0278-6133.22.5.479"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"129082886f79e066"}},{"id":"qx-e-026","clusterId":"E","werkstueckRef":"E.2.5","stufe":2,"question":"Welches Vorgehen ist hier am sinnvollsten, um herauszufinden, ob wirklich alle anderen den Plan gut finden, ohne dich selbst zu sehr zu exponieren?","scenario":"Im Projektmeeting stellt dein Chef einen Plan vor, der deiner Ansicht nach ein klares Problem hat. Alle nicken, niemand sagt etwas. Du hältst dich für den Einzigen, der zweifelt und überlegst, was du tun sollst.","options":["Den Plan in Ruhe gegen das Projektziel prüfen und das erkannte Problem dabei genauer fassen.","Eine Liste mit Vor- und Nachteilen anlegen und deinen Zweifel nüchtern dagegen abwägen.","Vom Chef die Belege für den Plan verlangen und seine Annahmen Schritt für Schritt nachprüfen.","Deinen Zweifel als offene Frage stellen und beobachten, wie die anderen im Raum darauf reagieren."],"correctIndex":3,"explanation":"Nicken und Schweigen sind nur öffentliches Verhalten, sie verraten nicht, was die anderen privat denken. Vielleicht zweifeln mehrere und schweigen aus demselben Grund wie du: Jeder hält sich für den Einzigen. Eine offene Frage ist ein günstiger Test: Das Risiko bleibt klein, dein Zweifel kommt trotzdem auf den Tisch, und oft äußern daraufhin andere ihre Bedenken. Den Plan gegen das Projektziel zu prüfen oder Vor- und Nachteile abzuwägen klärt den Plan selbst, verrät aber nichts über die Haltung der anderen. Belege vom Chef zu verlangen kann sinnvoll sein, zeigt aber ebenfalls nicht, was die Kollegen denken, und stellt dich stärker bloß als eine Frage.","coreRule":"⚡ Schweigen ist kein Beweis für Zustimmung: Eine offene Frage prüft, was die anderen denken, ohne dass du gleich angreifen musst.","beleg":"Werkstück E.2.5 (Das Härten im Feuer: Der mutige Test; Aktivierungs-Frage)","status":"entwurf","kurz":"Nicken und Schweigen sind nur Verhalten und verraten nicht, was die anderen denken; womöglich zweifeln mehrere und halten sich jeweils für den Einzigen. Eine offene Frage testet das günstig: Sie bringt deinen Zweifel auf den Tisch und lässt die Reaktionen sichtbar werden.","prueffrage":"Was zeigt dir das Verhalten der anderen im Raum tatsächlich, und was kannst du daraus nicht ablesen?","rueckmeldung":[{"option":0,"text":"Den Plan gegen das Projektziel zu prüfen klärt, wie belastbar dein Einwand ist. Über die anderen erfährst du dabei aber nichts, und genau danach fragt die Aufgabe: Auch bei einem klar gefassten Problem bleibt offen, wer sonst zweifelt."},{"option":1,"text":"Eine nüchterne Abwägung ordnet deine Gedanken und kann den Zweifel schärfen. Sie bleibt aber eine Rechnung in deinem Kopf: Ob andere ähnlich zweifeln, zeigt sie nicht, und dein Einwand wird dadurch auch nicht sichtbar."},{"option":2,"text":"Belege und Annahmen nachzuprüfen kann durchaus sinnvoll sein, um den Plan zu beurteilen. Über die Haltung der Kollegen sagt es aber ebenso wenig, und du stellst dich damit stärker bloß als mit einer einfachen Frage."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Schroeder, C. M.; Prentice, D. A. (1998): Exposing Pluralistic Ignorance to Reduce Alcohol Use Among College Students. Journal of Applied Social Psychology 28(23), S. 2150–2180 (Kopie Stanford SPARQ)","oeffentlich":true,"url":"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/schroeder_prentice_1998_-_exposing_pluralistic_ignorance.pdf","seite":"S. 2151–2153","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Prentice, D. A.; Miller, D. T. (1993): Pluralistic ignorance and alcohol use on campus. Journal of Personality and Social Psychology 64(2), S. 243–256","oeffentlich":false,"doi":"10.1037/0022-3514.64.2.243"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"86b2b873c8f7b798"}},{"id":"qx-e-027","clusterId":"E","werkstueckRef":"E.2.6","stufe":1,"question":"Ein Kind spielt gern mit einem Wellensittich. Eines Tages erschrickt es heftig, als genau dann ein Glas laut zerspringt. Nach mehreren ähnlichen Vorfällen weint das Kind schon beim bloßen Anblick des Vogels, noch bevor irgendein Geräusch zu hören ist. Wie lässt sich die Rolle des zerspringenden Glases am besten beschreiben?","options":["Es ist der Reiz, der von selbst Schreck auslöst, ohne dass das Kind etwas lernen musste; durch die Kopplung erhielt der Vogel diese Wirkung.","Es ist der anfangs neutrale Reiz, der erst durch die wiederholte Kopplung mit dem Vogel seine erschreckende Wirkung auf das Kind erhält.","Es ist der gelernte Auslöser der Angst, denn seine Wirkung hat sich erst über mehrere Vorfälle so aufgebaut, dass das Kind schon beim Vogel weint.","Es ist eine Strafe für das Spielen mit dem Vogel, die das Kind lehrt, die Nähe des Vogels künftig lieber zu meiden, weil sie Unangenehmes bringt."],"correctIndex":0,"explanation":"Ein Glas, das laut zerspringt, erschreckt von Natur aus; dafür muss das Kind nichts lernen. Der Vogel war zunächst neutral: Das Kind spielte gern mit ihm. Weil beides mehrfach zusammen auftrat, wurde der Vogel zum Auslöser der Angst, auch ohne Knall. Der Schreckreiz ist also der Auslöser, der von selbst wirkt, der Vogel dagegen der gelernte Auslöser. Wichtig für die Einschätzung: Ein einzelner Fall zeigt den Mechanismus, sagt aber nicht, ob die Angst dauerhaft bleibt oder sich wieder abschwächt.","coreRule":"⚡ Wenn ein neutraler Reiz oft genug mit einem Reiz gekoppelt wird, der von selbst eine Reaktion auslöst, löst der neutrale Reiz irgendwann allein diese Reaktion aus. Prüfe immer: Welcher Reiz wirkt von Anfang an, und welcher hat die Wirkung erst gelernt?","beleg":"Werkstück E.2.6 (Einstieg; Kernidee); Fn. gl-e-little-albert (Watson & Rayner 1920, S. 2–12). Szenario als Transfer des Albert-Experiments auf neue Situation (Kind, Vogel, Glas) gebaut; keine neuen Studien oder Zahlen.","status":"entwurf","scenario":"Ein Kind spielt gern mit einem Wellensittich. Wiederholt zerspringt im selben Moment ein Glas, das Kind erschrickt heftig. Nach einigen solchen Vorfällen weint es schon beim Anblick des Vogels, noch bevor irgendein Geräusch zu hören ist.","kurz":"Das zerspringende Glas erschreckt von sich aus, dafür muss das Kind nichts lernen. Der Fehler liegt darin, es als gelernten Auslöser zu sehen: Gelernt hat das Kind die Angst vor dem Vogel, der immer zugleich da war.","prueffrage":"Wie reagierte das Kind auf den Vogel, bevor das erste Glas zersprang, und wie nach mehreren Vorfällen?","rueckmeldung":[{"option":1,"text":"Die Kopplung beschreibst du richtig, nur sind die Rollen vertauscht. Anfangs neutral war der Vogel, mit dem das Kind gern spielte. Das Glas erschreckt dagegen von Natur aus, ohne jede Vorerfahrung."},{"option":2,"text":"Dass sich eine Wirkung erst über mehrere Vorfälle aufbaut, trifft zu, aber auf den Vogel. Das Glas braucht keine Wiederholung, um zu erschrecken. Gelernt ist das Weinen beim bloßen Anblick des Tieres."},{"option":3,"text":"Das Glas folgt nicht auf ein Verhalten des Kindes, es zerspringt zufällig im selben Moment wie der Vogel auftritt. Eine Strafe bräuchte eine Verbindung zum Tun des Kindes. Hier verknüpft das Kind den Schreck mit dem Tier."}],"familie":"gefuehl-statt-argument","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Watson, J. B.; Rayner, R. (1920): Conditioned Emotional Reactions. Journal of Experimental Psychology 3(1), 1–14 (Volltext in Classics in the History of Psychology, York University)","oeffentlich":true,"doi":"10.1037/h0069608","url":"https://psychclassics.yorku.ca/Watson/emotion.htm","abruf":"2026-10-12"},{"typ":"url","kurz":"OpenStax (Rice University): Psychology 2e, Kap. 6.2 Classical Conditioning","oeffentlich":true,"url":"https://openstax.org/books/psychology-2e/pages/6-2-classical-conditioning","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"893f7fcc70efefdb"}},{"id":"qx-e-028","clusterId":"E","werkstueckRef":"E.2.6","stufe":2,"question":"Welcher Mechanismus erklärt am besten, warum diese Werbung auch ohne ein einziges Sachargument wirken kann?","scenario":"In einem Spot sitzen lachende Freunde am Strand, ein Kind rennt jubelnd durch die Wellen, dazwischen taucht immer wieder dieselbe Limonadenflasche auf. Der Spot läuft wochenlang jeden Abend. Eine Kollegin sagt: „Dass mir die Limo sympathisch ist, liegt an ihrem Geschmack. Ich habe den Spot kaum beachtet.“","options":["Die Limonade wird wiederholt mit Reizen wie lachenden Freunden und einem jubelnden Kind gekoppelt, die von selbst Freude auslösen, und löst irgendwann allein ein Wohlgefühl aus.","Die Limonade wird durch die wochenlange Ausstrahlung jeden Abend vertraut, und schon das Vertraute wirkt angenehm, ganz gleich, mit welchen Bildern sie im Spot zusammen gezeigt wird.","Zuschauer ziehen aus den Bildern bewusst den Schluss, dass fröhliche Menschen und diese Limonade zusammengehören, und entscheiden sich nach dieser Überlegung für das Getränk.","Der Spot macht die Limonade vor allem bekannt, sodass Zuschauer sie einmal probieren; sympathisch wird sie danach durch ihren Geschmack, wie es die Kollegin selbst beschreibt."],"correctIndex":0,"explanation":"Der Spot enthält kein Argument über die Limonade selbst. Er zeigt sie immer wieder zusammen mit Dingen, die von sich aus Freude auslösen: lachende Menschen, Sonne, ein jubelndes Kind. Nach genug Wiederholungen kann schon das Produkt allein ein angenehmes Gefühl auslösen, oft ohne dass man es bemerkt. Dieselbe Technik funktioniert auch umgekehrt: Wer eine Person oder Gruppe wiederholt mit bedrohlicher Musik oder Angstbildern koppelt, kann Abneigung erzeugen.","coreRule":"⚡ Frag bei Werbung: Welcher Reiz soll hier welches Gefühl auf welches Produkt übertragen, und was wird dabei gar nicht argumentiert?","beleg":"Werkstück E.2.6 (Anwendung & Relevanz: In der Propaganda und Werbung; Schmiede-Übung)","status":"entwurf","kurz":"Der Spot koppelt die Limonade wiederholt mit Dingen, die von selbst Freude auslösen. Nach genug Wiederholungen kann das Produkt allein ein gutes Gefühl wecken, oft unbemerkt. Ein Sachargument braucht es dafür nicht, und die Selbstauskunft der Kollegin beweist wenig.","prueffrage":"Was wüsstest du über diese Limonade, wenn du den Spot nur zusammenfasst, und was zeigt er stattdessen?","rueckmeldung":[{"option":1,"text":"Dass Vertrautes angenehmer wirkt, ist durchaus belegt, und wochenlange Wiederholung gibt es hier. Aber der Spot zeigt die Flasche nicht neutral, sondern immer neben Lachen und Jubel. Gerade diese Verbindung trägt die Wirkung, nicht allein die Häufigkeit."},{"option":2,"text":"Bewusstes Abwägen wäre eine mögliche Route, aber hier nicht nötig: Die Kollegin hat den Spot kaum beachtet und mag die Limo trotzdem. Die Kopplung wirkt oft gerade dann, wenn man sie nicht bemerkt und nichts bewusst schlussfolgert."},{"option":3,"text":"Probieren und Geschmack können Sympathie tatsächlich stärken. Im Szenario steht aber nichts davon, dass der Geschmack zuerst kam. Das Wohlgefühl kann schon vorher durch die Kopplung entstehen, und die Kollegin kann es im Nachhinein dem Geschmack zuschreiben."}],"familie":"gefuehl-statt-argument","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"OpenStax (Rice University): Psychology 2e, Kap. 6.2 Classical Conditioning (Abschnitt zu Werbung)","oeffentlich":true,"url":"https://openstax.org/books/psychology-2e/pages/6-2-classical-conditioning","abruf":"2026-10-12"},{"typ":"url","kurz":"Hofmann, W.; De Houwer, J.; Perugini, M.; Baeyens, F.; Crombez, G. (2010): Evaluative conditioning in humans: a meta-analysis. Psychological Bulletin 136(3), 390–421 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1037/a0018916","url":"https://pubmed.ncbi.nlm.nih.gov/20438144/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"17150a04a05607ad"}},{"id":"qx-e-029","clusterId":"E","werkstueckRef":"E.2.6","stufe":3,"question":"Welche Erklärung beschreibt seinen Lernprozess am sparsamsten?","options":["Sein Verhalten ändert sich durch dessen Folgen: Beiträge, die Zuspruch und Ränge bringen, zeigt er häufiger, getadelte oder ignorierte seltener.","Der Tadel hat abweichende Meinungen für ihn mit Unbehagen verknüpft, sodass schon der Gedanke daran von selbst ein ungutes Gefühl in ihm auslöst.","Er hat nach zwei Erfahrungen durchschaut, nach welcher Regel das Forum Ränge vergibt, und richtet seine Beiträge nun bewusst nach dieser Regel aus.","Er hat seine Meinung wirklich geändert, weil die Reaktionen im Forum ihm gezeigt haben, dass die Gruppenlinie wohl besser begründet ist als seine."],"correctIndex":0,"explanation":"Der Nutzer lernt aus den Konsequenzen seines eigenen Verhaltens: Anpassung bringt Zuspruch und Ränge (Belohnung), Abweichung bringt Ignorieren oder Tadel (Bestrafung). Das Muster heißt operante Konditionierung (Skinner). Bei der klassischen Konditionierung wird dagegen ein Reiz mit einem anderen gekoppelt, ohne dass das eigene Verhalten Folgen hätte, wie bei der Ratte und dem Lärm im Fall des „kleinen Albert“; hier gibt es keinen solchen Auslöser. Entscheidend ist die Frage, ob das Verhalten selbst belohnt oder bestraft wird. Gruppen, die Abweichung bestrafen und Anpassung stark belohnen, können ihre Mitglieder so Schritt für Schritt auf Linie bringen, besonders wenn sie Zustimmung wie in einem Spiel mit Punkten und Rängen belohnen.","coreRule":"⚡ Klassisch lernt man Verknüpfungen von Reizen, operant lernt man aus den Folgen des eigenen Tuns.","beleg":"Werkstück E.2.6 (Kontext & Tiefe: Operante Konditionierung; Red Flags)","status":"entwurf","scenario":"Ein Forum vergibt Zuspruch und Ränge für Beiträge auf Gruppenlinie; abweichende Beiträge werden ignoriert oder getadelt. Ein Nutzer postet zweimal eine Meinung, die von der Linie abweicht, und wird beide Male ignoriert oder getadelt. Danach schreibt er nur noch Beiträge, die der Linie folgen und ihm Zuspruch und Ränge bringen.","quote":"","quoteLabel":"","kurz":"Er lernt aus den Folgen seines eigenen Verhaltens: Anpassung bringt Zuspruch und Ränge, Abweichung Ignorieren oder Tadel. Wer das Erlebte gleich mit Gefühlen, Einsicht oder Überzeugung erklärt, nimmt mehr an, als das Szenario hergibt.","prueffrage":"Zeigt der Nutzer irgendwo Angst oder Rückzug, und was genau hat sich an seinen Beiträgen verändert?","rueckmeldung":[{"option":1,"text":"Dass Tadel unangenehm ist, ist plausibel. Hier wird aber kein Reiz mit einem Gefühl gekoppelt, sondern sein Verhalten hat selbst Folgen, und von einem Unbehagen steht im Szenario nichts. Das erklärt allein, warum er seine Beiträge ändert."},{"option":2,"text":"Dass er die Regel durchschaut hat, ist denkbar. Das Szenario nennt aber nur zwei Erfahrungen und die Verhaltensänderung, nichts über Einsicht oder Absicht. Du müsstest etwas annehmen, das nicht dasteht, wo die Folgen allein genügen."},{"option":3,"text":"Zuspruch und Tadel sind Folgen, keine Argumente. Das Szenario zeigt nur, dass er anders postet, nicht dass er anders denkt. Ein echter Meinungswandel ist daher unbelegt und nicht nötig, um sein neues Verhalten zu erklären."}],"familie":"gefuehl-statt-argument","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"OpenStax (Rice University): Psychology 2e, Kap. 6.3 Operant Conditioning","oeffentlich":true,"url":"https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning","abruf":"2026-10-12"},{"typ":"url","kurz":"Watson, J. B.; Rayner, R. (1920): Conditioned Emotional Reactions. Journal of Experimental Psychology 3(1), 1–14 (Volltext in Classics in the History of Psychology)","oeffentlich":true,"doi":"10.1037/h0069608","url":"https://psychclassics.yorku.ca/Watson/emotion.htm","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"ec6f80a545bca52c"}},{"id":"qx-e-030","clusterId":"E","werkstueckRef":"E.2.6","stufe":4,"question":"Welche Erklärung für die Rückkehr der Angst ist die sparsamste?","options":["Die alte Angstverbindung wurde nicht gelöscht, sondern von einer neuen, hemmenden Erfahrung überlagert; unter neuen Umständen und nach einem Schreck kann die Angst wieder durchbrechen.","Die Therapie hat damals vermutlich nur oberflächlich gewirkt: Die Angst wurde jahrelang bloß nicht ausgelöst und zeigt sich jetzt, weil die Behandlung sie nicht an der Wurzel erfasst hatte.","Die Angst ist durch den Schreck neu entstanden: Das Erlebnis im Treppenhaus war so heftig, dass es eine frische Angstverbindung angelegt hat, unabhängig von der früheren, überwundenen Phobie.","Die Wirkung der Therapie ist mit den Jahren wohl verblasst: Was damals geübt wurde, lässt nach, wenn man es nicht auffrischt, und irgendwann reicht eine einzelne Spinne, um die Angst zu wecken."],"correctIndex":0,"explanation":"Die Rückkehr der Angst an einem neuen Ort und nach einem Schreck passt dazu, dass Löschung eine Reaktion eher unterdrückt als beseitigt: Neben die ursprüngliche Verknüpfung tritt eine zweite, hemmende, und die erste bleibt im Hintergrund erhalten. Dass Angst nach einer Pause, bei einem Ortswechsel oder nach einem Schreck zurückkehren kann, ist gut beobachtet und stützt genau das. Das beschreibt einen Mechanismus und ist keine Behandlungsempfehlung für den Einzelfall.","coreRule":"⚡ Verlernen heißt meist Überlagern: Das alte Gelernte bleibt im Hintergrund erhalten. Wiederkehr nach Jahren ist deshalb kein Beweis für ein Scheitern.","beleg":"Werkstück E.2.6 (Die entscheidende Waffe: Gegenkonditionierung & Desensibilisierung); Fn. gl-e-exposition (Craske u. a. 2014, S. 10–23; Myers 2014, S. 296)","status":"entwurf","scenario":"Eine Frau hat ihre Spinnenphobie mit schrittweiser Konfrontation erfolgreich überwunden und blieb jahrelang symptomfrei. Nach einem Umzug in eine andere Stadt erschreckt sie eine Spinne im Treppenhaus, und die alte Panik ist plötzlich wieder da. Ihre Freundin meint: „Dann hat die Therapie damals eben nicht richtig gewirkt.“","quote":"","quoteLabel":"","kurz":"Löschung unterdrückt die Angst eher, als sie zu beseitigen: Neben die alte Verknüpfung tritt eine hemmende, die alte bleibt bestehen. Dass sie nach Ortswechsel und Schreck wiederkehrt, ist deshalb kein Zeichen, dass die Therapie versagt hat.","prueffrage":"Was ist über die Therapie und die Jahre danach tatsächlich bekannt, und was wird nur vermutet?","rueckmeldung":[{"option":1,"text":"Jahrelange Symptomfreiheit spricht dagegen, dass die Therapie nur oberflächlich war; dass die Angst nur nicht ausgelöst wurde, ist bloß behauptet. Dass sie wiederkehren kann, ist auch nach gelungener Therapie normal und kein Zeichen von Versagen."},{"option":2,"text":"Der Schreck spielt tatsächlich eine Rolle, aber als Auslöser. Dass er eine ganz neue, unabhängige Angst anlegt, ist die aufwendigere Annahme, denn die Panik gilt genau demselben Auslöser wie früher: der Spinne."},{"option":3,"text":"Dass eine Pause zur Rückkehr beitragen kann, stimmt. Dass die Wirkung einfach verblasst, erklärt aber nicht, warum die Angst gerade nach Umzug und Schreck zurückkommt, und übergeht, dass die alte Verknüpfung im Hintergrund erhalten bleibt."}],"familie":"gefuehl-statt-argument","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Craske, M. G.; Treanor, M.; Conway, C. C.; Zbozinek, T.; Vervliet, B. (2014): Maximizing exposure therapy: An inhibitory learning approach. Behaviour Research and Therapy 58, 10–23 (PMC-Volltext)","oeffentlich":true,"doi":"10.1016/j.brat.2014.04.006","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4114726/","abruf":"2026-10-12"},{"typ":"url","kurz":"OpenStax (Rice University): Psychology 2e, Kap. 6.2 Classical Conditioning (Extinction, Spontaneous Recovery)","oeffentlich":true,"url":"https://openstax.org/books/psychology-2e/pages/6-2-classical-conditioning","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v7","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"8ea28fc0796b6654"}},{"id":"qx-e-031","clusterId":"E","werkstueckRef":"E.2.7","stufe":1,"question":"Welche Deutung seines Verhaltens ist am besten begründet?","options":["Sein früheres Zuhören kann ein Ausreißer gewesen sein, sodass das heutige Verhalten nur die Rückkehr zum Durchschnitt zeigt.","Das Team kann ihn seit der Beförderung kritischer beobachten, sodass sein Verhalten schlechter bewertet wird, obwohl es gleich geblieben ist.","Die neue Position kann sein Verhalten mitverändert haben, sodass die Situation neben dem Charakter als Erklärung zählt.","Eine vorübergehende Stimmungslage kann sein Verhalten erklären, sodass es nach wenigen Wochen von selbst wieder verschwindet."],"correctIndex":2,"explanation":"Wer ein Verhalten sofort dem „wahren Charakter“ zuschreibt, übersieht leicht, was die Situation bewirkt (fundamentaler Attributionsfehler). Frank war früher zugänglich, und die Veränderung setzte nach der Beförderung ein; das macht die neue Rolle als Mitursache plausibel, beweist sie aber nicht. In Experimenten schnitten Menschen, die man sich mächtig fühlen ließ, bei der Perspektivübernahme schlechter ab, doch eines dieser Experimente (zur Einschätzung, was andere wissen) ließ sich in einer großen Wiederholung mit fast 3.000 Teilnehmenden nicht bestätigen. Am besten begründet ist deshalb die vorsichtige Annahme, dass die Situation das Verhalten begünstigen kann, die man mit weiteren Beobachtungen prüfen würde.","coreRule":"⚡ Bevor du Mächtige zum „bösen Charakter“ erklärst, frag, was die Situation aus ihnen macht, und bleib bei der Stärke der Belege vorsichtig.","beleg":"Werkstück E.2.7 (Kernidee; Kontext & Tiefe „Der Empathie-Kollaps“; Anti-Denkmuster); Fn. gl-e-macht-droge (Keltner 2016), gl-e-galinsky (Galinsky u. a. 2006; Ebersole u. a. 2016)","status":"entwurf","scenario":"Frank galt im Team lange als zugänglich und hörte anderen gut zu. Sechs Monate nach seiner Beförderung zum Abteilungsleiter fällt auf: Er unterbricht andere in Meetings, hört kaum noch zu und geht davon aus, dass seine Ideen die besten sind. Im Team heißt es: „Er hat sein wahres Gesicht gezeigt.“","kurz":"Frank wurde vor der Beförderung als zugänglich erlebt, danach nicht mehr. Das macht die neue Rolle als Mitursache plausibel, auch wenn es sie nicht beweist. Aus dem Verhalten sofort auf den „wahren Charakter“ zu schließen, übersieht, was die Situation bewirken kann.","prueffrage":"Welche Beobachtungen über Frank stützen die Rede vom „wahren Gesicht“, und welche sprechen dagegen?","rueckmeldung":[{"option":0,"text":"Schwankungen um einen Durchschnitt gibt es wirklich, und ein Ausschlag nach oben fällt später als Absturz auf. Frank galt aber lange als zugänglich, das ist ein Muster und kein einzelner Ausreißer. Auch der Zeitpunkt nach der Beförderung bleibt dabei unerklärt."},{"option":1,"text":"Ein kritischerer Blick auf Vorgesetzte ist gut möglich und kann die Bewertung mitprägen. Das Szenario nennt aber konkrete Veränderungen: Er unterbricht und hört kaum noch zu, während er früher anders auftrat. Der Blick des Teams allein erklärt das nicht."},{"option":3,"text":"Stimmungen können Verhalten durchaus beeinflussen, meist aber nur für kurze Zeit. Hier hält das Verhalten seit sechs Monaten an. Eine Laune erklärt außerdem nicht, warum die Veränderung ausgerechnet mit der Beförderung begann."}],"familie":"umstaende-vor-absicht","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"FORRT FLoRA Replication Atlas: Galinsky u. a. (2006), Power and Perspectives Not Taken – Replikation Many Labs 3 (Ebersole u. a. 2016), Ergebnis „failed“","oeffentlich":true,"url":"https://forrt.org/flora-replication-atlas/doi/10.1111/j.1467-9280.2006.01824.x/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Galinsky, A. D.; Magee, J. C.; Inesi, M. E.; Gruenfeld, D. H. (2006): Power and Perspectives Not Taken. Psychological Science 17(12), 1068–1074","oeffentlich":false,"doi":"10.1111/j.1467-9280.2006.01824.x"},{"typ":"url","kurz":"Pronin, E.; Gilovich, T.; Ross, L. (2004): Objectivity in the eye of the beholder: divergent perceptions of bias in self versus others. Psychological Review 111(3), 781–799 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1037/0033-295X.111.3.781","url":"https://pubmed.ncbi.nlm.nih.gov/15250784/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"3ce174141fb8e8d1"}},{"id":"qx-e-032","clusterId":"E","werkstueckRef":"E.2.7","stufe":3,"question":"Du liest in einem Artikel: „Studien beweisen, dass Macht Menschen rücksichtslos macht.“ Als Beleg wird eine Feldstudie genannt, in der Fahrer teurer Autos an Kreuzungen häufiger andere Fahrzeuge schnitten und Fußgängern häufiger die Vorfahrt nahmen als Fahrer günstiger Wagen. Was ist an diesem Beleg zu beachten?","options":["Gemessen wurde der Preis des Autos, also ein Anzeichen für soziale Schicht und nicht für Macht; zudem stützen direkte Wiederholungen den Befund nicht.","Zu beachten ist vor allem die Zahl der beobachteten Fahrer; ist die Stichprobe groß genug, trägt der Unterschied zwischen den Wagen die Aussage über Macht.","Weil echtes Verhalten an echten Kreuzungen beobachtet wurde statt im Labor, ist der Beleg besonders lebensnah und stützt die Aussage über Macht gut.","Die Studie zeigt einen Zusammenhang, keinen Nachweis einer Ursache; das Wort „beweisen“ ist zu stark, die Messung von Macht über das Auto aber passt."],"correctIndex":0,"explanation":"Ein Beleg trägt eine Aussage nur, wenn er das misst, wovon die Aussage spricht. Das Auto ist hier ein Stellvertreter für soziale Schicht, und die Studie untersuchte nicht Macht, sondern soziale Schicht. Der Schluss von „Autopreis“ auf „Macht“ ist also ein Sprung. Dazu kommt: Die Feldstudie aus der Arbeitsgruppe um Dacher Keltner (Piff u. a., 2012) wurde 2023 in zwei direkten Wiederholungen nicht bestätigt. Ein Befund, der sich bei der Wiederholung nicht zeigt, ist ein wackliger Beleg. Zwei Fragen schützen vor solchen Fehlschlüssen: Was wurde tatsächlich gemessen, und hat sich das Ergebnis bei Wiederholung gezeigt?","coreRule":"⚡ Frag bei einer Studie: Was wurde wirklich gemessen, und wurde der Befund wiederholt?","beleg":"Werkstück E.2.7 (Kontext & Tiefe: Der Empathie-Kollaps); Fn. gl-e-keltner (Keltner 2016, S. 108 und 121–126; Piff u. a. 2012, PNAS 109(11), S. 4086–4091)","status":"entwurf","scenario":"Der Artikel zieht aus der Beobachtung den Schluss: „Wer Macht hat, verliert die Rücksicht auf andere.“","kurz":"Der Beleg trägt die Aussage nur, wenn er misst, wovon sie spricht. Der Autopreis steht für soziale Schicht, nicht für Macht, und die Feldstudie wurde in zwei direkten Wiederholungen nicht bestätigt. Beides macht den Beleg wackelig.","prueffrage":"Was genau haben die Forschenden an Autos und Fahrern festgehalten, und wurde die Beobachtung später noch einmal gemacht?","rueckmeldung":[{"option":1,"text":"Die Zahl der Beobachteten ist ein sinnvoller Prüfpunkt. Selbst eine große Stichprobe würde aber nichts daran ändern, dass der Autopreis nicht Macht erfasst; ein großer Unterschied zwischen den Wagen bliebe eine Aussage über etwas anderes."},{"option":2,"text":"Beobachtung im echten Verkehr ist ein Vorzug gegenüber dem Labor, weil das Verhalten nicht gestellt ist. Lebensnähe sagt aber nichts darüber, ob das Richtige gemessen wurde: Der Autopreis zeigt hier die soziale Schicht, nicht die Macht."},{"option":3,"text":"Dass hier ein Zusammenhang und kein Ursachennachweis vorliegt und „beweisen“ zu stark ist, stimmt. Der Schlussteil trägt aber nicht: Das Auto zeigt soziale Schicht, nicht Macht, und die Wiederholungen der Studie haben den Befund zudem nicht bestätigt."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Piff, P. K.; Stancato, D. M.; Côté, S.; Mendoza-Denton, R.; Keltner, D. (2012): Higher social class predicts increased unethical behavior. PNAS 109(11), 4086–4091 (PMC-Volltext)","oeffentlich":true,"doi":"10.1073/pnas.1118373109","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3306667/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Jung, M. H. u. a. (2023): Social status and unethical behavior: Two replications of the field studies in Piff et al. (2012). Journal of Experimental Psychology: General 152(5), 1368–1378","oeffentlich":false,"doi":"10.1037/xge0001333"},{"typ":"daten","kurz":"Universiteit van Amsterdam: Datensatz „Social status and unethical behavior: Two replications of the field studies in Piff et al. (2012)“ (mit Abstract)","oeffentlich":true,"doi":"10.21942/uva.24894654.v1","url":"https://dare.uva.nl/id/34307082-e88d-44ba-ad4d-340a45489827","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"43ec25bfad5a6d40"}},{"id":"qx-e-033","clusterId":"E","werkstueckRef":"E.2.7","stufe":4,"question":"Ein Ratgeber behauptet: „Macht wirkt im Gehirn wie Kokain – das ist gemessen.“ Als Beleg zitiert er einen Psychologen, der Macht „a dopamine high“ nennt. Wie beurteilst du die Behauptung?","options":["Ein Psychologe kennt sich mit solchen Fragen aus; nennt er Macht „a dopamine high“, wird er die Messung kennen, auf die sich der Ratgeber beruft.","Das Zitat zeigt nur, dass jemand den Vergleich formuliert hat; dass Dopamin bei Machtgefühl tatsächlich gemessen wurde, zeigt es nicht.","Hätte es eine Messung gegeben, hätte der Ratgeber sie statt des Zitats genannt; dass sie fehlt, spricht dafür, dass die Behauptung widerlegt ist.","Der Vergleich mit Kokain klingt stimmig, weil Macht sich gut anfühlen kann; eine so einleuchtende These ist durch das Fachzitat ausreichend gestützt."],"correctIndex":1,"explanation":"Ein Zitat, in dem ein Fachmann einen bildhaften Vergleich zieht („a dopamine high“), ist keine Messung. Der zitierte Psychologe (Dacher Keltner, 2016) nennt in seinem Buch „The Power Paradox“ keine Studie, die Dopamin bei Machtgefühl gemessen hätte; der Satz „das ist gemessen“ ist deshalb unbelegt. Unbelegt heißt aber nicht widerlegt, und zwischen beidem liegt ein großer Unterschied. Richtig ist die vorsichtige Lesart: eine griffige These mit dünner Datenbasis.","coreRule":"⚡ Ein griffiger Vergleich ist noch kein Messergebnis.","beleg":"Werkstück E.2.7 (Kernidee); Fn. gl-e-macht-droge (Keltner 2016, Einleitung S. 7, Kap. 1 S. 40, Kap. 4 S. 117)","status":"entwurf","scenario":"","kurz":"Ein Fachmann, der einen bildhaften Vergleich zieht, liefert keine Messung. Dass jemand Macht „a dopamine high“ nennt, zeigt nur, dass er den Vergleich gewählt hat. Ob Dopamin bei Machtgefühl gemessen wurde, bleibt offen.","prueffrage":"Welche Angaben zu Versuchspersonen, Messverfahren oder Messwerten enthält der Beleg des Ratgebers?","rueckmeldung":[{"option":0,"text":"Fachkompetenz macht eine Aussage glaubwürdiger, ersetzt aber keine Messung. Der Psychologe nennt laut Beleg keine Studie, sein Bild ist ein Vergleich, kein Befund. Wer „gemessen“ behauptet, muss die Messung selbst nennen."},{"option":2,"text":"Ein fehlender Beleg macht eine Behauptung unbelegt, aber nicht widerlegt. Ob es eine Messung gibt, bleibt offen; die vorsichtige Lesart lautet „griffige These, dünne Datenlage“, nicht „falsch“."},{"option":3,"text":"Dass Macht sich gut anfühlen kann, macht den Kokain-Vergleich anschaulich, nicht belegt. Einleuchten ersetzt keine Daten, und das Zitat ist ein Vergleich, keine Messung. Damit fehlt der Beleg für „gemessen“."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"literatur","kurz":"Keltner, D. (2016): The Power Paradox: How We Gain and Lose Influence. New York: Penguin Press","oeffentlich":false,"seite":"7"},{"typ":"url","kurz":"FORRT FLoRA Replication Atlas: Galinsky u. a. (2006), Power and Perspectives Not Taken – Replikation Many Labs 3, Ergebnis „failed“","oeffentlich":true,"url":"https://forrt.org/flora-replication-atlas/doi/10.1111/j.1467-9280.2006.01824.x/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"e3ca472634e4ba05"}},{"id":"qx-e-034","clusterId":"E","werkstueckRef":"E.2.7","stufe":2,"question":"In einer Zeitung steht: „Neurowissenschaftler haben bewiesen: Macht schaltet die Spiegelneuronen aus, Mächtige können das Leid anderer nicht mehr nachempfinden.“ Die zugrunde liegende Studie hat mit Magnetstimulation am Kopf gemessen, wie stark Muskeln beim Betrachten fremder Handbewegungen unwillkürlich „mitschwingen“. Wer sich mächtig fühlen sollte, zeigte eine schwächere Reaktion. Welche Übertreibung der Schlagzeile betrifft die Messebene selbst?","options":["Sie macht aus einem indirekten Muskelmaß den Beweis für abgeschaltete Nervenzellen, obwohl keine einzelne Nervenzelle untersucht wurde.","Sie macht aus einem Laborbefund eine Aussage über alle Mächtigen im Alltag, obwohl nur kurz mächtig gestimmte Teilnehmer untersucht wurden.","Sie macht aus einer einzelnen Studie einen Beweis, obwohl ein einzelner Befund erst durch Wiederholungen belastbar wird.","Sie macht aus einem Gruppenunterschied eine Wirkung der Macht, obwohl ganz andere Faktoren den Unterschied erklären könnten."],"correctIndex":0,"explanation":"Gemessen wurden Muskelantworten als indirektes Maß für das menschliche Spiegelsystem, keine einzelnen Nervenzellen. Daraus lässt sich allenfalls ein Hinweis auf geringere automatische Anteilnahme ableiten, kein Nachweis „abgeschalteter Spiegelneuronen“; einzelne Nervenzellen mit Spiegeleigenschaften wurden beim Menschen nur in einer anderen Studie mit implantierten Elektroden abgeleitet. Die übrigen Einwände treffen andere Schwächen: Die Übertragung vom Labor auf alle Mächtigen im Alltag betrifft die Verallgemeinerung, dass eine einzelne Studie noch kein Beweis ist, betrifft die Belegstärke, und der Einwand mit den „ganz anderen Faktoren“ betrifft die Ursache des Unterschieds; zudem wurde das Machtgefühl im Versuch gezielt erzeugt. Bei der Messebene selbst verspricht die Schlagzeile also etwas, das die Messung nicht hergibt: abgeschaltete Nervenzellen.","coreRule":"⚡ Ein indirektes Maß ist ein Hinweis, kein Beweis – und eine Schlagzeile darf nicht weiter reichen als das, was gemessen wurde.","beleg":"Werkstück E.2.7 (Kontext & Tiefe: Verringerte neuronale Resonanz); Fn. gl-e-hogeveen (Hogeveen u. a. 2014, S. 755–762; Mukamel u. a. 2010)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Gemessen wurde nur, wie stark Muskeln mitschwingen, also ein indirektes Maß, keine einzelne Nervenzelle. Daraus folgt allenfalls ein Hinweis auf geringere automatische Anteilnahme, nicht der Beweis „abgeschalteter Spiegelneuronen“.","prueffrage":"Wer wurde in der Studie untersucht, und wie wurde die Reaktion der Teilnehmenden erfasst?","rueckmeldung":[{"option":1,"text":"Der Einwand trifft eine echte Schwäche: Kurz mächtig gestimmte Teilnehmer sind kein Querschnitt aller Mächtigen. Diese Schwäche betrifft aber die Verallgemeinerung vom Labor auf den Alltag, nicht das, was die Messung selbst hergibt."},{"option":2,"text":"Dass eine einzelne Studie noch kein Beweis ist, stimmt, und „bewiesen“ ist tatsächlich zu stark. Das betrifft aber die Belegstärke, nicht die Messebene: Dort wird aus einem indirekten Muskelmaß ein Befund über abgeschaltete Nervenzellen."},{"option":3,"text":"Bei Gruppenvergleichen ist der Gedanke an andere Faktoren oft berechtigt. Hier wurde das Machtgefühl aber gezielt im Versuch erzeugt. Vor allem betrifft der Einwand die Ursache des Unterschieds, nicht das, was die Messung selbst hergibt."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Hogeveen, J.; Inzlicht, M.; Obhi, S. S. (2014): Power changes how the brain responds to others. Journal of Experimental Psychology: General 143(2), 755–762 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1037/a0033477","url":"https://pubmed.ncbi.nlm.nih.gov/23815455/","abruf":"2026-10-12"},{"typ":"url","kurz":"Mukamel, R.; Ekstrom, A. D.; Kaplan, J.; Iacoboni, M.; Fried, I. (2010): Single-neuron responses in humans during execution and observation of actions. Current Biology 20(8), 750–756 (PMC-Volltext)","oeffentlich":true,"doi":"10.1016/j.cub.2010.02.045","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC2904852/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"45a31c0954a94a15"}},{"id":"qx-e-035","clusterId":"E","werkstueckRef":"E.3.1","stufe":1,"question":"Was unterscheidet die Aussage des Politikers von der Zeitungsmeldung?","options":["Der Politiker ordnet das Ereignis in eine Geschichte mit Opfern, Gegnern und Retter ein und gibt ihm so eine Bedeutung, die die Fakten allein nicht liefern.","Der Politiker berichtet dasselbe Ereignis wie die Zeitung, nur in schärferen Worten; inhaltlich sagen beide dasselbe, lediglich der Ton ist deutlich emotionaler.","Der Politiker ergänzt eine Tatsache, die in der Meldung fehlt, nämlich dass die Manager aus Profitgier handeln, und berichtet damit vollständiger.","Der Politiker spricht im Wahlkampf und verfolgt dabei ein Eigeninteresse; deshalb ist seine Aussage wenig glaubwürdig, die Zeitung dagegen neutral."],"correctIndex":0,"explanation":"Die Meldung nennt ein Ereignis: 300 Entlassungen. Der Politiker fügt eine Deutung hinzu, mit Tätern („skrupellose Manager“), Opfern („die einfachen Leute“) und einem Retter („nur wir“). Das ist ein Narrativ: eine Geschichte, die Ereignisse in einen Ursache-Wirkungs-Zusammenhang mit Helden, Gegnern und Moral bringt, ihnen so Bedeutung verleiht und oft gleich eine Handlungsanweisung mitliefert. Die Entlassungen sind real, die Rollenverteilung ist eine Zutat der Geschichte. Deshalb lohnt die Frage, welche anderen Geschichten dieselben Fakten erklären könnten und welche Fakten diese Geschichte auslässt.","coreRule":"⚡ Fakten sagen, was geschah; ein Narrativ sagt, was es bedeutet. Prüfe deshalb immer, welche Deutung zu den Fakten hinzugefügt wurde und welche anderen möglich wären.","beleg":"Werkstück E.3.1 (Kernidee: Definition Narrativ; Kontext & Tiefe: Beispiel Fakt vs. Narrativ)","status":"entwurf","scenario":"Eine Tageszeitung meldet: „Ein Konzern entlässt 300 Beschäftigte.“ Ein Politiker sagt dazu im Wahlkampf: „Wieder opfern skrupellose Manager die einfachen Leute für ihren Profit, und nur wir stellen uns schützend vor sie.“","quote":"","quoteLabel":"","kurz":"Die Zeitung nennt ein Ereignis, der Politiker macht daraus eine Geschichte mit Tätern, Opfern und einem Retter. Diese Rollenverteilung steckt nicht in den 300 Entlassungen, sie ist eine Deutung, die man leicht für einen Teil der Tatsachen hält.","prueffrage":"Welcher Teil der Reaktion lässt sich in der Meldung wiederfinden, und welcher kommt erst von dem, der spricht?","rueckmeldung":[{"option":1,"text":"Beide beziehen sich auf dieselben Entlassungen, und der Ton ist tatsächlich emotionaler. Der Unterschied reicht aber tiefer: Der Politiker fügt Täter, Opfer und Retter hinzu, also eine Deutung, die in der Meldung nicht steht."},{"option":2,"text":"Der Politiker sagt tatsächlich mehr als die Meldung. Aber „aus Profitgier“ und „skrupellos“ sind zugeschriebene Motive und Wertungen, keine nachgewiesenen Tatsachen. Das macht die Aussage nicht vollständiger, sondern gedeutet."},{"option":3,"text":"Im Wahlkampf ist ein Eigeninteresse plausibel, und das rechtfertigt Vorsicht. Es erklärt aber nicht, worin sich die Aussage inhaltlich unterscheidet, und es widerlegt sie nicht von selbst. Auch eine Meldung wählt aus und formuliert."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dahlstrom, M. F. (2014): Using narratives and storytelling to communicate science with nonexpert audiences. PNAS 111(Suppl. 4) (PMC-Volltext)","oeffentlich":true,"doi":"10.1073/pnas.1320645111","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4183170/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"a33a01f6f02a3e66"}},{"id":"qx-e-036","clusterId":"E","werkstueckRef":"E.3.1","stufe":2,"question":"Ein Kollege wendet ein: „Das ist doch Verschwendung. Wer Schuhe verkaufen will, sollte zeigen, was die Schuhe können.“ Wie lässt sich die Strategie der Marke am besten erklären?","scenario":"Du siehst einen Spot nach dem anderen für eine Sportmarke: Läufer im Morgengrauen, ein Mädchen, das nicht aufgibt, am Ende ein Logo. Von den Schuhen erfährst du fast nichts.","options":["Die Marke verkauft eine Geschichte vom Menschen, der über sich hinauswächst. Wer die Schuhe kauft, kann sich als Teil dieser Geschichte fühlen.","Die Marke setzt auf die Bekanntheit ihres Logos. Wer die Schuhe kauft, greift im Laden zu dem Zeichen, das er am häufigsten gesehen hat und kennt.","Die Marke will vor allem eine gute Stimmung erzeugen. Wer die Schuhe kauft, überträgt das angenehme Gefühl aus dem Spot auf das Produkt selbst.","Die Marke umgeht den Vergleich mit der Konkurrenz. Wer die Schuhe kauft, soll gar nicht erst prüfen, ob andere Schuhe besser abschneiden."],"correctIndex":0,"explanation":"Der Spot erzählt, was die Marke bedeuten soll: Held, Hindernis, Überwindung. Das ist ein Narrativ, und Narrative sind weit einprägsamer und motivierender als abstrakte Sachinformationen. Käufer erwerben dann nicht nur ein Produkt, sondern die Zugehörigkeit zu einer Geschichte. Dass kaum Schuhe zu sehen sind, ist deshalb kein Fehler, sondern Absicht. Ein Test für solche Fälle: Frag, welche Geschichte ein Produkt mitverkauft und wer darin der Held ist.","coreRule":"⚡ Wer fragt, welche Geschichte ein Produkt mitverkauft, durchschaut die Werbung besser.","beleg":"Werkstück E.3.1 (Anwendung & Relevanz: Im Marketing)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Die Spots erzählen eine Geschichte mit Held, Hindernis und Überwindung, und wer kauft, erwirbt auch die Zugehörigkeit dazu. Der naheliegende Fehler ist, nur nach Produktinformation zu suchen und deren Fehlen für Verschwendung zu halten.","prueffrage":"Was genau bekommst du in diesen Spots zu sehen und zu hören, und was davon ließe sich in einer Produktbeschreibung wiederfinden?","rueckmeldung":[{"option":1,"text":"Dass ein häufig gesehenes Logo im Laden vertraut wirkt, ist durchaus ein Werbeeffekt. Dafür bräuchte es aber keine Läufer im Morgengrauen und kein Mädchen, das nicht aufgibt; die erzählte Geschichte bleibt damit unerklärt."},{"option":2,"text":"Ein gutes Gefühl kann sich tatsächlich auf ein Produkt übertragen. Die Spots bieten aber mehr als Stimmung: Sie erzählen eine Geschichte vom Überwinden, und gekauft wird auch das Gefühl, ein Teil davon zu sein."},{"option":3,"text":"Im Szenario steht nur, dass über die Schuhe fast nichts zu erfahren ist; dass die Marke damit den Vergleich verhindern will, steht dort nicht. Die gewählten Bilder erklärt diese Deutung auch nicht."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Mar, R. A.; Li, J.; Nguyen, A. T. P.; Ta, C. P. (2021): Memory and comprehension of narrative versus expository texts: A meta-analysis. Psychonomic Bulletin & Review 28(3), 732–749 (PMC-Volltext)","oeffentlich":true,"doi":"10.3758/s13423-020-01853-1","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8219577/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dahlstrom, M. F. (2014): Using narratives and storytelling to communicate science with nonexpert audiences. PNAS 111(Suppl. 4) (PMC-Volltext)","oeffentlich":true,"doi":"10.1073/pnas.1320645111","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4183170/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"e9d87f44cd327a87"}},{"id":"qx-e-037","clusterId":"E","werkstueckRef":"E.3.1","stufe":3,"question":"Welche Beobachtung zeigt am deutlichsten, dass eine Geschichte nicht mehr der Deutung der Wirklichkeit dient, sondern sie ersetzt?","options":["Die Geschichte teilt die Welt scharf in „das Volk“ und „die Eliten“ ein, denn eine so klare Trennung in Gut und Böse vereinfacht die Wirklichkeit bis zur Unkenntlichkeit.","Belegte Gegenbeispiele werden nicht geprüft, sondern als Angriff abgetan, denn die Treue zur Geschichte zählt dort mehr als die Treue zu den Tatsachen.","Die Geschichte überzeugt fast nur die eigenen Anhänger und kaum Außenstehende, denn wer an der Wirklichkeit vorbeierzählt, findet draußen wenig Anklang.","Die Geschichte erklärt den Mitgliedern Vergangenheit, Gegenwart und Zukunft, denn wer so viel aus einer einzigen Erzählung ableitet, lässt kaum Raum für andere Deutungen."],"correctIndex":1,"explanation":"Eine Geschichte ist zunächst ein Werkzeug: Sie ordnet Ereignisse zu einem Zusammenhang, stiftet Sinn und ermöglicht Zusammenarbeit zwischen Menschen, die sich nicht kennen. Das ist nützlich und kein Fehler. Gefährlich wird sie, wenn sie die Wirklichkeit nicht mehr deutet, sondern ersetzt: Dann gelten Tatsachen, die nicht ins Bild passen, als feindliche Propaganda und werden nicht mehr geprüft. Das Merkmal ist also der Umgang mit widersprechenden Belegen. Klare Rollen von Held und Gegner kommen in fast jeder wirksamen Geschichte vor, auch in harmlosen, und sind höchstens ein Warnsignal, aber noch kein Beweis. Dass eine Geschichte nur eine Gruppe erreicht, sagt über ihren Wahrheitsgehalt nichts.","coreRule":"⚡ Eine Geschichte wird gefährlich, wenn sie die Wahrheit nicht mehr deutet, sondern ersetzt.","beleg":"Werkstück E.3.1 (Der Kipppunkt; Red Flags; Kontext & Tiefe)","status":"entwurf","scenario":"Eine Bewegung erzählt ihren Anhängern eine Geschichte von einem Kampf zwischen „dem Volk“ und „den Eliten“. Die Geschichte erklärt für die Mitglieder Vergangenheit, Gegenwart und Zukunft. Du beobachtest vier Dinge an dieser Bewegung.","kurz":"Entscheidend ist, wie die Geschichte mit widersprechenden Belegen umgeht. Wo diese nicht mehr geprüft, sondern als Angriff abgetan werden, ersetzt sie die Wirklichkeit. Dass sie ordnet und Sinn stiftet, tut jede nützliche Geschichte.","prueffrage":"Welche der beobachteten Eigenschaften hätte auch ein harmloses Märchen, und welche nicht?","rueckmeldung":[{"option":0,"text":"Eine scharfe Rollenverteilung fällt sofort auf. Held und Gegner gibt es aber in fast jeder wirksamen Geschichte, auch in harmlosen. Das kann höchstens ein Warnsignal sein, beweist für sich genommen noch nichts."},{"option":2,"text":"Dass kaum Außenstehende überzeugt werden, wirkt wie ein Zeichen fehlender Wahrheit. Über den Wahrheitsgehalt sagt das aber nichts: Auch zutreffende Geschichten erreichen oft nur eine Gruppe, etwa wegen anderer Erfahrungen oder Interessen."},{"option":3,"text":"Eine Geschichte, die Vergangenheit, Gegenwart und Zukunft verbindet, wirkt allumfassend. Genau das tun aber auch nützliche Geschichten: Sie ordnen Ereignisse und stiften Sinn. Ob sie die Wirklichkeit ersetzt, zeigt sich erst im Umgang mit Gegenbelegen."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Smith, D. u. a. (2017): Cooperation and the evolution of hunter-gatherer storytelling. Nature Communications 8, 1853 (PMC-Volltext)","oeffentlich":true,"doi":"10.1038/s41467-017-02036-8","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5717173/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dahlstrom, M. F. (2014): Using narratives and storytelling to communicate science with nonexpert audiences. PNAS 111(Suppl. 4) (PMC-Volltext)","oeffentlich":true,"doi":"10.1073/pnas.1320645111","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4183170/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Harari, Y. N. (2013): Eine kurze Geschichte der Menschheit (Sapiens). München: DVA","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"5ed9360f4f27c3c2"}},{"id":"qx-e-038","clusterId":"E","werkstueckRef":"E.3.1","stufe":4,"question":"Du liest in einem populären Geschichtsbuch: „Vor genau 70.000 Jahren löste eine plötzliche kognitive Revolution die Fähigkeit des Menschen aus, an gemeinsame Geschichten zu glauben, und erklärt damit alles Spätere.“ Welche Rückfrage prüft diese Aussage am besten?","options":["Gibt es Funde, die symbolisches Verhalten schon deutlich vor 70.000 Jahren zeigen und eher für eine allmähliche Entwicklung sprechen?","Hat sich das Buch besonders gut verkauft und halten deshalb viele Menschen die Aussage für richtig?","Ist die Jahreszahl 70.000 nicht exakt belegbar und spielten gemeinsame Geschichten dann keine Rolle?","Wurde das Buch für ein breites Publikum geschrieben und ist die Aussage deshalb vermutlich falsch?"],"correctIndex":0,"explanation":"Eine Behauptung mit einer genauen Zahl und einem „plötzlichen“ Wendepunkt lässt sich an Befunden prüfen. Hier gibt es Hinweise dagegen: Die Archäologinnen Sally McBrearty und Alison Brooks argumentieren für eine allmähliche Entwicklung symbolischen Verhaltens, und Funde aus der Höhle von Blombos in Südafrika werden auf 75.000 bis 100.000 Jahre datiert. Die Rückfrage nach früheren Funden prüft also genau den Punkt, an dem die Aussage angreifbar ist. Verkaufszahlen und Reichweite sagen nichts über die Richtigkeit, und dass ein Werk ein breites Publikum anspricht, macht es noch nicht falsch. Auch eine umstrittene Jahreszahl widerlegt nicht den Kerngedanken, dass gemeinsame Geschichten Kooperation unter Fremden ermöglichen; dieser hängt nicht an der genauen Zahl.","coreRule":"⚡ Prüfe bei einer eingängigen Zahl in einer großen Erzählung, ob Befunde dagegensprechen. Eine umstrittene Zahl entwertet nicht automatisch den Kerngedanken.","beleg":"Werkstück E.3.1 (Kontext & Tiefe); Fn. gl-e-harari (Harari 2011/2013; McBrearty & Brooks; Blombos)","status":"entwurf","scenario":"Ein Bekannter hält eine Aussage aus einem populären Geschichtsbuch für die Erklärung unserer ganzen Kultur. Du willst herausfinden, wie belastbar diese Aussage ist.","kurz":"Eine genaue Zahl und ein „plötzlicher“ Wendepunkt lassen sich an Funden prüfen. Findet sich symbolisches Verhalten deutlich früher, spricht das gegen den Umbruch. Beliebtheit eines Buchs dagegen sagt nichts über seine Richtigkeit.","prueffrage":"Welche Wörter machen den Satz besonders angreifbar, und womit ließe sich jedes davon überprüfen?","rueckmeldung":[{"option":1,"text":"Dass sich ein Buch gut verkauft, gibt der Aussage einen Anschein von Gewicht. Verkaufszahlen und Reichweite sagen aber nichts darüber, ob sie stimmt; viele Leserinnen und Leser können sich ebenso irren."},{"option":2,"text":"Eine genaue Jahreszahl lässt sich tatsächlich kaum belegen. Selbst eine umstrittene Zahl widerlegt aber nicht den Gedanken, dass gemeinsame Geschichten Zusammenarbeit unter Fremden ermöglichen; der hängt nicht an der Zahl."},{"option":3,"text":"Populäre Bücher vereinfachen manchmal, deshalb ist Nachprüfen sinnvoll. Ein breites Publikum macht eine Aussage aber nicht falsch; ob sie trägt, zeigt sich an den Befunden, nicht am Leserkreis."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"McBrearty, S.; Brooks, A. S. (2000): The revolution that wasn't: a new interpretation of the origin of modern human behavior. Journal of Human Evolution 39(5), 453–563 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1006/jhev.2000.0435","url":"https://pubmed.ncbi.nlm.nih.gov/11102266/","abruf":"2026-10-12"},{"typ":"url","kurz":"Henshilwood, C. S.; d'Errico, F.; Watts, I. (2009): Engraved ochres from the Middle Stone Age levels at Blombos Cave, South Africa. Journal of Human Evolution 57(1), 27–47 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1016/j.jhevol.2009.01.005","url":"https://pubmed.ncbi.nlm.nih.gov/19487016/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Harari, Y. N. (2013): Eine kurze Geschichte der Menschheit (Sapiens). München: DVA","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"1577bafd9ba2c4ed"}},{"id":"qx-e-039","clusterId":"E","werkstueckRef":"E.3.2","stufe":1,"question":"Welche Erwiderung auf diesen Einwand trifft zu?","options":["Der Wert entsteht im Kopf jedes Einzelnen, und wer wie du selbst nicht an Geld glaubt, für den hat der Schein auch keinen Wert und kann dir egal sein.","Der Wert steckt im Papier der Scheine und im Metall der Münzen, nicht im Glauben der Menschen; er hängt am Material, das jeder Käufer in der Hand hält.","Der Wert ist keine Einbildung des Einzelnen, sondern beruht auf dem gemeinsamen Glauben vieler und zeigt sich in den Folgen, die er für alle hat.","Der Wert wird vom Staat vorgeschrieben, der Scheine und Münzen zum gesetzlichen Zahlungsmittel erklärt, und wirkt deshalb auch ohne den Glauben der Menschen."],"correctIndex":2,"explanation":"Der Einwand verwechselt zwei Dinge: „nur im Denken“ und „nur im Denken eines Einzelnen“. Der Wert des Geldes hängt nicht an einer einzelnen Person, sondern an der Übereinkunft von Millionen. Deshalb kann ihn niemand allein wegdenken: Wer als Einziger aufhört, an den Euro zu glauben, ist nicht erleuchtet, sondern pleite. Ein Schimpanse zeigt, wie viel am geteilten Glauben hängt: Für ihn ist der Schein nur ein Stück Papier, er tauscht ihn nicht gegen Bananen. Gleichzeitig ist der Wert nicht objektiv wie die Schwerkraft, denn er würde verschwinden, wenn eine kritische Masse von Menschen aufhört, an ihn zu glauben. Solche Dinge nennt man intersubjektiv: Sie existieren durch gemeinsamen Glauben und wirken trotzdem real. Dass jeder Güter nach persönlichem Nutzen bewertet, stimmt zwar, doch der Wert des Geldes hängt daran, was alle anderen dafür hergeben, nicht an der eigenen Meinung. Im Papier und im Metall steckt kaum Wert, den bekommen Schein und Münze erst dadurch, dass andere sie annehmen. Und staatlicher Zwang kann die Annahme absichern, ersetzt aber nicht das Vertrauen, dass andere das Geld ebenfalls annehmen.","coreRule":"⚡ Intersubjektiv real ist, was nur durch den gemeinsamen Glauben vieler existiert – und trotzdem handfeste Folgen hat. „Nur im Kopf“ heißt nicht „nur im Kopf eines Einzelnen“ und auch nicht „wirkungslos“.","beleg":"Werkstück E.3.2 (Kernidee; Kontext & Tiefe: Drei Arten von Realität)","status":"entwurf","scenario":"Im Gespräch über Geld sagt jemand: „Geld ist doch nur bedrucktes Papier und ein Stück Metall. Der Wert existiert nur in unseren Köpfen, also ist er Einbildung. Wenn ich selbst nicht daran glaube, kann es mir egal sein.“","kurz":"Der Wert des Geldes steckt nicht im Kopf einer einzelnen Person, sondern in der Übereinkunft von Millionen, und diese wirkt real: Wer als Einziger nicht mitglaubt, ist nicht erleuchtet, sondern pleite. „Nur im Denken“ heißt nicht „nur im eigenen Denken“.","prueffrage":"Was geschieht mit jemandem, der als Einziger in seiner Stadt aufhört, Geld anzunehmen?","rueckmeldung":[{"option":0,"text":"Dass jeder Güter nach eigenem Nutzen bewertet, stimmt. Beim Geld zählt aber, was alle anderen dafür hergeben, nicht die eigene Meinung: Wer allein nicht mehr daran glaubt, wird dadurch nicht unabhängig, sondern kann einfach nichts mehr kaufen."},{"option":1,"text":"Den Schein hält man tatsächlich in der Hand, und das macht das Material greifbar. Es trägt aber kaum Wert in sich; den bekommen Schein und Münze erst dadurch, dass andere sie annehmen. Ohne diese Annahme bleibt es Papier und Metall."},{"option":3,"text":"Der Staat kann die Annahme von Geld tatsächlich absichern, etwa als gesetzliches Zahlungsmittel. Das ersetzt aber nicht das Vertrauen, dass andere es ebenfalls annehmen. Der Wert wirkt also keineswegs unabhängig vom Glauben der Menschen."}],"familie":"gemeinsamer-glaube","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Social Ontology (2018, überarbeitet 2024)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/social-ontology/","abruf":"2026-10-12"},{"typ":"url","kurz":"Beran, M. J.; Parrish, A. E. (2021): Non-human primate token use shows possibilities but also limitations for establishing a form of currency. Philosophical Transactions of the Royal Society B 376(1819), 20190675 (PMC-Volltext)","oeffentlich":true,"doi":"10.1098/rstb.2019.0675","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7815425/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Harari, Y. N. (2013): Eine kurze Geschichte der Menschheit (Sapiens). München: DVA","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"8fa22243f257919f"}},{"id":"qx-e-040","clusterId":"E","werkstueckRef":"E.3.2","stufe":2,"question":"Welche Erklärung für den Wertverlust ist am stimmigsten?","options":["Der Wert des Geldes beruht auf dem gemeinsamen Vertrauen vieler Menschen; schwindet dieses Vertrauen breit, bricht der Wert zusammen, auch wenn die Scheine gleich bleiben.","Der Wert des Geldes entspricht dem seines Papiers und Drucks; er sinkt erst, wenn die Scheine billiger oder schlechter werden, nicht bei unveränderten Scheinen wie hier.","Der Wert des Geldes ergibt sich aus der Wertschätzung jedes Einzelnen für seine Scheine; er fällt für jede Person einzeln, unabhängig davon, was andere damit anfangen.","Der Wert des Geldes wird allein durch das Gesetz festgelegt; solange das Gesetz die Annahme der Scheine vorschreibt, bleibt der Wert stabil, egal wie viele ihm misstrauen."],"correctIndex":0,"explanation":"Geld hat keinen Wert, der im Papier steckt; es ist nur so viel wert, wie andere dafür hergeben, und das hängt am breiten Vertrauen, dass es weiter angenommen wird. Ausgelöst wird eine Hyperinflation meist durch massive Geldschöpfung, etwa wenn ein Staat seine Ausgaben über die Notenpresse bezahlt; schwindet dann das Vertrauen, beschleunigt das den Verfall, obwohl die Scheine physisch dieselben bleiben. Der Wert eines Materials würde nur sinken, wenn sich das Material verschlechterte, doch das Papier ist vorher und nachher dasselbe. Eine persönliche Einschätzung jedes Einzelnen erklärt keinen gemeinsamen Absturz, denn wer als Einziger nicht mehr an die Währung glaubt, ändert an ihrem Wert nichts, solange andere sie annehmen. Und das Gesetz kann die Annahme vorschreiben, hält den Wert aber nicht stabil, wenn die Menschen der Währung nicht mehr vertrauen.","coreRule":"⚡ Was nur auf gemeinsamem Glauben ruht, kann zerbrechen, wenn der Glaube bricht. Die Veränderung muss dann im Verhalten der Menschen gesucht werden, nicht im Material.","beleg":"Werkstück E.3.2 (Kontext & Tiefe: Intersubjektive Realität; Red Flags; Anwendung & Relevanz: In der Wirtschaft)","status":"entwurf","scenario":"Eine Währung verliert in einer Hyperinflation fast über Nacht ihren Wert, obwohl sich die Geldscheine physisch nicht verändern. Kollegin A sagt: „Da muss das Papier selbst schlechter geworden sein.“ Kollege B sagt: „Nein, das hat mit dem Papier nichts zu tun.“","kurz":"Geld ist nur so viel wert, wie andere dafür hergeben, und das beruht auf breitem Vertrauen in seine Annahme. Fehlt das Vertrauen, hilft es nicht, dass die Scheine physisch dieselben bleiben; der Wert steckte nie im Papier.","prueffrage":"Was genau hat sich an den Geldscheinen selbst zwischen vorher und nachher verändert, und wie schnell ist der Wert gefallen?","rueckmeldung":[{"option":1,"text":"Ein Stoffwert würde tatsächlich nur fallen, wenn sich das Material verschlechtert. Beim Geld steckt der Wert aber nicht im Papier, und das ist hier vorher und nachher dasselbe."},{"option":2,"text":"Vertrauen ist tatsächlich eine Einstellung von Menschen. Ein gemeinsamer Absturz entsteht aber nicht aus vielen Einzelurteilen: Wer allein nicht mehr glaubt, ändert am Wert nichts, solange andere die Währung annehmen."},{"option":3,"text":"Das Gesetz kann die Annahme der Scheine vorschreiben, und das stützt die Währung. Allein bestimmt es ihren Wert aber nicht: Schwindet das Vertrauen der Menschen, fällt er trotzdem, auch bei unveränderter Rechtslage."}],"familie":"gemeinsamer-glaube","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Deutscher Bundestag: Hyperinflation in Deutschland 1923 (Reihe „100 Jahre Weimar“)","oeffentlich":true,"url":"https://www.bundestag.de/parlament/geschichte/100-jahre-weimar/hyperinflation-970722","abruf":"2026-10-12"},{"typ":"url","kurz":"Agur, I.; Capelle, D.; Dell'Ariccia, G.; Sandri, D. (2022): Should Monetary Finance Remain Taboo? IMF Blog, 22.02.2022","oeffentlich":true,"url":"https://www.imf.org/en/Blogs/Articles/2022/02/22/should-monetary-finance-remain-taboo","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"210a5deb6a922e9d"}},{"id":"qx-e-041","clusterId":"E","werkstueckRef":"E.3.2","stufe":3,"question":"Welche Rückfrage prüft die Behauptung des Kollegen am besten?","options":["Was geschähe mit dem Modell, wenn alle Beteiligten morgen aufhörten, sich an seine Regeln zu halten?","Was geschähe mit dem Modell, wenn ein einzelner Vertragspartner morgen aus seinen Verträgen ausstiege?","Was geschähe mit dem Modell, wenn sich die Einkaufspreise der Beteiligten im nächsten Jahr verdoppelten?","Was geschähe mit dem Modell, wenn der Verfasser der Regeln es morgen öffentlich infrage stellte?"],"correctIndex":0,"explanation":"Ein Naturgesetz gilt unabhängig davon, was wir glauben: Wer nicht mehr an die Schwerkraft glaubt, fällt trotzdem. Ein Wirtschaftsmodell dagegen besteht aus gemeinsamen Regeln, Verträgen und Erwartungen. Es wirkt nur, solange genügend Menschen mitmachen, und es kann sich ändern, wenn sie ihr Verhalten ändern. Die Rückfrage, ob es noch bestünde, wenn alle morgen aufhörten mitzumachen, trennt diese beiden Fälle. Der Fehler des Kollegen liegt darin, ein von Menschen geschaffenes Gefüge für unveränderlich zu halten. Das führt zu Dogmatismus, weil Verbesserungen gar nicht erst gesucht werden. Umgekehrt wäre es auch falsch, das Modell für beliebig änderbar zu halten: Wer allein aussteigt, ändert nichts, sondern trägt nur selbst die Folgen. Genau deshalb prüft der Ausstieg eines einzelnen Vertragspartners nichts, denn das Modell läuft ohne ihn weiter. Ein Preisschock beim Einkauf prüft die Robustheit gegen einen äußeren Einfluss, nicht die Abhängigkeit von der Zustimmung der Beteiligten. Und das Urteil des Verfassers der Regeln sagt höchstens etwas über sein Ansehen, solange die Beteiligten weitermachen.","coreRule":"⚡ Frag bei einer „Naturgesetz“-Behauptung: Gilt sie auch, wenn alle morgen nicht mehr daran glauben?","beleg":"Werkstück E.3.2 (Der Kipppunkt; Anti-Denkmuster)","status":"entwurf","scenario":"In einer Teamsitzung über die Preisgestaltung sagt ein Kollege: „Dieses Wirtschaftsmodell ist wie ein Naturgesetz – daran kann man nichts ändern.“ Das Modell beruht auf Regeln, Verträgen und Erwartungen, auf die sich viele Menschen eingestellt haben.","quote":"","quoteLabel":"","kurz":"Ein Naturgesetz gilt auch dann, wenn niemand daran glaubt, ein Wirtschaftsmodell dagegen nur, solange genug Menschen mitmachen. Der Denkfehler: ein von Menschen geschaffenes Gefüge für unveränderlich zu halten, obwohl es sich ändert, wenn sie ihr Verhalten ändern.","prueffrage":"Woraus besteht das Modell im Einzelnen, und wer hat diese Regeln, Verträge und Erwartungen hervorgebracht?","rueckmeldung":[{"option":1,"text":"Dass ein einzelner Ausstieg nichts verändert, stimmt: Das Modell läuft ohne diesen Partner weiter, und er trägt selbst die Folgen. Gerade deshalb zeigt die Frage nichts, denn auch ein veränderbares Gefüge übersteht einen Einzelausstieg."},{"option":2,"text":"Ein Preisschock zeigt, wie robust das Modell gegen einen äußeren Einfluss ist. Ob es überhaupt davon abhängt, dass die Beteiligten mitmachen, bleibt dabei aber offen, und genau darum geht es beim Vergleich mit einem Naturgesetz."},{"option":3,"text":"Das Urteil des Verfassers sagt höchstens etwas über sein Ansehen. Das Modell besteht, solange die Beteiligten sich daran halten, unabhängig davon, wer die Regeln einmal geschrieben hat oder was er heute von ihnen hält."}],"familie":"gemeinsamer-glaube","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Social Ontology (2018, überarbeitet 2024)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/social-ontology/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Harari, Y. N. (2013): Eine kurze Geschichte der Menschheit (Sapiens). München: DVA","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"cd62c99032bdfdf6"}},{"id":"qx-e-042","clusterId":"E","werkstueckRef":"E.3.2","stufe":4,"question":"Ein Beitrag behauptet: „Schimpansen verstehen Geld. Sie tauschen Marken gegen Futter, also nutzen sie Geld genau wie wir.“ Welche Frage prüft diese Behauptung am besten?","options":["Haben die Tiere nur gelernt, was belohnt wird, oder teilen sie auch eine Vorstellung davon, dass die Marken Wert haben?","Wie oft pro Stunde tauschen die Tiere ihre Marken im Durchschnitt gegen Futter ein?","Wie schneiden Schimpansen bei Intelligenztests im Vergleich zu anderen Tierarten ab?","Schmeckt den Tieren das Futter aus dem Automaten besser als das Futter in ihrem Käfig?"],"correctIndex":0,"explanation":"Der Schluss „tauscht Marken gegen Futter, also nutzt Geld“ verwechselt gelerntes Tauschen mit Geld. Nach Beran & Parrish (2021) lernen Primaten, Marken als Platzhalter für Futter zu schätzen, nutzen sie aber nicht so, wie Menschen Währung nutzen. Beim Geld kommt etwas hinzu: Es hat Wert, weil Millionen Menschen sich gemeinsam vorstellen, dass ein Stück Papier Wert hat. Genau das prüft die Frage, ob die Tiere nur gelernt haben, was belohnt wird, oder ob sie auch eine geteilte Wertvorstellung haben. Die übrigen Fragen betreffen Häufigkeit, Intelligenz oder Geschmack und sagen nichts darüber, ob mehr als gelerntes Tauschen vorliegt. Schimpansen lernen den Markentausch übrigens schon seit den 1930er-Jahren, ohne damit Teil unseres Geldsystems zu sein.","coreRule":"⚡ Tauschen können ist noch kein Geld: Dazu gehört die geteilte Geschichte über seinen Wert.","beleg":"Werkstück E.3.2 (Einstieg: Die unmögliche Banane); Fn. gl-e-marken (Beran & Parrish 2021; Wolfe 1936)","status":"freigegeben","freigabe":{"datum":"2026-10-13","pruefsumme":"1f6b04564b6fa704","vermerk":"Prüfpult"},"scenario":"In einem Versuch lernen Schimpansen, Marken in einen Automaten zu stecken und dafür Futter zu bekommen. Ein Beitrag zieht daraus den Schluss, die Tiere seien Teil unseres Geldsystems.","quote":"","quoteLabel":"","kurz":"Marken gegen Futter zu tauschen ist gelerntes Verhalten und noch kein Geld. Geld gilt, weil viele gemeinsam an seinen Wert glauben, und der Fehler liegt darin, Belohnungslernen mit dieser geteilten Vorstellung gleichzusetzen.","prueffrage":"Was tun die Tiere mit den Marken, wenn gerade kein Automat in der Nähe ist oder ein anderes Tier eine Marke anbietet?","rueckmeldung":[{"option":1,"text":"Eine hohe Tauschrate wirkt wie ein Beleg für echten Gebrauch. Sie zeigt aber nur, wie gut der Tausch eingeübt ist, und sagt nichts darüber, ob mehr als gelerntes Verhalten dahintersteckt."},{"option":2,"text":"Schimpansen gelten als klug, und das scheint zu einem Geldverständnis zu passen. Ihr Abschneiden in Intelligenztests sagt aber nichts darüber, ob sie mit den Marken eine geteilte Wertvorstellung verbinden."},{"option":3,"text":"Ob das Futter besser schmeckt, betrifft nur die Belohnung selbst. Es sagt nichts darüber, ob die Marken als Wert verstanden werden oder die Tiere bloß gelernt haben, was Futter bringt."}],"familie":"gemeinsamer-glaube","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Beran, M. J.; Parrish, A. E. (2021): Non-human primate token use shows possibilities but also limitations for establishing a form of currency. Philosophical Transactions of the Royal Society B 376(1819), 20190675 (PMC-Volltext)","oeffentlich":true,"doi":"10.1098/rstb.2019.0675","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7815425/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Wolfe, J. B. (1936): Effectiveness of token-rewards for chimpanzees. Comparative Psychology Monographs 12(5) (zitiert nach Beran & Parrish)","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"1f6b04564b6fa704"}},{"id":"qx-e-043","clusterId":"E","werkstueckRef":"E.3.3","stufe":1,"question":"Eine Freundin sagt: „Ich habe keine Ideologie, ich bin einfach nur objektiv und pragmatisch. Wer anderer Meinung ist, folgt eben einer Ideologie.“ Welche Antwort trifft den Denkfehler am besten?","options":["Auch wer sich als objektiv bezeichnet, kann sich irren. Der Satz setzt „objektiv“ mit „richtig“ gleich, dabei kommt man auch ohne Ideologie manchmal zu falschen Ergebnissen.","Auch wer sich für rein pragmatisch hält, bringt Grundannahmen darüber mit, was gerecht ist oder was Probleme verursacht. Die Annahme, keine zu haben, macht sie nur unsichtbar.","Auch wer wirklich pragmatisch urteilt, sollte Andersdenkende anhören. Der Fehler liegt im zweiten Satz: Wer Gegenpositionen Ideologie nennt, muss sich mit ihren Gründen nicht befassen.","Auch wer eine Haltung hat, kann sich an Ergebnissen orientieren. Richtet sie ihre Urteile wirklich nur danach, was funktioniert, ist sie tatsächlich frei von Ideologie."],"correctIndex":1,"explanation":"Eine Ideologie ist ein zusammenhängendes System aus Überzeugungen und Werten, das erklärt, wie die Welt ist, und zugleich sagt, wie sie sein sollte. Solche Grundannahmen hat praktisch jeder, etwa darüber, was gerecht ist oder woher Leid kommt. Die Annahme, es gebe keine Ideologie, ist selbst Teil einer Ideologie, meist der dominanten, unsichtbaren der eigenen Kultur. Wer sich für ideologiefrei hält, übersieht also seine eigene Brille und erkennt sie nur bei anderen. Der Fehler liegt darin, die eigene Brille für das Fehlen einer Brille zu halten. Gute Gegenfrage: „Welche Annahmen über Gerechtigkeit und Ursachen stecken in meiner Position?“","coreRule":"⚡ Wer glaubt, keine Weltsicht zu haben, hat trotzdem eine, und gerade diese bleibt ihm unsichtbar.","beleg":"Werkstück E.3.3 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","kurz":"Fast jeder bringt Grundannahmen mit, etwa darüber, was gerecht ist oder woher Probleme kommen. Der Fehler: Die eigene Brille wird für das Fehlen einer Brille gehalten, sodass Ideologie nur bei den anderen sichtbar wird.","prueffrage":"Woran misst die Freundin, was „objektiv“ oder „pragmatisch“ ist, und würde jemand mit anderen Werten denselben Maßstab wählen?","rueckmeldung":[{"option":0,"text":"Dass auch Objektive irren können, stimmt. Der Satz der Freundin behauptet aber gar nicht, sie liege richtig, sondern, sie habe keine Ideologie. Dort liegt der Fehler: bei den Grundannahmen, die sie bei sich selbst nicht bemerkt."},{"option":2,"text":"Andersdenkende anzuhören ist sinnvoll, und das Etikett „Ideologie“ kann Gründe abwehren. Es setzt aber später an: Der Denkfehler steckt schon im ersten Satz, in der Annahme, die eigene Position komme ohne Grundannahmen aus."},{"option":3,"text":"Sich an Ergebnissen zu orientieren, ist vernünftig. Was als gutes Ergebnis zählt, hängt aber von Vorstellungen ab, was gerecht ist oder was ein Problem darstellt. Pragmatisch zu urteilen heißt daher nicht, ohne Grundannahmen zu urteilen."}],"familie":"weltsicht-sichtbar-machen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Pronin, E. (2007): Perception and misperception of bias in human judgment. Trends in Cognitive Sciences 11(1), 37–43 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1016/j.tics.2006.11.001","url":"https://pubmed.ncbi.nlm.nih.gov/17129749/","abruf":"2026-10-12"},{"typ":"url","kurz":"Scherr, K. (2007): The End of the End of Ideology. APS Observer (Bericht über J. T. Jost)","oeffentlich":true,"url":"https://www.psychologicalscience.org/observer/the-end-of-the-end-of-ideology","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"2bacda131bc01d8b"}},{"id":"qx-e-044","clusterId":"E","werkstueckRef":"E.3.3","stufe":2,"question":"Was ist hier die klügste nächste Gesprächsstrategie?","scenario":"Dein Onkel sieht die Welt durch eine feste politische Überzeugung. Auf jede Statistik, die du ihm zeigst, antwortet er: „Das ist doch Propaganda“ – und wechselt das Thema. Du hast ihm schon mehrere Studien und Quellen vorgelegt, ohne dass sich etwas bewegt hat.","options":["Weitere Studien aus anderen Quellen vorlegen, damit ihn die Menge der Belege überzeugt.","Ihm erklären, woran man Propaganda erkennt, damit er die Studien nicht mehr so nennt.","Fragen, woran er verlässliche Quellen erkennt und welche Belege ihn umstimmen könnten.","Die Studien noch einmal auf Methodenfehler prüfen, damit er keinen Angriffspunkt findet."],"correctIndex":2,"explanation":"Wer feste Überzeugungen hat, bewertet neue Informationen durch den Rahmen, den er schon mitbringt. Passt ein Fakt nicht hinein, wird er als Propaganda, Ausnahme oder irrelevant abgetan. Mehr Fakten desselben Typs ändern daran nichts, denn der Rahmen entscheidet, was überhaupt als Beleg zählt. Deshalb lohnt es sich, zuerst über die Spielregeln zu sprechen: Was zählt für ihn als verlässliche Quelle? Was müsste passieren, damit er seine Meinung ändert? Die anderen Schritte sind in anderen Lagen sinnvoll, helfen hier aber nicht: Weitere Studien nützen nichts, wenn er jede Quelle ohnehin als Propaganda abtut. Ihm zu erklären, woran man Propaganda erkennt, setzt voraus, dass er die Kriterien schon teilt, und wirkt wie ein Angriff auf sein Urteil. Und eine erneute Prüfung auf Methodenfehler wäre sinnvoll, wenn er die Methoden kritisierte, er weist aber jede Quelle pauschal zurück, ohne auf ihren Inhalt einzugehen.","coreRule":"⚡ Wenn Fakten abprallen, sprich über den Rahmen, nicht nur über die Daten.","beleg":"Werkstück E.3.3 (Anwendung & Relevanz: In der Politik; Kontext & Tiefe: Sich selbst immunisiert)","status":"entwurf","kurz":"Seine Antwort „Propaganda“ kommt nicht aus den Studien, sondern aus seinem Rahmen, der festlegt, was als Beleg zählt. Mehr Material ändert daran wenig; erst die Frage nach seinen Maßstäben und danach, was ihn umstimmen würde, rührt an den Kern.","prueffrage":"Was hat dein Onkel auf deine bisherigen Quellen jeweils geantwortet, und was haben diese Antworten gemeinsam?","rueckmeldung":[{"option":0,"text":"Mehr Belege wirken wie das natürliche Mittel, wenn bisherige nicht reichten. Wer aber jede Quelle schon vorab als Propaganda einordnet, wird auch die nächste so einordnen; mehr vom Gleichen trifft denselben Rahmen."},{"option":1,"text":"Das Wissen über Propaganda ist grundsätzlich nützlich. Hier setzt es aber voraus, dass er die Kriterien teilt, und kann als Angriff auf sein Urteil ankommen. Dann verteidigt er eher seine Haltung, als dass er nachdenkt."},{"option":3,"text":"Sorgfältige Methodenprüfung ist sinnvoll, wenn jemand die Methoden kritisiert. Dein Onkel nimmt aber gar nicht Stellung zu Details, sondern lehnt jede Quelle pauschal ab. Ohne konkreten Einwand gibt es keinen Angriffspunkt, den du ausräumen könntest."}],"familie":"weltsicht-sichtbar-machen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Kahan, D. M. (2013): Ideology, motivated reasoning, and cognitive reflection. Judgment and Decision Making 8(4), 407–424","oeffentlich":true,"url":"https://dlab.sauder.ubc.ca/sjdm/journal/13/13313/jdm13313.html","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"b2e6a49dd7965bfb"}},{"id":"qx-e-045","clusterId":"E","werkstueckRef":"E.3.3","stufe":3,"question":"Welche Beobachtung zeigt am deutlichsten, dass ihre Weltanschauung zum starren Dogma geworden ist?","options":["Die Weltanschauung beantwortet große Fragen umfassend und lässt ihren Mitgliedern dadurch kaum noch offene Fragen, die sie selbst klären müssten.","Die Weltanschauung gibt ihren Mitgliedern starken Zusammenhalt, und wer so fest in einer Gemeinschaft verankert ist, löst sich schwer von ihren Lehren.","Die Gruppe hält an ihrer Kernannahme fest, obwohl ein Mitglied eine widersprechende Studie vorlegt, und ändert ihre Überzeugung deshalb nicht.","Widersprechende Belege werden als Beweis für die Verblendung der Kritiker gewertet, und kein denkbares Ereignis könnte die Überzeugung erschüttern."],"correctIndex":3,"explanation":"Erklärung, Handlungsimpuls und Zusammenhalt sind normale Leistungen jeder Weltanschauung, auch einer gesunden; sie sagen nichts darüber, ob man noch aus Gegenbelegen lernen kann. Entscheidend ist die Frage, ob die Überzeugung noch widerlegbar ist. Wenn jeder Einwand zum Beweis für die Bösartigkeit oder Verblendung des Kritikers umgedeutet wird und es kein denkbares Ereignis gibt, das etwas ändern würde, dient die Weltanschauung nicht mehr dem Verständnis der Welt. Dann zählt die Treue zur eigenen Lehre mehr als das, was die Wirklichkeit zeigt.","coreRule":"⚡ Eine Weltanschauung wird starr, wenn nichts mehr sie widerlegen darf.","beleg":"Werkstück E.3.3 (Red Flags; Der Kipppunkt; Das Adaptive Talent)","status":"entwurf","scenario":"Eine Gruppe vertritt eine Weltanschauung, die große Fragen erklärt und ihren Mitgliedern Zusammenhalt gibt. Ein Mitglied legt ihr eine Studie vor, die einer ihrer Kernannahmen widerspricht. Die Gruppe antwortet: „Solche Studien werden von unseren Gegnern bezahlt. Wer sie ernst nimmt, ist blind für die Wahrheit.“ Auf Nachfrage räumt sie ein, dass es kein denkbares Ergebnis gäbe, das ihre Überzeugung ins Wanken brächte.","kurz":"Entscheidend ist nicht, dass die Gruppe viel erklärt oder zusammenhält, sondern dass sie Gegenbelege zum Beweis gegen die Kritiker umdeutet und nichts sie mehr widerlegen könnte. Ein Dogma erkennt man an der fehlenden Widerlegbarkeit.","prueffrage":"Was hat die Gruppe mit der vorgelegten Studie selbst gemacht, bevor sie antwortete?","rueckmeldung":[{"option":0,"text":"Dass eine Weltanschauung viele große Fragen beantwortet, gehört zu ihrer normalen Leistung und gilt auch für gesunde. Ob sie dogmatisch ist, zeigt sich erst daran, wie sie mit Gegenbelegen umgeht."},{"option":1,"text":"Starker Zusammenhalt macht den Abschied schwerer, das stimmt. Bindung ist aber noch kein Dogma, auch gesunde Gemeinschaften halten zusammen. Die Frage ist, ob die Überzeugung noch widerlegbar wäre."},{"option":2,"text":"Das Festhalten wirkt wie der Kern des Problems. Nach einer einzelnen Studie bei einer Annahme zu bleiben, kann aber vernünftig sein. Problematisch ist, wie die Gruppe den Einwand abwehrt und dass nichts sie je umstimmen könnte."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"57c75934d20a634a"}},{"id":"qx-e-046","clusterId":"E","werkstueckRef":"E.3.3","stufe":4,"question":"Eine Kollegin sagt im Team: „Ich habe keine Ideologie, ich bin rein pragmatisch.“ Welche Erwiderung nimmt ihre Aussage ernst und bleibt zugleich logisch tragfähig?","options":["„Auch wer nur schaut, was funktioniert, legt vorher fest, was als funktionierend zählt. Dahinter steckt eine Weltsicht, die oft unsichtbar bleibt, weil unser Umfeld sie teilt.“","„Dann lass uns genau das tun: vorher festlegen, woran wir Erfolg messen, und danach entscheiden. So bleibt die Entscheidung über das Programm frei von Weltanschauungen.“","„Pragmatisch zu sein ist auch eine Haltung, aber eine gute: Wer auf Ergebnisse schaut statt auf Grundsätze, kommt beim Förderprogramm wohl eher zu einem sachlichen Urteil.“","„Rein pragmatisch klingt gut, doch ein Förderprogramm lässt sich nicht nur nach seiner Wirkung beurteilen. Manchmal muss man zu Grundsätzen stehen, auch wenn sie wenig bringen.“"],"correctIndex":0,"explanation":"Jeder Mensch hat eine Ideologie, auch wer glaubt, rein „objektiv“ oder „pragmatisch“ zu sein. Die Annahme, es gebe gar keine, ist selbst Teil einer Ideologie, meist der dominanten, unsichtbaren Ideologie der eigenen Kultur. Das lässt sich so begründen: „Pragmatisch“ zu sein beantwortet nicht die Frage, woran man Erfolg misst, etwa an Kosten, an Gerechtigkeit, an Freiheit oder an Geschwindigkeit. Was als „funktionierend“ gilt, setzt also eine Gewichtung voraus, und die gehört zu einer Weltsicht, auch wenn sie sich nicht so anfühlt. Gerade die Weltsicht, die alle in der Umgebung teilen, fällt nicht mehr auf und wird mit „neutral“ verwechselt. Hilfreich ist die Frage, wie jemand mit einer ganz anderen Weltsicht die Lage beurteilen würde und woran er Erfolg messen würde.","coreRule":"⚡ Die unsichtbarste Brille ist die, die alle um dich herum auch tragen.","beleg":"Werkstück E.3.3 (Kontext & Tiefe; Anti-Denkmuster): „Eine Ideologie hat jeder, auch wenn er glaubt, rein ‚objektiv‘ oder ‚pragmatisch‘ zu sein.“","status":"entwurf","scenario":"In einer Besprechung über ein neues Förderprogramm wird heftig gestritten. Die Kollegin hält sich heraus und sagt: „Ich habe keine Ideologie, ich bin rein pragmatisch. Ich schaue nur, was funktioniert.“","quote":"Eine Ideologie hat jeder, auch wenn er glaubt, rein „objektiv“ oder „pragmatisch“ zu sein.","quoteLabel":"Merksatz:","kurz":"Wer nur schaut, was funktioniert, muss zuerst festlegen, woran er Erfolg misst, und diese Gewichtung gehört selbst zu einer Weltsicht. Der Denkfehler: Eine Sicht, die alle um uns teilen, wirkt neutral.","prueffrage":"Woran würde jemand mit ganz anderen Prioritäten bei diesem Programm merken, dass es „funktioniert“?","rueckmeldung":[{"option":1,"text":"Maßstäbe vorab festzulegen ist sinnvoll. Die Entscheidung bleibt dadurch aber nicht frei von Weltanschauung, denn ob man Kosten, Gerechtigkeit oder Tempo als Maßstab wählt, ist selbst eine Gewichtung."},{"option":2,"text":"Pragmatismus als Haltung zu benennen, ist richtig. Dass sie zu einem sachlicheren Urteil führt, ist aber unbelegt: Auch wer auf Ergebnisse schaut, hat vorher einen Maßstab gewählt, der nicht neutral ist."},{"option":3,"text":"Dass Wirkung nicht der einzige Maßstab sein muss, kann stimmen. Die Antwort tut aber so, als seien nur Grundsätze Weltanschauung und Wirkung neutral, dabei ist schon die Wahl, was als Wirkung zählt, eine Gewichtung."}],"familie":"weltsicht-sichtbar-machen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Pronin, E. (2007): Perception and misperception of bias in human judgment. Trends in Cognitive Sciences 11(1), 37–43 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1016/j.tics.2006.11.001","url":"https://pubmed.ncbi.nlm.nih.gov/17129749/","abruf":"2026-10-12"},{"typ":"url","kurz":"Pronin, E.; Gilovich, T.; Ross, L. (2004): Objectivity in the eye of the beholder: divergent perceptions of bias in self versus others. Psychological Review 111(3), 781–799 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1037/0033-295X.111.3.781","url":"https://pubmed.ncbi.nlm.nih.gov/15250784/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"e8dcbf594bb574ea"}},{"id":"qx-e-047","clusterId":"E","werkstueckRef":"E.3.4","stufe":1,"question":"Welche Schlussfolgerung ist am besten begründet?","options":["Die Kinder profitierten von einem Übungseffekt, denn wer dieselbe Art von Aufgaben ein zweites Mal löst, schneidet oft besser ab.","Die Kinder lagen nur zufällig vorn, denn per Los gezogene Kinder haben nichts gemeinsam, was ihren größeren Zuwachs ursächlich erklären könnte.","Die Kinder wurden durch die Teilnahme am Test motiviert, denn Menschen strengen sich oft mehr an, wenn sie sich beobachtet fühlen.","Die Kinder hatten Lehrkräfte mit höheren Erwartungen, denn die Auswahl war zufällig und nur die Erwartung der Lehrkräfte unterschied sich."],"correctIndex":3,"explanation":"Die Kinder wurden per Los gezogen, ihre angeblichen Testergebnisse waren erfunden. Die einzige Variable, die sich geändert hatte, war die Erwartungshaltung der Lehrkräfte. Als Wirkweg gilt das Verhalten der Lehrkräfte, das sich aus ihrer Erwartung ergeben kann: wärmerer Umgang, anspruchsvollere Aufgaben, klarere Rückmeldungen, mehr Gelegenheit zur Beteiligung. So kann eine bloße Erwartung selbst zur Ursache dessen werden, was sie vorhersagt. Vorsicht bei der Größenordnung: Im ursprünglichen Experiment von Rosenthal und Jacobson lag der Zuwachs bei rund zwölf statt acht IQ-Punkten, und der Vorsprung zeigte sich fast nur in der ersten und zweiten Klasse. Spätere Forschung findet solche Effekte meist klein und wenig dauerhaft. Die Schlussfolgerung betrifft deshalb die Ursache des Unterschieds, nicht ein großes, sicheres Ausmaß.","coreRule":"⚡ Wenn die Gruppen per Zufall gebildet wurden, bleibt als Ursache nur, was sich zwischen ihnen tatsächlich unterscheidet, hier die Erwartung.","beleg":"Werkstück E.3.4 (Einstieg: Die akademischen Überflieger); Fn. gl-e-rosenthal (Rosenthal & Jacobson 1966/1968)","status":"entwurf","scenario":"Ein Schulleiter lässt an einer Grundschule alle Kinder einen IQ-Test schreiben. Danach teilt er den Lehrkräften vertraulich mit, welche 20 % der Kinder laut Test im kommenden Jahr besonders stark aufblühen werden. Tatsächlich hat er die Namen per Los gezogen. Am Jahresende haben diese Kinder im Schnitt mehr dazugewonnen als ihre Mitschüler.","kurz":"Die Auswahl war ausgelost und nur die Erwartung der Lehrkräfte unterschied die Gruppen, also kann diese den Mehrzuwachs verursacht haben. Der Fehler wäre, einen Vorsprung für eine echte Begabung zu halten. Ein großes, sicheres Ausmaß folgt daraus nicht.","prueffrage":"Was wusste der Schulleiter über die Kinder, deren Namen er den Lehrkräften nannte?","rueckmeldung":[{"option":0,"text":"Wer Aufgaben wiederholt, wird oft besser, das stimmt. Doch alle Kinder schrieben denselben Test, ein Übungsgewinn betrifft also beide Gruppen gleich und erklärt den Unterschied zwischen ihnen nicht."},{"option":1,"text":"Dass per Los gezogen wurde, ist richtig. Gerade deshalb hatten die Gruppen vorher keinen Unterschied, den man verantwortlich machen könnte, und der Mehrzuwachs braucht eine Erklärung. Die liefert die eingeführte Erwartung der Lehrkräfte. Reiner Zufall ist als Erklärung deutlich schwächer."},{"option":2,"text":"Beobachtetwerden kann Kinder tatsächlich anspornen. Hier schrieben aber alle denselben Test, und nur die Lehrkräfte erfuhren die angeblichen Ergebnisse. Eine Motivation durch den Test träfe also beide Gruppen gleichermaßen und erklärt den Unterschied nicht."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Jussim, L.; Harber, K. D. (2005): Teacher Expectations and Self-Fulfilling Prophecies. Personality and Social Psychology Review 9(2), 131–155 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1207/s15327957pspr0902_3","url":"https://pubmed.ncbi.nlm.nih.gov/15869379/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Jussim, L.; Harber, K. D. (2005): Teacher Expectations and Self-Fulfilling Prophecies. Personality and Social Psychology Review 9(2) (Verlagsfassung)","oeffentlich":false,"seite":"134"},{"typ":"doi","kurz":"Rosenthal, R.; Jacobson, L. (1966): Teachers' Expectancies: Determinants of Pupils' IQ Gains. Psychological Reports 19(1), 115–118","oeffentlich":false,"doi":"10.2466/pr0.1966.19.1.115"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v7","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"b2a2132f327c81fe"}},{"id":"qx-e-048","clusterId":"E","werkstueckRef":"E.3.4","stufe":2,"question":"Welche Erklärung dafür, dass sich Fehler und Lustlosigkeit häufen, ist am sparsamsten und lässt sich am besten prüfen?","scenario":"Ein neuer Abteilungsleiter hält sein Team für wenig fähig. Er prüft jede Kleinigkeit nach und vergibt keine eigenständigen Aufgaben. Nach einigen Monaten häufen sich Fehler und Lustlosigkeit, und er sagt: „Ich habe es ja gewusst.“","options":["Seine Erwartung hat sein Verhalten geprägt, das Team reagierte mit Unsicherheit und Fehlern, die seine Erwartung scheinbar bestätigen.","Das Team ist tatsächlich so wenig fähig, wie er von Anfang an vermutet hat; die Fehler zeigen jetzt offen, was vorher schon so war.","Die Fehler gab es schon vorher; weil er jetzt jede Kleinigkeit nachprüft, fallen sie nur häufiger auf, ohne dass das Team schlechter arbeitet.","Der Wechsel an der Spitze hat das Team verunsichert; Fehler und Unlust gehören zu einer Übergangszeit, die sich mit der Zeit von selbst legt."],"correctIndex":0,"explanation":"Der Manager misstraut seinem Team, kontrolliert es engmaschig und überträgt keine Verantwortung. Wer so behandelt wird, wird oft unsicher und demotiviert und macht mehr Fehler, was die ursprüngliche Erwartung scheinbar bestätigt. So kann ein sich selbst verstärkender Kreislauf aus Überzeugung, Handlung, Selbstbild und Gegenhandlung entstehen (Golem-Effekt). Seine Aussage „Ich habe es ja gewusst“ taugt nicht als Beweis, denn die Fehler können Folge seines Verhaltens sein. Prüfen ließe sich das, indem man klärt, ob die Fehler schon vor seinem Kontrollverhalten auftraten oder erst danach, oder indem er probeweise Verantwortung überträgt und beobachtet, ob sich die Leistung ändert. Wichtig bleibt: Dass Erwartungen Leistungen beeinflussen können, zeigt sich im Klassenzimmer, die Effekte sind aber meist klein und wenig dauerhaft, und oft sagen Erwartungen Leistungen nur deshalb voraus, weil sie zutreffen. Deshalb braucht es einen Vergleich, bevor man sicher urteilt.","coreRule":"⚡ Wer von anderen wenig erwartet, bekommt oft genau das – und hält es für die Bestätigung. Prüfe darum, ob die Fehler vor oder nach dem eigenen Verhalten auftraten.","beleg":"Werkstück E.3.4 (Kontext & Tiefe: Kreislauf, Golem-Effekt; Anwendung & Relevanz: In der Führung & im Management)","status":"entwurf","kurz":"Wer misstraut und alles nachprüft, kann Unsicherheit und Fehler selbst hervorrufen, die dann die Erwartung zu bestätigen scheinen. „Ich habe es ja gewusst“ beweist daher nichts, denn die Fehler können Folge seines Verhaltens sein.","prueffrage":"Waren die Fehler und die Lustlosigkeit schon da, bevor er mit der Kontrolle begann, oder erst danach?","rueckmeldung":[{"option":1,"text":"Dass das Team schwach ist, lässt sich nicht ausschließen, und Erwartungen sagen oft Leistungen voraus, weil sie zutreffen. Aber „Ich habe es ja gewusst“ beweist es nicht, denn die Fehler können auch erst durch seine Kontrolle entstanden sein."},{"option":2,"text":"Mehr Kontrolle kann tatsächlich mehr Fehler sichtbar machen, das lässt sich prüfen. Die Option erklärt aber die Lustlosigkeit nicht und setzt voraus, dass sich die Arbeit nicht verändert hat; gerade das ist offen, denn Unsicherheit kann selbst Fehler hervorbringen."},{"option":3,"text":"Ein Führungswechsel kann ein Team durchaus verunsichern, und Übergangszeiten gibt es. Doch im Szenario häufen sich die Fehler nach Monaten, statt abzuklingen, und dass sich das von selbst legt, ist ungeprüft. Auch bleibt seine engmaschige Kontrolle als Ursache unberücksichtigt."}],"familie":"erwartung-erfuellt-sich","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Jussim, L.; Harber, K. D. (2005): Teacher Expectations and Self-Fulfilling Prophecies. Personality and Social Psychology Review 9(2), 131–155 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1207/s15327957pspr0902_3","url":"https://pubmed.ncbi.nlm.nih.gov/15869379/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"e25e74e143ad0f5c"}},{"id":"qx-e-049","clusterId":"E","werkstueckRef":"E.3.4","stufe":3,"question":"Welche Einschätzung des Forschungsstands ist angemessen?","options":["Der Effekt ist belegt, aber meist klein und wenig dauerhaft; dass er die Intelligenz tatsächlich verändert, ist offen, und Erwartungen treffen oft auch einfach zu.","Der Effekt ist belegt und in der Originalstudie deutlich; dass Erwartungen die Intelligenz steigern, ist damit gezeigt, auch wenn spätere Effekte kleiner ausfielen.","Der Effekt ist eher ein Scheinbefund; weil Lehrkräfte die Leistungen vorab treffend einschätzen, erfüllen sich ihre Erwartungen nicht, sondern sie treffen bloß zu.","Der Effekt ist belegt, wirkt aber vor allem in den ersten Schuljahren; dort steigert er die Intelligenz spürbar, in höheren Klassen spielt er dagegen kaum eine Rolle."],"correctIndex":0,"explanation":"Die Behauptung „beweist, dass … allein durch Erwartungen steigern“ geht weit über die Datenlage hinaus. Spätere Forschung bestätigt, dass Lehrererwartungen Schülerleistungen beeinflussen können, findet die Effekte aber meist klein und wenig dauerhaft. Ob dadurch die Intelligenz selbst steigt, ist ungeklärt. Dazu kommt: Lehrererwartungen sagen Leistungen oft deshalb voraus, weil sie zutreffen, nicht weil sie sich erfüllen. Schon die Originalstudie spricht gegen eine große, allgemeine Wirkung: Der Vorsprung stammte fast ganz aus den ersten beiden Klassen und zeigte sich in höheren Klassen nicht. Wer sauber urteilt, hält deshalb beides auseinander: Dass es selbsterfüllende Prophezeiungen im Klassenzimmer gibt, ist belegt, aber meist klein; dass sie die Intelligenz verändern, ist offen.","coreRule":"⚡ „Erwartungen wirken“ ist belegt – „Erwartungen machen klüger“ ist es nicht.","beleg":"Werkstück E.3.4 (Hinweis zur Beleglage); Fn. gl-e-rosenthal (Jussim & Harber 2005, S. 131, 134 f., 140, 142 f.)","status":"entwurf","scenario":"In einem Lehrbuch steht: „Rosenthals Studie von 1966 beweist, dass Lehrer die Intelligenz ihrer Schüler allein durch Erwartungen steigern können.“ Du liest nach: In der Originalstudie erhielten zufällig ausgewählte Kinder („Überflieger“) einen Zuwachs von rund zwölf statt acht IQ-Punkten, und dieser Vorsprung zeigte sich fast nur in der ersten und zweiten Klasse. Spätere Untersuchungen fanden selbsterfüllende Prophezeiungen im Klassenzimmer zwar immer wieder, aber meist klein und oft nicht von Dauer. Außerdem schätzen Lehrkräfte die Leistungen ihrer Schüler oft schon vorab recht treffend ein.","kurz":"Dass Erwartungen Leistungen beeinflussen können, ist belegt, die Effekte sind aber meist klein und wenig dauerhaft. Ob sie die Intelligenz selbst ändern, ist offen, denn Einschätzungen von Lehrkräften treffen oft schlicht zu. „Beweist“ geht daher zu weit.","prueffrage":"Wie groß war der Vorsprung der „Überflieger“ gegenüber den übrigen Kindern in IQ-Punkten, und in welchen Klassen trat er auf?","rueckmeldung":[{"option":1,"text":"Die Originalstudie zeigt tatsächlich einen sichtbaren Vorsprung. Dass Erwartungen die Intelligenz steigern, folgt daraus aber nicht: Der Vorsprung stammt fast nur aus den ersten beiden Klassen, spätere Effekte waren meist klein und oft nicht von Dauer, und Einschätzungen treffen oft einfach zu."},{"option":2,"text":"Dass Lehrkräfte Leistungen vorab oft treffend einschätzen, ist richtig und erklärt einen Teil der Vorhersagekraft. Daraus folgt aber kein Scheinbefund: Selbsterfüllende Prophezeiungen im Klassenzimmer wurden immer wieder gefunden, meist nur klein. Treffen erklärt vieles, aber nicht alles."},{"option":3,"text":"Dass sich der Vorsprung fast nur in den ersten beiden Klassen zeigte, stimmt. Offen bleibt aber, ob dort die Intelligenz selbst stieg. Und später fand man Erwartungseffekte durchaus immer wieder, nur meist klein und oft nicht von Dauer, während Einschätzungen oft ohnehin zutreffen."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Jussim, L.; Harber, K. D. (2005): Teacher Expectations and Self-Fulfilling Prophecies. Personality and Social Psychology Review 9(2), 131–155 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1207/s15327957pspr0902_3","url":"https://pubmed.ncbi.nlm.nih.gov/15869379/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Jussim, L.; Harber, K. D. (2005): Teacher Expectations and Self-Fulfilling Prophecies. Personality and Social Psychology Review 9(2) (Verlagsfassung)","oeffentlich":false,"seite":"134"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"a8a831ce04921a5c"}},{"id":"qx-e-050","clusterId":"E","werkstueckRef":"E.3.4","stufe":4,"question":"Wie sicher darfst du aus diesem Befund sein, und welche Schlussfolgerung ist angemessen?","options":["Der Mechanismus ist für Mädchen in Mathematik gestützt, denn die Studie zeigt bei afroamerikanischen Schülern deutliche Effekte, und derselbe Vorgang wirkt auch bei Mädchen.","Der Mechanismus ist plausibel, für Mädchen in Mathematik aber nicht belegt; die Studie spricht dagegen und zeigt deutlichere Effekte bei afroamerikanischen Schülern.","Der Mechanismus ist für Mädchen in Mathematik widerlegt; die Studie zeigt bei ihnen keinen stärkeren Effekt als bei Jungen, also wirken Erwartungen hier überhaupt nicht.","Der Mechanismus bleibt für Mädchen in Mathematik vorerst gültig, denn ein einzelner Befund wiegt weniger als eine schlüssige Argumentation, auch wenn er dagegen spricht."],"correctIndex":1,"explanation":"Die Argumentation ist logisch glatt, aber sie behauptet einen Effekt, den man messen kann, und die Messung stützt ihn für diese Gruppe nicht: Bei Mädchen in Mathematik wirkten Lehrererwartungen in der großen Studie nicht stärker als bei Jungen, bei afroamerikanischen Schülern und bei leistungsschwachen Kindern aus ärmeren Familien dagegen deutlich stärker. Damit ist weder bewiesen, dass der Effekt überall wirkt, noch, dass es ihn nirgends gibt. Das Gesamtbild nennen die Autoren für diese Gruppenbefunde „mixed“; ob Stereotype so einen Golem-Effekt im großen Stil auslösen, ist offen. Ein einleuchtender Mechanismus liefert eine Hypothese, keinen Beleg; ob und bei wem er greift, entscheiden die Daten.","coreRule":"⚡ Ein einleuchtender Mechanismus ist noch kein belegter Effekt in jeder Gruppe.","beleg":"Werkstück E.3.4 (Anwendung & Relevanz: Im Umgang mit sozialen Stereotypen); Fn. gl-e-rosenthal (Jussim & Harber 2005)","status":"entwurf","scenario":"In einer Diskussion heißt es: „Stereotype sind negative Erwartungen. Negative Erwartungen verschlechtern Leistungen. Also verschlechtert das Stereotyp ‚Mädchen sind schlecht in Mathe' die Mathematikleistungen von Mädchen.“ Du kennst eine große Studie zu Lehrererwartungen: Bei Mädchen in Mathematik wirkten die Erwartungen nicht stärker als bei Jungen. Deutlich stärker wirkten sie bei afroamerikanischen Schülern und bei leistungsschwachen Kindern aus ärmeren Familien.","kurz":"Der Mechanismus klingt schlüssig, ist für Mädchen in Mathematik aber nicht belegt: Die Studie fand bei ihnen keinen stärkeren Effekt als bei Jungen. Ein einleuchtender Mechanismus ist eine Hypothese, ob und bei wem er greift, zeigen erst die Daten.","prueffrage":"Was ließe sich an Leistungsdaten von Mädchen und Jungen messen, wenn der behauptete Effekt tatsächlich bestünde?","rueckmeldung":[{"option":0,"text":"Dass Erwartungen bei afroamerikanischen Schülern deutlich wirkten, macht den Mechanismus vorstellbar. Auf Mädchen lässt sich das aber nicht übertragen: Die Studie zeigt gerade, dass die Wirkung je nach Gruppe verschieden ausfällt."},{"option":2,"text":"Bei Mädchen zeigte sich tatsächlich kein stärkerer Effekt als bei Jungen. „Nicht stärker als bei Jungen“ ist aber ein Vergleich und kein Nachweis, dass überhaupt keine Wirkung besteht. Offen ist die Frage, nicht entschieden."},{"option":3,"text":"Einzelne Studien sollte man vorsichtig gewichten, das stimmt. Doch eine bloße Überlegung, so schlüssig sie klingt, bleibt eine Hypothese. Eine große Messung, die sie für diese Gruppe nicht stützt, darf man nicht einfach beiseiteschieben."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Jussim, L.; Harber, K. D. (2005): Teacher Expectations and Self-Fulfilling Prophecies. Personality and Social Psychology Review 9(2), 131–155 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1207/s15327957pspr0902_3","url":"https://pubmed.ncbi.nlm.nih.gov/15869379/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Jussim, L.; Harber, K. D. (2005): Teacher Expectations and Self-Fulfilling Prophecies. Personality and Social Psychology Review 9(2) (Verlagsfassung)","oeffentlich":false,"seite":"142 f."}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"9914e569687d2839"}},{"id":"qx-e-051","clusterId":"E","werkstueckRef":"E.3.5","stufe":1,"question":"Eine Kommentatorin sagt: „Vor zwanzig Jahren hätte kein Politiker einen Vorschlag wie diesen öffentlich gemacht, heute wird er in Talkshows ernsthaft diskutiert. Dabei hat sich an den Argumenten kaum etwas geändert.“ Welche Schlussfolgerung passt am besten zu dieser Beobachtung?","options":["Der Rahmen des öffentlich Akzeptablen hat sich verschoben, sodass die Idee nun diskutierbar geworden ist.","Durch häufiges Hören hat sich die Öffentlichkeit an die Idee gewöhnt (Mere-Exposure-Effekt) und stimmt ihr nun zu.","In offener Debatte setzen sich stärkere Argumente durch, sodass die Idee diese Prüfung nun bestanden hat.","Kritiker schweigen aus Angst vor Isolation (Schweigespirale), sodass die Idee in Talkshows weit verbreitet wirkt."],"correctIndex":0,"explanation":"Die Beobachtung sagt nur, dass die Idee heute besprochen wird, nicht dass sie überzeugt oder mehrheitsfähig geworden ist. Politische Veränderung entsteht oft nicht dadurch, dass man die Wähler überzeugt, sondern dadurch, dass sich das „Fenster der Akzeptanz“ (das Overton-Fenster, benannt nach Joseph P. Overton) langsam verschiebt: Eine Idee kann also vom Undenkbaren zum Diskutablen werden, ohne dass die Mehrheit sie schon befürwortet. Wer aus „wird diskutiert“ auf „wird mehrheitlich befürwortet“ oder „war schon immer richtig“ schließt, verwechselt Sagbarkeit mit Zustimmung bzw. Wahrheit.","coreRule":"⚡ Dass etwas diskutiert wird, heißt nicht, dass es überzeugt hat. Prüfe, ob sich die Argumente geändert haben oder nur das, was als sagbar gilt.","beleg":"Werkstück E.3.5 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Aus der Beobachtung folgt nur, dass die Idee heute sagbar ist, nicht dass sie überzeugt. Der naheliegende Fehler ist, „wird diskutiert“ mit „wird befürwortet“ oder „ist richtig“ zu verwechseln, obwohl sich nur der Rahmen des Akzeptablen verschoben haben kann.","prueffrage":"Was hat sich laut Kommentatorin in zwanzig Jahren verändert, und was ist gleich geblieben?","rueckmeldung":[{"option":1,"text":"Dass häufiges Hören vertraut machen kann, ist ein bekannter Effekt. Die Beobachtung sagt aber nur, dass der Vorschlag besprochen wird, von Zustimmung ist nirgends die Rede. Diese Antwort macht aus „wird diskutiert“ stillschweigend „wird befürwortet“."},{"option":2,"text":"Offene Debatte kann bessere Argumente stärken. Hier hat sich aber an den Argumenten kaum etwas geändert, sie können also nicht der Grund für den Wandel sein. Auch dass die Idee eine Prüfung bestanden hätte, steht nirgends."},{"option":3,"text":"Eine Schweigespirale kann den Eindruck verbreiteter Meinungen erzeugen. Im Beispiel wird aber niemand als verstummt beschrieben, und es geht um das, was gesagt werden darf, nicht um einen vorgetäuschten Mehrheitseindruck. Für Angst vor Isolation gibt es keinen Hinweis."}],"familie":"sagbarkeit-verschiebt-sich","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Mackinac Center for Public Policy: The Overton Window","oeffentlich":true,"url":"https://www.mackinac.org/OvertonWindow","abruf":"2026-10-12"},{"typ":"url","kurz":"Lehman, J. G. (2023): The legacy of the Overton Window. Mackinac Center for Public Policy, Blog, 30.06.2023","oeffentlich":true,"url":"https://www.mackinac.org/blog/2023/the-legacy-of-the-overton-window","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"2a08419b33d26c58"}},{"id":"qx-e-052","clusterId":"E","werkstueckRef":"E.3.5","stufe":2,"question":"In einer Gesellschaft, in der Rauchen überall normal ist, gilt ein Rauchverbot in Innenräumen zunächst als politisch undenkbar. Jahre später schlägt eine gemäßigte Gruppe vor: „Vielleicht nicht überall, aber in Krankenhäusern.“ Dieser Vorschlag findet breite Zustimmung. Was erklärt das am besten?","options":["Der Kompromisseffekt: Menschen wählen zwischen zwei Lagern gern die Mitte, sodass ein Teilverbot leichter Zustimmung findet als ein volles Verbot.","Das Overton-Fenster: Hartnäckige Verfechter rückten die Idee vom Undenkbaren zum Radikalen, sodass der Kompromiss nun gemäßigt wirkt.","Die Schutzbedürftigkeit: In Krankenhäusern liegen kranke Menschen, sodass ein Rauchverbot dort leichter zu begründen ist als anderswo.","Der Mitläufereffekt: Sobald eine Gruppe einen Vorschlag öffentlich vertritt, schließen sich viele an, sodass er rasch breite Zustimmung findet."],"correctIndex":1,"explanation":"Politische Ideen gelten nicht aus sich heraus als „radikal“ oder „vernünftig“, sondern immer relativ zu dem, was eine Gesellschaft gerade für akzeptabel hält. Das Overton-Fenster beschreibt diese Bandbreite des öffentlich Akzeptablen. Es kann dazu beitragen, dass eine zuvor undenkbare Forderung wiederholt vorgetragen wird, Studien erscheinen und Medien das Thema aufgreifen: Die Idee rückt dann von „undenkbar“ zu „radikal“. Erst dadurch wirkt ein abgeschwächter Vorschlag wie ein vernünftiger Mittelweg. Zugleich verschiebt sich das Fenster meist durch den langsamen Wandel von Werten und Normen. Niemand muss dafür über Nacht überzeugt werden: Verschoben hat sich der Rahmen dessen, was als akzeptable Meinung gilt.","coreRule":"⚡ Ein „vernünftiger Kompromiss“ ist oft nur deshalb vernünftig, weil der Rahmen des Akzeptablen sich vorher verschoben hat.","beleg":"Werkstück E.3.5 (Einstieg: Die Debatte, die niemand wollte; Kernidee)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Zustimmung entsteht hier, weil sich über Jahre verschob, was als akzeptabel gilt: Das Verbot rückte vom Undenkbaren zum Radikalen, und erst daneben wirkt der Teilvorschlag gemäßigt. Bei einem fest gedachten Maßstab sähe man diese Verschiebung nicht.","prueffrage":"Wie wurde der Krankenhaus-Vorschlag früher eingeschätzt, und was hat sich zwischen damals und heute verändert?","rueckmeldung":[{"option":0,"text":"Die Neigung zur Mitte gibt es wirklich. Sie erklärt aber nicht, warum das Teilverbot erst Jahre später Zustimmung findet, obwohl beide Pole schon vorher bekannt waren. Entscheidend ist, was inzwischen als akzeptabel gilt."},{"option":2,"text":"Kranke zu schützen ist ein gutes Argument, und es stimmt, dass es den Vorschlag stützt. Dieses Argument gab es aber auch früher, als der Vorschlag noch undenkbar war. Es erklärt also nicht, was sich geändert hat."},{"option":3,"text":"Dass sich Menschen einer sichtbaren Gruppe anschließen, kommt vor. Hier greift es zu kurz: Es erklärt nicht, warum derselbe Vorschlag Jahre früher keine Zustimmung fand. Verschoben hat sich der Rahmen des Akzeptablen, nicht nur die Zahl der Anhänger."}],"familie":"sagbarkeit-verschiebt-sich","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Mackinac Center for Public Policy: The Overton Window","oeffentlich":true,"url":"https://www.mackinac.org/OvertonWindow","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"6a52fb686883aca5"}},{"id":"qx-e-053","clusterId":"E","werkstueckRef":"E.3.5","stufe":3,"question":"Zwei Beobachter diskutieren über das Overton-Fenster, ein Modell dafür, was in der Öffentlichkeit als akzeptable Meinung gilt. Beobachterin A sagt: „Das Modell zeigt, dass solche Verschiebungen dessen, was gesagt werden darf, gefährlich sind.“ Beobachter B sagt: „Das Modell zeigt, dass solche Verschiebungen gesellschaftlichen Fortschritt bedeuten.“ Wie lässt sich der Denkfehler beider am besten auflösen?","options":["Das Modell beschreibt nur, dass sich Grenzen verschieben; ob das gut oder schlecht ist, hängt von Richtung und Inhalt der jeweiligen Idee ab.","Das Modell zeigt Licht und Schatten zugleich; Verschiebungen bringen mal Fortschritt, mal Gefahr, also haben beide Beobachter je zur Hälfte recht.","Das Modell zeigt, was eine Mehrheit annimmt; ob eine Verschiebung gut ist, entscheidet sich daran, ob die neue Idee am Ende breit getragen wird.","Das Modell beschreibt Verschiebungen; ob eine gut ist, entscheidet ihr Tempo, denn was über Jahrzehnte wächst, ist reifer als rasch Durchgesetztes."],"correctIndex":0,"explanation":"Das Overton-Fenster ist ein neutrales Modell zur Beschreibung von sozialem Wandel: Es sagt, welche Ideen gerade als akzeptabel gelten und wie sich das ändern kann, aber nicht, ob eine Verschiebung wünschenswert ist. Die Gefahr liegt nicht im Modell, sondern in der Richtung der Verschiebung. Dieselbe Mechanik trug das Frauenwahlrecht und Umweltschutzgesetze in den Mainstream, sie dient aber auch extremistischen Bewegungen, die ihre fremdenfeindlichen oder autoritären Ideen als „akzeptabel“ oder „vernünftig“ erscheinen lassen wollen. A schließt von „Verschiebung möglich“ auf „Verschiebung gefährlich“, B auf „Verschiebung gut“. Beides überspringt die Bewertung des Inhalts und der Richtung.","coreRule":"⚡ Ein Modell beschreibt, wie sich etwas verändert, nicht ob es gut ist – bewerten musst du Richtung und Inhalt der Veränderung.","beleg":"Werkstück E.3.5 (Der Kipppunkt; Anwendung & Relevanz)","status":"entwurf","scenario":"Das Overton-Fenster beschreibt, welche Ideen zu einem bestimmten Zeitpunkt als akzeptabel gelten. Früher undenkbare Ideen wie das Frauenwahlrecht, Umweltschutzgesetze oder Rauchverbote in öffentlichen Gebäuden wanderten über Jahrzehnte in den Mainstream. Extremistische Bewegungen versuchen ebenfalls, ihre Positionen schrittweise als „akzeptabel“ oder „vernünftig“ erscheinen zu lassen.","kurz":"Das Overton-Fenster beschreibt nur, dass sich Grenzen verschieben, und bewertet nichts. Der Fehler beider Beobachter: Sie machen aus „Verschiebung möglich“ ein Urteil, statt Inhalt und Richtung der jeweiligen Idee zu prüfen.","prueffrage":"Wie würden A und B das Frauenwahlrecht beurteilen, und wie die Vorstöße extremistischer Bewegungen?","rueckmeldung":[{"option":1,"text":"Dass Verschiebungen mal Fortschritt, mal Gefahr bringen können, stimmt. Das Modell selbst zeigt aber keines von beiden, und die beiden haben nicht je „zur Hälfte“ recht: Beide urteilen aus der bloßen Möglichkeit einer Verschiebung, ohne auf den Inhalt zu schauen."},{"option":2,"text":"Das Fenster beschreibt tatsächlich, was gerade als akzeptabel gilt. Breite Zustimmung ist aber kein Maßstab dafür, ob eine Idee gut ist, denn auch extremistische Positionen wollen genau diese Zustimmung erreichen. Entscheidend bleiben Inhalt und Richtung."},{"option":3,"text":"Frauenwahlrecht und Umweltschutz brauchten tatsächlich Jahrzehnte. Das Tempo sagt aber nichts über den Wert einer Idee, denn auch Extremisten verschieben Grenzen schrittweise. Ob eine Verschiebung gut ist, zeigt erst ihr Inhalt."}],"familie":"sagbarkeit-verschiebt-sich","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Mackinac Center for Public Policy: The Overton Window","oeffentlich":true,"url":"https://www.mackinac.org/OvertonWindow","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"6e3a8caab9b744f9"}},{"id":"qx-e-054","clusterId":"E","werkstueckRef":"E.3.5","stufe":4,"question":"Ein Artikel behauptet: „Joseph Overton hat die sechs Stufen von ‚undenkbar‘ bis ‚Politik‘ entwickelt, und Politiker verschieben das Fenster gezielt selbst.“ Du findest dazu eine Quelle, in der sein Kollege Joseph Lehman (selbst Mitarbeiter des Thinktanks, in dem Overton arbeitete) Overtons Rolle beschreibt. Lehman schreibt: Overton habe das Konzept Mitte der 1990er-Jahre entwickelt, Lehman selbst habe es nach Overtons Tod benannt und formalisiert; Overton habe dazu nie eine Arbeit veröffentlicht, und der Thinktank zeige das Fenster heute ohne die sechs Stufen. Politiker verschöben es nur selten selbst, meist wandle es sich durch den langsamen Wandel von Werten und Normen. Was ist die am besten begründete Schlussfolgerung für den Artikel?","options":["Die Behauptung ist in beiden Teilen überzogen: Die Sechs-Stufen-Skala lässt sich Overton nicht als eigener Wortlaut zuschreiben, und dass Politiker das Fenster gezielt verschieben, ist eher die Ausnahme.","Die Behauptung bleibt im Kern richtig: Ob ein Konzept taugt, hängt nicht davon ab, wer es erfunden hat, und die Skala beschreibt das Phänomen auch dann brauchbar, wenn Lehman sie benannte.","Die Behauptung ist falsch, weil Overton nie etwas veröffentlicht hat: Wer zu einem Konzept keine Arbeit vorlegt, kann es nicht entwickelt haben, und die Skala stammt deshalb allein von Lehman.","Die Behauptung ist glaubwürdiger als Lehmans Darstellung, weil sie in vielen Texten so steht: Was breit wiederholt wird, trifft meist im Kern zu, und Lehman schildert nur eine Außenseitersicht."],"correctIndex":0,"explanation":"Die Quelle stammt von einem direkten Kollegen Overtons und beschreibt dessen Rolle nüchtern: Overton entwickelte das Konzept Mitte der 1990er-Jahre, Lehman benannte und formalisierte es erst nach Overtons Tod, und Overton hat dazu nie eine Arbeit veröffentlicht. Die beliebte Sechs-Stufen-Skala ist Overtons eigener Wortlaut nicht, sondern eine spätere, gebräuchliche Ausarbeitung; auch der Thinktank selbst zeigt das Fenster heute ohne diese Stufen. Beim zweiten Teil gilt: Politiker können das Fenster mitunter selbst verschieben, aber das ist selten; meist wandeln sich Werte und Normen langsam, und Lehman nennt als Hebel Thinktank-Forschung, Analyse und Debatte. Der Artikel schreibt Overton also die Skala als eigenes Werk zu und überschätzt die Rolle der Politiker. Die anderen Schlussfolgerungen greifen für sich bekannte Gedanken auf, tragen aber hier nicht: Ob ein Konzept taugt, ist eine andere Frage als die, wem es zuzuschreiben ist, und der Artikel behauptet eine Zuschreibung. Dass Overton nichts veröffentlicht hat, heißt nicht, dass er das Konzept nicht entwickelt hat, und Lehman sagt ausdrücklich das Gegenteil. Eine Darstellung wird nicht dadurch richtiger, dass sie oft wiederholt wird, während Lehman als Kollege Overtons aus erster Hand berichtet.","coreRule":"⚡ Prüfe bei einem bekannten Modell, wie viel davon vom Urheber stammt und wie viel später dazugekommen ist.","beleg":"Werkstück E.3.5 (Kontext & Tiefe); Fn. gl-e-overton (Lehman 2023, Mackinac Center)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Die Quelle stammt von einem Kollegen aus erster Hand und widerspricht dem Artikel in beiden Teilen: Die Skala ist eine spätere Ausarbeitung, und Politiker verschieben das Fenster nur selten. Weit verbreitet heißt nicht belegt.","prueffrage":"Wer hat laut Quelle wann was zum Konzept beigetragen, und wer verschiebt das Fenster nach Lehmans Darstellung meistens?","rueckmeldung":[{"option":1,"text":"Dass ein Konzept unabhängig von seinem Urheber taugen kann, stimmt. Der Artikel macht aber Aussagen über die Herkunft der Skala und die Rolle der Politiker, nicht über ihre Brauchbarkeit. Genau diese Aussagen stützt die Quelle nicht."},{"option":2,"text":"Daran stimmt: Die Sechs-Stufen-Skala stammt nicht von Overton selbst. Fehlende Veröffentlichungen heißen aber nicht, dass er nichts entwickelt hat; Lehman schreibt ihm das Konzept ausdrücklich zu und hat es nur benannt und formalisiert."},{"option":3,"text":"Häufig Wiederholtes wirkt vertraut und damit glaubwürdig. Wie oft etwas steht, sagt aber nichts darüber, ob es stimmt. Lehman arbeitete im selben Thinktank wie Overton und berichtet aus erster Hand, er ist also keine Außenseitersicht."}],"familie":"zitat-am-original-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Lehman, J. G. (2023): The legacy of the Overton Window. Mackinac Center for Public Policy, Blog, 30.06.2023","oeffentlich":true,"url":"https://www.mackinac.org/blog/2023/the-legacy-of-the-overton-window","abruf":"2026-10-12"},{"typ":"url","kurz":"Mackinac Center for Public Policy: The Overton Window","oeffentlich":true,"url":"https://www.mackinac.org/OvertonWindow","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"de0f974e3c0d5a6e"}},{"id":"qx-e-055","clusterId":"E","werkstueckRef":"E.3.6","stufe":1,"question":"Eine Freundin sagt: „Ich habe es genau gesehen, ich weiß, was passiert ist. Meine Augen haben doch einfach aufgezeichnet, was da war.“ Welche Antwort trifft die Lage am besten?","options":["Wahrnehmung ist eine Vermutung des Gehirns aus lückenhaften Sinnesdaten und Erwartungen, und im Dämmerlicht kann die Erwartung gewinnen.","Wahrnehmung ist eine Aufzeichnung, die im Dämmerlicht unscharf wird, und erst die spätere Erinnerung hat aus dem Umriss einen klaren Mann gemacht.","Wahrnehmung zeichnet zuverlässig auf, solange das Licht reicht, und im Dämmerlicht fehlten den Augen einfach Daten, um den Busch zu erkennen.","Wahrnehmung folgt oft dem Schreck, und weil sie im Dämmerlicht erschrocken ist, hat erst die Angst aus dem Busch einen Mann gemacht."],"correctIndex":0,"explanation":"Das Gehirn arbeitet als Vorhersagemaschine: Es erstellt ständig Modelle dessen, was es zu sehen erwartet, und die Sinnesdaten dienen vor allem dazu, diese Vorhersagen zu korrigieren. Sind die Daten mehrdeutig (Dämmerung, ein menschenähnlicher Umriss), gewinnt oft die Erwartung. Das Gefühl von Klarheit sagt deshalb nichts darüber, ob die Wahrnehmung stimmt. Wahrnehmung ist keine passive Aufzeichnung, sondern eine „kontrollierte Halluzination“: eine beste Vermutung des Gehirns, die mit den Sinnesdaten abgeglichen wird.","coreRule":"⚡ Wir sehen nicht, was da ist, sondern die beste Vermutung unseres Gehirns darüber. Wie sicher sich eine Wahrnehmung anfühlt, sagt nichts darüber, ob sie stimmt.","beleg":"Werkstück E.3.6 (Kernidee; Kontext & Tiefe); Fn. gl-e-halluzination (Grush 2004, S. 393; Seth 2016)","status":"entwurf","scenario":"Beim Spaziergang im Dämmerlicht erschrickt jemand vor einem „Mann“ am Wegrand. Beim Näherkommen ist es ein Busch. Hinterher beharrt die Person darauf, sie habe die ganze Zeit klar einen Menschen gesehen.","kurz":"Das Gehirn rät aus lückenhaften Daten ein Modell und gleicht es mit den Sinnen ab. Im Dämmerlicht kann die Erwartung gewinnen. Der Fehler: Klarheit für ein Zeichen von Richtigkeit zu halten, obwohl das Gefühl nichts über die Genauigkeit sagt.","prueffrage":"Was war im Dämmerlicht tatsächlich zu erkennen, bevor die Person näher kam?","rueckmeldung":[{"option":1,"text":"Dass Erinnerung Dinge umdeutet, stimmt grundsätzlich. Hier aber erschrickt die Person schon beim Hinsehen vor dem „Mann“: Die Deutung geschah also im Moment des Sehens selbst und nicht erst später im Gedächtnis."},{"option":2,"text":"Im Dämmerlicht sind die Daten tatsächlich dürftig. Fehlende Daten würden aber eher einen unscharfen Fleck ergeben, keinen klaren Mann. Dass der Umriss so eindeutig erschien, zeigt, dass das Gehirn aktiv ergänzt, auch bei gutem Licht."},{"option":3,"text":"Gefühle können die Wahrnehmung färben, das ist nicht falsch. Das Szenario nennt aber keinen vorherigen Schreck, sondern der Schreck folgt dem Anblick eines „Mannes“. Die Deutung kam zuerst, und sie entsteht aus Erwartung und mehrdeutigen Daten, nicht aus Angst."}],"familie":"erinnerung-ist-rekonstruktion","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Powers, A. R.; Kelley, M.; Corlett, P. R. (2016): Hallucinations as Top-Down Effects on Perception. Biological Psychiatry: CNNI 1(5) (Autorenmanuskript frei in PMC5469545)","oeffentlich":true,"doi":"10.1016/j.bpsc.2016.04.003"},{"typ":"url","kurz":"Seth, A. K. (2016): The real problem. Aeon, 2.11.2016","oeffentlich":true,"url":"https://aeon.co/essays/the-hard-problem-of-consciousness-is-a-distraction-from-the-real-one"},{"typ":"doi","kurz":"Grush, R. (2004): The emulation theory of representation. Behavioral and Brain Sciences 27(3)","oeffentlich":false,"doi":"10.1017/S0140525X04000093"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"daa7a3103dbb901c"}},{"id":"qx-e-056","clusterId":"E","werkstueckRef":"E.3.6","stufe":2,"question":"Welche Schlussfolgerung ist am besten begründet?","options":["Ihre Beschwerden sind echt; die Einzelheiten der Entführung stammen vermutlich aus Suggestion in den Hypnosesitzungen und aus bekannten Bildern, mit denen das Gehirn Lücken füllte.","Ihre Beschwerden sind echt; die Einzelheiten der Entführung stammen vermutlich aus einer beginnenden Psychose, die Angst, Schlaflosigkeit und die grauen Wesen als Wahn hervorbrachte.","Ihre Beschwerden sind echt; die Einzelheiten der Entführung stammen vermutlich aus einem realen Ereignis, das die Hypnose im Gedächtnis freilegte und das ihre Angst erklärt.","Ihre Beschwerden sind echt; sie entstanden erst durch die in der Hypnose erinnerte Entführung, und die Einzelheiten stammen deshalb aus einem tatsächlichen Erlebnis."],"correctIndex":0,"explanation":"Hier greifen drei Dinge ineinander: echte Symptome, ein realer, furchteinflößender Zustand (Schlafparalyse: wach sein, sich nicht bewegen können, oft mit Halluzinationen) und ein Rahmen, der falsche Erinnerungen begünstigt. Die Erwartung des Therapeuten, die Hypnose und die bekannten Bilder aus Filmen und Büchern liefern dem Gehirn das Material, um die unzusammenhängenden Sinnesfetzen zu einer stimmigen Geschichte zu verbinden. Das Gehirn ruft dann nicht eine Erinnerung ab, sondern erzeugt sie. Echte Symptome beweisen nicht, dass die berichtete Ursache stimmt: Angst und Schlaflosigkeit treten auch dann auf, wenn die Erinnerung konstruiert ist. Auch Lebhaftigkeit und Emotionalität sagen wenig über Wahrheit; starke Gefühle können Erinnerungen festigen, aber ebenso anfälliger für Verzerrung machen. In der Laborstudie von Clancy u. a. (2002) bildeten Menschen mit „wiedergefundenen“ Entführungserinnerungen im Gedächtnistest häufiger falsche Erinnerungen als eine Vergleichsgruppe.","coreRule":"⚡ Dass sich eine Erinnerung echt anfühlt, beweist nicht, dass sie echt ist.","beleg":"Werkstück E.3.6 (Einstieg: Das Zeugnis des Entführten); Fn. gl-e-clancy (Clancy u. a. 2002, S. 455–461; Clancy 2005)","status":"entwurf","scenario":"Eine Frau berichtet, sie sei nachts von kleinen grauen Wesen an Bord eines Raumschiffs gebracht und dort untersucht worden. Sie leidet unter echter Angst und Schlaflosigkeit, und die Erinnerung fühlt sich für sie sehr lebhaft und real an. Details fielen ihr erst in Sitzungen bei einem Therapeuten unter Hypnose ein, der zuvor gesagt hatte, genau solche Erlebnisse seien bei ihren Beschwerden häufig. In Filmen und Büchern kennt sie das Motiv schon lange. Außerdem erwacht sie manchmal nachts bei vollem Bewusstsein und kann sich minutenlang nicht bewegen.","kurz":"Echte Symptome sprechen nicht für die Geschichte dahinter: Schlafparalyse, die Erwartung des Therapeuten, Hypnose und bekannte Filmbilder reichen, damit das Gehirn eine Erinnerung erzeugt. Der Fehler wäre, aus echter Angst auf ein echtes Ereignis zu schließen.","prueffrage":"Wann und unter welchen Umständen sind die Einzelheiten der Erinnerung zum ersten Mal aufgetaucht?","rueckmeldung":[{"option":1,"text":"Dass die Einzelheiten kaum auf ein reales Ereignis zurückgehen, ist stimmig. Eine Psychose lässt sich aber aus dem Fall nicht ableiten: Es gibt keine weiteren Anzeichen dafür, wohl aber mehrere bekannte Alltagsursachen, die die Erlebnisse ohne Erkrankung erklären."},{"option":2,"text":"Dass Angst und Schlaflosigkeit eine reale Ursache haben müssen, liegt nahe. Sie treten aber auch bei einer konstruierten Erinnerung auf, und Hypnose legt Erinnerungen eher an, als dass sie verschüttete freilegt. Auch eine sehr lebhafte, gefühlsstarke Erinnerung beweist kein Ereignis."},{"option":3,"text":"An dieser Antwort stimmt, dass die Beschwerden echt sind. Doch Angst und Schlaflosigkeit bestanden schon, bevor die Einzelheiten in den Sitzungen auftauchten. Sie können daher nicht erst aus der dort erinnerten Entführung entstanden sein."}],"familie":"erinnerung-ist-rekonstruktion","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Clancy, S. A.; McNally, R. J.; Schacter, D. L.; Lenzenweger, M. F.; Pitman, R. K. (2002): Memory distortion in people reporting abduction by aliens. Journal of Abnormal Psychology 111(3)","oeffentlich":false,"doi":"10.1037/0021-843X.111.3.455"},{"typ":"doi","kurz":"Bhalerao, V. u. a. (2024): Recent Insights Into Sleep Paralysis: Mechanisms and Management. Cureus 16(7), e65413","oeffentlich":true,"doi":"10.7759/cureus.65413"},{"typ":"doi","kurz":"Murphy, G. u. a. (2023): Lost in the mall again. Memory 31(6)","oeffentlich":true,"doi":"10.1080/09658211.2023.2198327"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"36cef2a4f0c66b19"}},{"id":"qx-e-057","clusterId":"E","werkstueckRef":"E.3.6","stufe":3,"question":"Wie ordnest du den Wert dieser Aussage ein?","options":["Sehr sichere Aussagen sind verlässlich, wenn weitere Zeugen sie stützen, nicht aber bei einem einzelnen Zeugen, selbst wenn er sich bei fairer erster Gegenüberstellung festlegte.","Sehr sichere Aussagen sind verlässlich, wenn sie bei einer fairen ersten Gegenüberstellung ohne Beeinflussung entstehen, nicht aber bei unfairer Gegenüberstellung oder späterer Beeinflussung.","Sehr sichere Aussagen sind verlässlich, wenn der Zeuge Zeit zum Abwägen hatte, nicht aber, wenn er sich schon bei der ersten Gegenüberstellung festlegt, weil schnelle Wahlen Bauchentscheidungen sind.","Sehr sichere Aussagen sind kaum verlässlicher als zögernde, auch bei fairer erster Gegenüberstellung, weil das Gedächtnis konstruiert ist und die Sicherheit nur ein Gefühl des Zeugen bleibt."],"correctIndex":1,"explanation":"Beides ist belegt: In den USA waren falsche Augenzeugen-Identifizierungen an rund zwei Dritteln der später per DNA-Test aufgehobenen Fehlurteile beteiligt (Innocence Project: 69 % von 375 Entlastungen). Das hat Reformen bei Gegenüberstellungen angestoßen. Unter sauberen Bedingungen, also bei erster, unbeeinflusster Gegenüberstellung und sofort festgehaltener Sicherheit, sind sehr sichere Identifizierungen laut Wixted und Wells (2017) aber bemerkenswert treffsicher. Unzuverlässig werden sie vor allem durch unfaire Gegenüberstellungen und spätere Beeinflussung. Der Verteidiger schließt von „das Gedächtnis ist formbar“ auf „jede Aussage ist wertlos“, doch aus einer Schwäche folgt nicht, dass sie unter allen Bedingungen gleich stark wirkt. Der Wert einer sicheren Aussage hängt von den Umständen ab, unter denen sie zustande kam.","coreRule":"⚡ Nicht nur wie sicher ein Zeuge ist, sondern unter welchen Bedingungen er sich festgelegt hat, zählt.","beleg":"Werkstück E.3.6 (Anwendung & Relevanz: In der Justiz); Fn. gl-e-dna (Innocence Project, abgerufen 06.10.2026); Fn. gl-e-wixted (Wixted & Wells 2017, S. 10, 19, 39)","status":"entwurf","scenario":"Ein Zeuge ist sich seiner Identifizierung des Täters „hundertprozentig“ sicher. Er hat sich schon bei der ersten Gegenüberstellung festgelegt, kein Ermittler hat ihn dabei beeinflusst, und seine Sicherheit wurde sofort festgehalten. Der Verteidiger entgegnet: „Das Gedächtnis ist ohnehin konstruiert, also ist jede Zeugenaussage wertlos.“","kurz":"Sehr sichere Aussagen sind unter sauberen Bedingungen, also erste, unbeeinflusste Gegenüberstellung und sofort festgehaltene Sicherheit, treffsicher. Aus „Das Gedächtnis ist formbar“ folgt nicht, dass jede Aussage unter allen Umständen gleich wertlos ist.","prueffrage":"Unter welchen Umständen kam die Identifizierung zustande, und was spricht in diesem Fall für oder gegen Beeinflussung?","rueckmeldung":[{"option":0,"text":"Weitere Zeugen können eine Aussage zusätzlich stützen, daran stimmt etwas. Entscheidend ist aber, unter welchen Bedingungen sie entstand: Eine saubere erste Gegenüberstellung macht auch einen einzelnen sehr sicheren Zeugen sehr treffsicher."},{"option":2,"text":"Gründliches Abwägen klingt nach Sorgfalt. Gerade die erste, unbeeinflusste Festlegung zählt aber zu den sauberen Bedingungen; unzuverlässig machen Aussagen eher spätere Beeinflussung und unfaire Gegenüberstellungen."},{"option":3,"text":"Dass das Gedächtnis formbar ist und falsche Identifizierungen viele Fehlurteile mitverursacht haben, ist belegt. Unter sauberen Bedingungen sind sehr sichere Identifizierungen aber bemerkenswert treffsicher, Sicherheit sagt dort also durchaus etwas aus."}],"familie":"erinnerung-ist-rekonstruktion","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Innocence Project: DNA Exonerations in the United States (1989–2020)","oeffentlich":true,"url":"https://innocenceproject.org/dna-exonerations-in-the-united-states/","abruf":"2026-10-06"},{"typ":"doi","kurz":"Wixted, J. T.; Wells, G. L. (2017): The Relationship Between Eyewitness Confidence and Identification Accuracy: A New Synthesis. Psychological Science in the Public Interest 18(1)","oeffentlich":false,"doi":"10.1177/1529100616686966"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"721c16e9e7bda18c"}},{"id":"qx-e-058","clusterId":"E","werkstueckRef":"E.3.6","stufe":4,"question":"Du siehst in einem Video einen Mund, der „GA“ formt, hörst aber den Ton „BA“ und nimmst „DA“ wahr. Schließt du die Augen, hörst du klar „BA“. Eine Freundin schließt daraus: „Dann hört mein Gehirn eben immer genau das, was der Mund zeigt.“ Was folgt aus der Beobachtung wirklich?","options":["Das Gehirn verrechnet das „GA“ im Bild und das „BA“ im Ton zu einem gemeinsamen „DA“; wie stark die Täuschung ausfällt, hängt von Person und Video ab, bei manchen bleibt sie ganz aus.","Das Gehirn ergänzt den unklaren Ton durch Erwartung und wählt das „DA“ als die Silbe, die es am ehesten erwartet; wie gut das gelingt, hängt von Person und Video ab, bei manchen gar nicht.","Bei widersprüchlichen Reizen setzt sich meist der Sehsinn durch, sodass das „GA“ aus dem Bild das „BA“ im Ton verdrängt; wie deutlich, hängt von Person und Video ab, bei manchen gar nicht.","Die Aufmerksamkeit wählt einen Kanal aus: Wer auf den Mund achtet, nimmt „GA“ wahr, wer auf den Ton achtet, „BA“; wie leicht das gelingt, hängt von Person und Video ab, bei manchen gar nicht."],"correctIndex":0,"explanation":"Die Beobachtung enthält zwei Hinweise. Erstens: Wahrgenommen wird „DA“, obwohl weder das Bild („GA“) noch der Ton („BA“) diese Silbe liefert. Wäre es immer das Bild, würdest du „GA“ wahrnehmen, wäre es immer der Ton, „BA“. Das spricht dafür, dass das Gehirn beide Sinnesdaten zu einem Kompromiss verrechnet, statt einfach eine Quelle abzulesen. Zweitens: Bei geschlossenen Augen hörst du klar „BA“. Der Ton selbst hat sich also nicht verändert; das Bild hat die Wahrnehmung mitgeformt. Dazu kommt eine Einschränkung, die der Befund selbst liefert: In einer Studie mit 165 Erwachsenen lag die Täuschungsrate je Person zwischen 0 und 100 % und je Video zwischen 17 und 58 % (Basu Mallick u. a. 2015). Ein Effekt, der so stark streut, darf nicht als Naturgesetz für alle behandelt werden. Wer ihn ohne diese Einschränkung verallgemeinert, überzieht den Befund. Dass das Gehirn Lücken mit Erwartungen füllt, stimmt allgemein, doch hier war der Ton bei geschlossenen Augen klar, und das „DA“ liegt zwischen den beiden Reizen. Setzte sich meist der Sehsinn durch, würdest du „GA“ wahrnehmen, nicht „DA“. Wählte die Aufmerksamkeit nur einen Kanal aus, käme „BA“ oder „GA“ heraus, nicht eine dritte Silbe.","coreRule":"⚡ Wahrnehmung ist keine Aufzeichnung: Das Gehirn verrechnet mehrere Sinnesdaten zu einem Ergebnis, und wie stark das wirkt, unterscheidet sich von Mensch zu Mensch.","beleg":"Werkstück E.3.6 (Die Schmiede-Übung); Fn. gl-e-mcgurk (McGurk & MacDonald 1976; Basu Mallick u. a. 2015, S. 1299–1307)","status":"entwurf","scenario":"Ein Experiment zur Wahrnehmung: Bild und Ton passen absichtlich nicht zusammen. Viele Menschen nehmen dabei eine Silbe wahr, die weder im Bild noch im Ton vorkommt. Bei geschlossenen Augen verschwindet der Effekt. Wie stark die Täuschung ausfällt, ist von Person zu Person und von Video zu Video sehr verschieden; manche erleben sie nie.","kurz":"Dass „DA“ weder im Bild noch im Ton steckt, zeigt eine Verrechnung beider Sinne, kein bloßes Ablesen des Mundes. Der Fehler der Freundin ist, einen Effekt, der von Person zu Person stark streut und manchmal ganz ausbleibt, zur Regel für alle zu machen.","prueffrage":"Was würdest du hören, wenn nur eine der beiden Quellen die Wahrnehmung bestimmte, und was hörst du tatsächlich?","rueckmeldung":[{"option":1,"text":"Dass das Gehirn Lücken oft mit Erwartungen füllt, stimmt allgemein. Hier war der Ton aber bei geschlossenen Augen klar, und das „DA“ liegt zwischen den beiden Reizen. Es entsteht aus Bild und Ton zusammen, nicht aus einer Erwartung."},{"option":2,"text":"Das Bild prägt die Wahrnehmung tatsächlich mit, sonst bliebe der Effekt bei geschlossenen Augen nicht aus. Würde es den Ton aber meist verdrängen, hörtest du „GA“. Wahrgenommen wird jedoch „DA“, eine Silbe, die keiner der beiden Reize liefert."},{"option":3,"text":"Ein Einfluss des Bildes ist tatsächlich da, denn ohne Bild hörst du klar „BA“. Würde die Aufmerksamkeit nur einen Kanal wählen, ergäbe sich aber „GA“ oder „BA“. Das wahrgenommene „DA“ bleibt damit unerklärt."}],"familie":"erinnerung-ist-rekonstruktion","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Basu Mallick, D.; Magnotti, J. F.; Beauchamp, M. S. (2015): Variability and stability in the McGurk effect. Psychonomic Bulletin & Review 22(5) (frei in PMC4580505)","oeffentlich":true,"doi":"10.3758/s13423-015-0817-4"},{"typ":"doi","kurz":"McGurk, H.; MacDonald, J. (1976): Hearing Lips and Seeing Voices. Nature 264","oeffentlich":false,"doi":"10.1038/264746a0"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"afcc7294f3bd6248"}},{"id":"qx-e-059","clusterId":"E","werkstueckRef":"E.3.7","stufe":1,"question":"Welche Antwort auf die Behauptung ist am wirksamsten?","options":["Sie sagt: „Der Redner würde an der Wachtruppe selbst verdienen. Prüft seine Behauptungen deshalb besonders kritisch, bevor ihr ihm folgt.“","Sie erklärt: „Der Feind ist keine Bande, sondern unsere Unachtsamkeit. Lasst uns gemeinsam Nachbarschaftsrunden einrichten, Schlösser nachrüsten und aufeinander achten.“","Sie fragt: „Welche Belege gibt es für Banden von außerhalb? Wer etwas behauptet, muss es belegen, und bisher hat der Redner nichts vorgelegt.“","Sie entgegnet: „Es gibt nicht nur die Wahl zwischen seiner Wachtruppe und ungeschützten Häusern. Das ist ein falsches Dilemma, und darauf sollten wir nicht hereinfallen.“"],"correctIndex":1,"explanation":"Eine reine Widerlegung zerstört die Geschichte des Redners, lässt aber eine Leere zurück: Die Angst bleibt, und das Gehirn füllt die Lücke oft wieder mit der vertrauten Erklärung. Wirksamer ist eine wahre Alternative, die die Lücke schließt, das Bedürfnis nach Sicherheit ernst nimmt und den Menschen eine aktive Rolle gibt. Genau das leistet die Antwort mit den Nachbarschaftsrunden: Sie bleibt bei den Fakten, benennt eine bessere Erklärung und zeigt, was die Gemeinschaft selbst tun kann.","coreRule":"⚡ Wer eine falsche Geschichte nur zerstört, lässt eine Lücke; fülle sie mit der wahren, die Handlungsmacht gibt.","quote":"Was ist die wahre, aber ebenso fesselnde und ermächtigende Geschichte, die ich an ihrer Stelle erzählen kann?","quoteLabel":"Denkfrage:","beleg":"Werkstück E.3.7 (Einstieg: Die Brandstifter und der Gärtner; Kernidee; Kontext & Tiefe; Härten im Feuer: Aktivierungs-Frage)","status":"entwurf","scenario":"In einer Kleinstadt häufen sich Einbrüche. Auf einer Bürgerversammlung behauptet ein Redner: „Das sind organisierte Banden von außerhalb! Nur wenn ihr mir folgt und meine Wachtruppe bezahlt, seid ihr sicher.“ Viele nicken, denn die Geschichte gibt ihrer Angst einen klaren Schuldigen. Die Polizeistatistik zeigt: Die meisten Einbrüche geschahen durch offene Fenster und unverschlossene Türen, die Täter waren überwiegend Gelegenheitstäter aus der Gegend. Eine Anwohnerin meldet sich zu Wort.","kurz":"Wer nur widerlegt, lässt die Angst ohne Antwort zurück, und die füllt sich oft wieder mit der alten Erklärung. Wirksamer ist eine wahre Alternative: Unachtsamkeit statt Banden, dazu Schritte, die die Nachbarn selbst tun können.","prueffrage":"Womit verlassen die Zuhörenden den Saal, wenn die Anwohnerin fertig ist, und was davon hilft ihnen gegen die Einbrüche?","rueckmeldung":[{"option":0,"text":"Der mögliche Interessenkonflikt ist ein berechtigter Hinweis. Er erklärt den Zuhörenden aber nicht, warum eingebrochen wird, und so bleibt ihre Angst ohne Antwort."},{"option":2,"text":"Die Beweislast liegt tatsächlich beim Redner, und die Nachfrage setzt sie richtig. Nur gibt sie der Angst nichts, woran sie sich halten könnte, und die Lücke steht weiter offen."},{"option":3,"text":"Das falsche Dilemma ist hier zutreffend benannt und ein echtes Denkwerkzeug. Es zeigt den Zuhörenden aber nur, was nicht stimmt, und keinen eigenen Weg, wie sie ihre Häuser schützen können."}],"familie":"luecke-fuellen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Lewandowsky, S.; Cook, J.; Ecker, U. K. H. u. a. (2020): The Debunking Handbook 2020","oeffentlich":true,"doi":"10.17910/b7.1182"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"a31d9c5dcda37637"}},{"id":"qx-e-060","clusterId":"E","werkstueckRef":"E.3.7","stufe":2,"question":"Dein Freund hält Kondensstreifen am Himmel für „Chemtrails“, mit denen heimlich etwas versprüht wird. Welche Reaktion hat die beste Aussicht, seine Meinung tatsächlich zu verändern?","options":["Ihm erklären, wie Kondensstreifen entstehen und warum sie je nach Luftfeuchtigkeit unterschiedlich lange am Himmel bleiben.","Ihn vor typischen Tricks von Verschwörungserzählungen warnen, damit er künftige Behauptungen dieser Art kritischer prüft.","Ihn auffordern, einen Beleg für das heimliche Versprühen zu nennen, und ihm sagen, dass die Beweislast bei ihm liegt.","Ihm sagen, dass fast alle Fachleute die Chemtrail-Behauptung ablehnen, und ihn bitten, dem Fachkonsens zu folgen."],"correctIndex":0,"explanation":"Wer nur widerspricht oder Fehler aufzählt, nimmt dem Freund eine Erklärung weg, ohne eine neue anzubieten. Gerade das Rätsel, das ihn beschäftigt (warum bleiben manche Streifen stundenlang, andere nicht?), bleibt dann offen, und das Gehirn füllt solche Lücken oft mit der alten, vertrauten Behauptung. Forschung zum Richtigstellen von Falschinformationen (Lewandowsky u. a., 2020) zeigt: Eine sachliche Alternativerklärung, die die Lücke schließt, wirkt besser als ein bloßes Dementi. Für Kondensstreifen liefert diese Alternativerklärung die Atmosphärenphysik. Dass ein Widerspruch den Irrtum sogar verstärkt, kommt zwar nur selten vor, doch auch ohne diesen Effekt bleibt das Dementi schwächer als die Erklärung. Die Warnung vor Tricks hilft, bevor jemand einer Behauptung begegnet, ändert aber kaum, was er schon glaubt. Die Beweislast ist ein gutes Prinzip, beantwortet aber nicht seine Frage nach den unterschiedlich langen Streifen. Der Verweis auf den Fachkonsens nennt ein Ergebnis, ohne zu erklären, wie es zustande kommt.","coreRule":"⚡ Wer eine Behauptung widerlegen will, braucht mehr als ein Nein: Eine bessere, nachprüfbare Erklärung füllt die Lücke, die sonst die alte Behauptung wieder füllt.","beleg":"Werkstück E.3.7 (Anwendung & Relevanz: Verschwörungsmythen; Red Flags; Kontext & Tiefe, Fn. gl-e-luecke: Lewandowsky u. a. 2020, Debunking Handbook; Backfire-Effekt selten)","status":"entwurf","scenario":"Du stehst mit einem Freund draußen, am Himmel ziehen sich weiße Streifen. Er sagt: „Siehst du? Die sprühen da was aus. Warum bleiben manche Streifen stundenlang und andere verschwinden sofort?“","kurz":"Er hat eine echte Frage, und die Antwort darauf schließt die Lücke: Die Physik erklärt, warum Streifen je nach Luftfeuchtigkeit unterschiedlich lange bleiben. Ein bloßes Dementi nimmt ihm die Erklärung weg und bietet keine neue an.","prueffrage":"Was genau hat dein Freund gefragt, als ihr die Streifen am Himmel gesehen habt?","rueckmeldung":[{"option":1,"text":"Eine Vorwarnung kann nützlich sein, bevor jemand einer Behauptung begegnet. Dein Freund glaubt sie aber schon, und die Warnung ändert daran kaum etwas. Seine Frage nach den unterschiedlich langen Streifen bleibt dabei unbeantwortet."},{"option":2,"text":"Dass die Beweislast bei dem liegt, der etwas behauptet, ist ein gutes Prinzip. Es beantwortet aber nicht, warum manche Streifen bleiben und andere verschwinden. Ohne Erklärung bleibt die Lücke, und die füllt er leicht mit seiner alten Deutung."},{"option":3,"text":"Der Fachkonsens ist tatsächlich eindeutig und ein wichtiger Hinweis. Er nennt aber nur ein Ergebnis und nicht, wie es zustande kommt. Auf die Frage deines Freundes gibt das keine Antwort, und die Bitte, einfach zu folgen, ersetzt keine Erklärung."}],"familie":"luecke-fuellen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Lewandowsky, S.; Cook, J.; Ecker, U. K. H. u. a. (2020): The Debunking Handbook 2020","oeffentlich":true,"doi":"10.17910/b7.1182"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"1e642524ad303199"}},{"id":"qx-e-061","clusterId":"E","werkstueckRef":"E.3.7","stufe":3,"question":"Was folgt aus diesem Befund für die Planung einer Richtigstellung?","options":["Die Erzählform bringt für sich keinen Vorteil; entscheidend ist, dass die Richtigstellung die Lücke im Weltbild mit einer Erklärung füllt, die das Gerücht ersetzt.","Die Erzählform bringt keinen Vorteil, der Mitarbeiter lag mit seiner Annahme also falsch; die Behörde sollte deshalb bei einem nüchternen, sachlichen Text bleiben.","Die Erzählform bringt keinen Vorteil; es genügt daher, das Gerücht deutlich als falsch zu kennzeichnen und auf die gesicherte Studienlage zum Impfstoff zu verweisen.","Die Erzählform bringt keinen Vorteil, beide Fassungen wirkten gleich; entscheidend ist also, dass die Richtigstellung kurz und für alle leicht verständlich formuliert ist."],"correctIndex":0,"explanation":"Aus dem Befund folgt: Wenn eine erzählte und eine sachliche Richtigstellung gleich viel erklären, wirken sie ähnlich gut. Der Mitarbeiter schließt also von „Geschichte“ auf „wirksamer“, ohne dass das belegt ist. Wirksam ist eine sachliche Alternativerklärung, die die entstandene Lücke füllt; ohne sie greift das Gehirn oft wieder zur vertrauten Falschinformation. Die Geschichtenform kann Aufmerksamkeit und Merkbarkeit unterstützen, ersetzt aber nie die erklärende Substanz. Dass Aufmerksamkeit helfen kann, klingt einleuchtend, doch der Befund gilt nur bei gleich viel Erklärung; wer sie kürzt, verlässt die Bedingung des Vergleichs, und die Lücke bliebe offen. Vorsicht gegenüber einzelnen Studien ist grundsätzlich richtig, doch drei vorregistrierte Experimente mit über 2.000 Personen sind eine tragfähige Planungsgrundlage, und Abwarten lässt das Gerücht weiterwirken. Dass die Glaubwürdigkeit des Absenders eine Rolle spielt, ist plausibel, doch der Befund verglich nur zwei Darstellungsformen und sagt über die Bedeutung des Absenders nichts.","coreRule":"⚡ Frage bei einer Richtigstellung zuerst, welche Erklärung die Lücke füllt, nicht, wie spannend sie erzählt ist.","beleg":"Werkstück E.3.7 (Kontext & Tiefe); Fn. gl-e-erzaehlform (Ecker, Butler, Hamby 2020, Abstract); Fn. gl-e-luecke (Lewandowsky u. a. 2020, PDF-S. 9 und 12)","status":"entwurf","scenario":"Eine Gesundheitsbehörde will ein hartnäckiges Gerücht über einen Impfstoff richtigstellen. Ein Mitarbeiter schlägt vor: „Wir packen die Richtigstellung in eine spannende Geschichte, dann wirkt sie von selbst besser als ein nüchterner Text.“ In drei vorregistrierten Experimenten mit zusammen 2.279 Teilnehmenden zeigte sich: Erzählte Richtigstellungen wirkten nicht besser als sachlich formulierte, sofern beide gleich viel erklärten.","kurz":"Wenn Geschichte und Sachtext gleich viel erklären, wirken sie ähnlich gut. Der Fehler liegt im Schluss von „spannend“ auf „wirksamer“: Entscheidend ist eine Erklärung, die die Lücke füllt, die das Gerücht hinterlässt.","prueffrage":"Was wurde in den drei Experimenten miteinander verglichen, und welcher Unterschied zeigte sich dabei?","rueckmeldung":[{"option":1,"text":"Dass die Geschichte nichts bringt, stimmt. Daraus folgt aber nicht, dass der nüchterne Text besser wäre: Beide wirkten gleich, solange sie gleich viel erklärten. Wichtig ist, was erklärt wird, nicht welche Form gewählt wird."},{"option":2,"text":"Klare Kennzeichnung als falsch und ein Verweis auf Studien wirken gründlich. Das Gerücht lässt aber eine Lücke zurück, und ohne Ersatzerklärung greift man oft wieder zur vertrauten Falschinformation. Zudem gilt der Befund nur bei gleich viel Erklärung."},{"option":3,"text":"Verständlichkeit hilft grundsätzlich. Der Befund sagt darüber aber nichts, er verglich nur zwei Darstellungsformen bei gleich viel Erklärung. Kürze kann sogar Erklärung kosten, und die füllt die Lücke, die das Gerücht hinterlässt."}],"familie":"luecke-fuellen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Ecker, U. K. H.; Butler, L. H.; Hamby, A. (2020): You don't have to tell a story! Cognitive Research: Principles and Implications 5, Art. 64","oeffentlich":true,"doi":"10.1186/s41235-020-00266-x"},{"typ":"doi","kurz":"Lewandowsky, S.; Cook, J.; Ecker, U. K. H. u. a. (2020): The Debunking Handbook 2020","oeffentlich":true,"doi":"10.17910/b7.1182"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"b172ef8195f37337"}},{"id":"qx-e-062","clusterId":"E","werkstueckRef":"E.3.7","stufe":4,"question":"Welchen Vorschlag solltest du umsetzen?","options":["Ein übersichtlicher Faktencheck auf der Infoseite, der das Gerücht oben zitiert und es darunter Punkt für Punkt mit den aktuellen Messwerten aus dem Labor widerlegt.","Eine wahre Geschichte über die Laborantin, die täglich Proben zieht, mit klarer Erklärung der Messung und einer Einladung, die Werte selbst nachzulesen.","Eine kurze Stellungnahme der Werksleitung, die das Gerücht entschieden zurückweist und der Stadt versichert, dass das Leitungswasser unbedenklich ist.","Ein kurzes, persönliches Video, in dem eine Ärztin aus der Stadt ein Glas Leitungswasser trinkt und sagt, dass sie dem Wasserwerk und seinen Kontrollen vertraut."],"correctIndex":1,"explanation":"Eine Gegenerzählung soll Menschen eine bessere Erklärung anbieten, die die entstandene Lücke füllt, und diese Erklärung muss auf der Wahrheit beruhen; sie bleibt der Wahrheit und der intellektuellen Redlichkeit verpflichtet. Die wahre Geschichte über die Laborantin erfüllt beides: Sie fesselt, erklärt die Messung und gibt den Lesenden eine aktive Rolle, und sie stimmt mit den Fakten überein. Wer eine falsche, aber emotional ansprechende Geschichte konstruiert, um eine andere falsche Erzählung zu bekämpfen, überschreitet den Kipppunkt von der Nützlichkeit zur Gefahr: Er benutzt genau die Methode, die er bekämpfen wollte. Ein guter Zweck macht ein unredliches Mittel nicht gültig, denn ob eine Aussage stimmt, hängt nicht davon ab, wofür man sie einsetzt.","coreRule":"⚡ Gegen Lügen hilft keine bessere Lüge – nur eine wahre Geschichte, die auch fesselt.","beleg":"Werkstück E.3.7 (Der Kipppunkt; Kontext & Tiefe: Komponenten)","status":"entwurf","scenario":"In deiner Stadt verbreitet sich das Gerücht, das neue Wasserwerk vergifte das Leitungswasser. Du betreust die Infoseite des Wasserwerks. Sachliche Richtigstellungen mit Messtabellen werden dort kaum gelesen, das Gerücht dagegen wird massenhaft geteilt. Im Team liegen vier Vorschläge auf dem Tisch.","kurz":"Ein Gerücht bleibt, solange keine bessere Erklärung die Lücke füllt, und die muss wahr sein. Die Geschichte der Laborantin tut beides; Widerlegungen und Beteuerungen erklären nichts und erreichen kaum jemanden.","prueffrage":"Was bleibt bei den Lesenden hängen, wenn sie nur die Tabelle sehen, und was nach der Geschichte?","rueckmeldung":[{"option":0,"text":"Ein Faktencheck mit Messwerten ist korrekt und redlich. Er hat aber dasselbe Problem wie die bisherigen Tabellen: Er wird kaum gelesen und erzählt nichts, was die Lücke füllt. Das zitierte Gerücht steht dabei sogar ganz oben."},{"option":2,"text":"Eine entschiedene Zurückweisung wirkt klar und gibt Sicherheit. Sie ist aber nur eine Behauptung der Betroffenen selbst, ohne Beleg und ohne Erklärung, und macht aus der Lücke keine bessere Geschichte."},{"option":3,"text":"Die persönliche Form und das Gesicht aus der Stadt sind klug gewählt. Ein getrunkenes Glas und eine Vertrauensbekundung beweisen aber wenig und erklären nichts. Die Wirkung hängt am Ansehen der Ärztin, nicht an etwas, das man selbst nachprüfen könnte."}],"familie":"luecke-fuellen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Lewandowsky, S.; Cook, J.; Ecker, U. K. H. u. a. (2020): The Debunking Handbook 2020","oeffentlich":true,"doi":"10.17910/b7.1182"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"8bd15b523400763f"}},{"id":"qx-e-063","clusterId":"E","werkstueckRef":"E.4.1","stufe":1,"question":"Was ist an dieser Schlussfolgerung fehlerhaft?","options":["Sie schließt aus der Nutzung einer Mechanik durch eine Gruppe, dass die Mechanik selbst den Hass erzeugt; dieselbe Mechanik kann aber auch harmlose Inhalte tragen.","Sie verallgemeinert vorschnell von einer einzigen Gruppe auf alle, die solche Mechaniken nutzen; um den Schluss zu stützen, bräuchte es Beispiele aus vielen Gruppen.","Sie verwechselt Zusammenhang und Ursache; dass Punkte und Hass gemeinsam auftreten, genügt nicht, man müsste erst zeigen, dass die Punkte vor dem Hass da waren.","Sie ist im Kern berechtigt, nur zu scharf formuliert; Punkte und Ränge machen Inhalte fesselnder und verstärken deshalb auch den Hass, wo er schon vorhanden ist."],"correctIndex":0,"explanation":"Eine Mechanik ist ein Werkzeug, kein Inhalt. Punkte, Ränge und Gemeinschaft motivieren Menschen, egal wofür: In Lern- und Fitness-Apps fördern sie nützliche Gewohnheiten, in einer extremistischen Gruppe binden sie Mitglieder an eine hasserfüllte Ideologie. Der Fehler liegt nicht in der Mechanik, sondern darin, wofür sie eingesetzt wird. Wer von „wird dort benutzt“ auf „ist die Ursache“ schließt, verwechselt Mittel und Zweck. Richtig wäre die Frage, ob die Belohnung eine Gruppe bindet, die Menschen schrittweise an immer radikalere Inhalte gewöhnt, ohne dass sie es merken.","coreRule":"⚡ Eine Mechanik, die Menschen bindet, ist noch kein Beleg für schädliche Absichten: Entscheidend ist, wofür sie eingesetzt wird und wohin sie führt.","beleg":"Werkstück E.4.1 (Einstieg; Kernidee; Das Adaptive Talent)","status":"entwurf","scenario":"In einer Diskussion über Online-Radikalisierung sagt jemand: „Die Gruppe benutzt Punkte, Ränge und Belohnungen, um ihre Mitglieder zu binden. Also sind diese Spielmechaniken selbst der Grund für Hass und Gewalt. Wer solche Mechaniken einsetzt, verbreitet Extremismus.“ Dieselben Mechaniken stecken auch in Lern-Apps, Fitness-Apps und Videospielen.","kurz":"Punkte und Ränge sind Werkzeuge: In Lern- und Fitness-Apps stärken sie nützliche Gewohnheiten, in einer extremistischen Gruppe binden sie an Hass. Der Fehler liegt darin, aus „wird dort benutzt“ auf „ist die Ursache“ zu schließen und Mittel und Zweck zu verwechseln.","prueffrage":"Wo kommen Punkte, Ränge und Belohnungen sonst noch vor, und was bewirken sie dort?","rueckmeldung":[{"option":1,"text":"Dass hier von einer Gruppe auf viele geschlossen wird, stimmt. Aber auch mehr Beispiele würden den Schluss nicht retten: Lern- und Fitness-Apps zeigen schon, dass dieselben Mechaniken harmlos eingesetzt werden. Das Problem liegt tiefer als in der Stichprobe."},{"option":2,"text":"Ein bloßer Zusammenhang wird hier gar nicht beschrieben, die Aussage behauptet unmittelbar eine Ursache. Und selbst wenn die Punkte zuerst da waren, bliebe der Schluss unsauber, weil nicht die Reihenfolge, sondern der Einsatzzweck über den Inhalt entscheidet."},{"option":3,"text":"Dass Punkte und Ränge binden und motivieren, trifft zu. Daraus folgt aber nicht, dass sie Hass erzeugen: Sie tragen jeden Inhalt, ob nützlich oder schädlich. Der Schluss ist deshalb nicht nur zu scharf formuliert, sondern verwechselt Mittel und Zweck."}],"familie":"anreize-durchschauen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Schlegel, L. (2020): Jumanji Extremism? How games and gamification could facilitate radicalization processes. Journal for Deradicalization 23","oeffentlich":true,"url":"https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/359","seite":"PDF-S. 5, 13, 15","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Nocun, K.; Lamberty, P. (2020): Fake Facts. Wie Verschwörungstheorien unser Denken bestimmen. Quadriga","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"9b20818fe8423b1c"}},{"id":"qx-e-064","clusterId":"E","werkstueckRef":"E.4.1","stufe":2,"question":"Was ist die sparsamste Erklärung dafür, dass der Nutzer beim nächsten Mal noch schärfer postet?","scenario":"In einem Forum bekommt ein Nutzer für einen besonders zugespitzten, „witzigen“ Beitrag hunderte Likes und neue Follower. Davor hatte er eher sachlich geschrieben und kaum Resonanz bekommen. Beim nächsten Mal wird er noch schärfer.","options":["Die Schärfe wirkt als Gewöhnung: Nach dem ersten zugespitzten Beitrag ist der Ton gesetzt, also bleibt er dabei und schreibt beim nächsten Mal noch etwas schärfer.","Die Zustimmung wirkt wie Punkte: Auf den zugespitzten Beitrag kamen Likes und Follower, auf die sachlichen kaum Resonanz, also wiederholt er, was sich lohnt.","Die Likes wirken als Beweis: Hunderte Zustimmungen zeigen ihm, dass seine zugespitzte Haltung in der Sache stimmt, also vertritt er sie nun noch deutlicher.","Die Follower wirken als Publikum: Vor mehr Lesern will er nun erst recht auffallen, also schreibt er für die größere Bühne noch pointierter und bissiger als zuvor."],"correctIndex":1,"explanation":"Likes und neue Follower sind sofortiges, sichtbares Feedback. Verhalten, das belohnt wird, wird wiederholt und oft gesteigert. Das erklärt den Verlauf allein aus dem, was bekannt ist: sachlich gab es wenig Resonanz, zugespitzt gab es viel. Das heißt nicht, dass der Nutzer nichts meint; es heißt, dass sein Verhalten auch ohne Überzeugungswandel erklärbar ist.","coreRule":"⚡ Frag bei einer Community: Wofür gibt es hier Punkte – und wofür gibt es sie nicht? Wer die Belohnung kennt, versteht oft das Verhalten, ohne eine Gesinnung unterstellen zu müssen.","beleg":"Werkstück E.4.1 (Kontext & Tiefe (Die Analyse), Aufzählpunkt „Punkte & Sozialer Status“)","status":"entwurf","kurz":"Sachlich gab es kaum Resonanz, zugespitzt gab es Likes und Follower. Belohntes Verhalten wird oft wiederholt und gesteigert, das erklärt den Verlauf allein. Man muss keinen Überzeugungswandel oder neue Motive dazuerfinden.","prueffrage":"Was ist über den Nutzer tatsächlich bekannt, und was wird über ihn nur vermutet?","rueckmeldung":[{"option":0,"text":"Dass der erste scharfe Beitrag den Ton gesetzt hat, ist denkbar. Es erklärt aber nicht, warum er gerade danach noch schärfer wird, statt gleich zu bleiben. Das tut erst die Reaktion der anderen."},{"option":2,"text":"Hunderte Likes für einen „witzigen“ Beitrag zeigen vor allem, dass er gut ankam, nicht dass die Haltung stimmt. Und es braucht keinen Überzeugungswandel: Das Verhalten ist auch ohne ihn erklärbar."},{"option":3,"text":"Die Follower spielen durchaus eine Rolle, aber als Teil der Belohnung selbst, nicht als eigener Antrieb. Der Wunsch nach der größeren Bühne ist eine Zusatzannahme, die im Szenario nirgends steht und die man nicht braucht."}],"familie":"anreize-durchschauen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Brady, W. J.; McLoughlin, K.; Doan, T. N.; Crockett, M. J. (2021): How social learning amplifies moral outrage expression in online social networks. Science Advances 7(33)","oeffentlich":true,"doi":"10.1126/sciadv.abe5641","abruf":"2026-10-12"},{"typ":"doi","kurz":"Lindström, B. u. a. (2021): A computational reward learning account of social media engagement. Nature Communications 12, 1311","oeffentlich":true,"doi":"10.1038/s41467-020-19607-x","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"e94a11cb60d45803"}},{"id":"qx-e-065","clusterId":"E","werkstueckRef":"E.4.1","stufe":3,"question":"Wie lässt sich am besten beurteilen, ob eine Online-Gemeinschaft mit Punkten und Rängen schädlich ist?","options":["Wofür das Forum Punkte vergibt und ob das Streben nach Rang in Belästigung, Hass oder Gewalt außerhalb des Forums mündet, denn daran zeigt sich der Schaden.","Wer das Forum betreibt und womit es Geld verdient, denn das Geschäftsmodell zeigt, ob die Punkte und Ränge vor allem dazu dienen, Mitglieder länger zu binden.","Wie viel Zeit deine Freundin im Forum verbringt und wie schnell sie Ränge aufsteigt, denn sehr lange Nutzung und rascher Aufstieg deuten auf ungesunde Bindung hin.","Wie zufrieden deine Freundin und die anderen Mitglieder mit dem Forum sind, denn wer sich dort wohlfühlt und Punkte sammelt, ist in der Regel nicht gefährdet."],"correctIndex":0,"explanation":"Punkte, Ränge und Gemeinschaft sind an sich neutral: Dieselben Mechanismen motivieren in Lern- und Fitness-Apps und sind dort nützlich. Entscheidend ist, wofür sie eingesetzt werden. Warnzeichen sind, wenn Ansehen von Extremität oder Provokation abhängt, wenn es einen Pfad von harmloseren zu immer radikaleren Inhalten gibt oder wenn Kritik als Angriff von „Spielverderbern“ abgetan wird. Kritisch wird es, wenn der „Highscore“ in der Gruppe zu Belästigung, Hass oder Gewalt im echten Leben führt.","coreRule":"⚡ Nicht die Spielmechanik ist das Problem, sondern wofür sie eingesetzt wird.","beleg":"Werkstück E.4.1 (Der Kipppunkt; Das Adaptive Talent; Red Flags)","status":"entwurf","scenario":"Eine Freundin erzählt dir von einem Online-Forum, in dem man für gute Beiträge Punkte sammelt und in Ränge aufsteigt. Sie ist begeistert. Du fragst dich, ob das harmlos ist oder ob du sie warnen solltest.","quote":"","quoteLabel":"","kurz":"Punkte und Ränge sind an sich neutral; entscheidend ist, was sie belohnen und wohin der Ehrgeiz führt. Der naheliegende Fehler ist, nach Merkmalen wie Betreiber, Zeit oder Zufriedenheit zu urteilen, die auch bei harmlosen Gemeinschaften vorkommen.","prueffrage":"Was postet deine Freundin dort konkret, und wie reagieren die anderen darauf?","rueckmeldung":[{"option":1,"text":"Wer ein Forum betreibt und womit es verdient, ist eine gute Frage, um Interessen zu klären. Sie sagt aber nichts darüber, was dort belohnt wird, und genau daran zeigt sich ein Schaden."},{"option":2,"text":"Viel Zeit und rascher Aufstieg können auf ungesunde Bindung hindeuten. Sie kommen aber ebenso in harmlosen Gemeinschaften vor und verraten nicht, wofür die Punkte stehen."},{"option":3,"text":"Zufriedenheit unterscheidet hier kaum etwas: Deine Freundin ist schon begeistert, und das sind Mitglieder schädlicher Gemeinschaften ebenso wie harmloser. Wohlfühlen schützt nicht davor, dass dort etwas Problematisches belohnt wird."}],"familie":"anreize-durchschauen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Schlegel, L. (2020): Jumanji Extremism? How games and gamification could facilitate radicalization processes. Journal for Deradicalization 23","oeffentlich":true,"url":"https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/359","seite":"PDF-S. 5, 15","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Nocun, K.; Lamberty, P. (2020): Fake Facts. Wie Verschwörungstheorien unser Denken bestimmen. Quadriga","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"46da5b1f49f18a18"}},{"id":"qx-e-066","clusterId":"E","werkstueckRef":"E.4.1","stufe":4,"question":"Du liest die Schlagzeile: „Spiel macht Menschen immun gegen Fake News!“ Dahinter steckt eine Studie mit 196 Teilnehmenden einer Online-Plattform. Eine Gruppe spielte eine Viertelstunde lang ein Spiel, in dem man selbst Falschmeldungen verbreitet und dabei Manipulationstechniken kennenlernt, die Vergleichsgruppe spielte Tetris. Direkt danach bewerteten beide Gruppen erfundene Beiträge. Die Spielgruppe erkannte die Manipulationstechniken besser. Was darfst du aus diesem Ergebnis folgern?","options":["Gemessen wurde nur direkt nach der Viertelstunde und an erfundenen Beiträgen; ob der Schutz hält und sich im Verhalten im Netz zeigt, bleibt deshalb offen.","Die Spielgruppe erkannte Techniken direkt nach dem Spiel besser; weil man selbst angewendete Techniken lange behält, hält der Schutz auch Wochen später noch an.","Die Spielgruppe erkannte Manipulationstechniken besser; wer sie erkennt, teilt im Alltag auch weniger Falschmeldungen, also senkt das Spiel deren Verbreitung im Netz.","Die 196 Teilnehmenden kamen von einer Online-Plattform, die Menschen aller Gruppen erreicht; die Stichprobe bildet alle Internetnutzenden ab, der Effekt gilt also für alle."],"correctIndex":0,"explanation":"Die Spielgruppe schnitt direkt nach dem Spiel besser ab als die Tetris-Gruppe. Mehr trägt die Messung aber nicht: Es wurde nur unmittelbar nach dem Spiel gemessen, und zwar an erfundenen Beiträgen. Ob das Erkennen nach Wochen noch funktioniert und ob Menschen im echten Netz anders handeln, wurde nicht geprüft. Zudem stammen die 196 Personen aus einer Online-Plattform und sind nach Angabe der Autoren wohl nicht repräsentativ. Der Vergleich mit der Tetris-Gruppe spricht zugleich gegen einen reinen Zufallsbefund. Dass Gelerntes lange haftet, ist möglich, wurde hier aber nicht nachgemessen. Dass Erkennen und Handeln zusammenhängen, ist eine Annahme, die erst eine Verhaltensmessung belegen könnte. Und eine Online-Plattform erreicht zwar viele Menschen, ihre Nutzenden sind aber nicht automatisch ein Abbild aller.","coreRule":"⚡ Prüfe bei jeder Studienschlagzeile, was genau gemessen wurde und wann: Ein Effekt direkt nach der Intervention sagt nichts über Dauer oder Verhalten im Alltag.","beleg":"Werkstück E.4.1 (Verbindungen: Kognitive Immunisierung); Fn. gl-e-badnews (Basol, Roozenbeek, van der Linden 2020, S. 1–3 und 6)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Gemessen wurde nur direkt nach dem Spiel und an erfundenen Beiträgen. Ob das Erkennen anhält und sich im echten Netz im Verhalten zeigt, bleibt offen; aus „besser erkannt“ wird schnell „dauerhaft geschützt“.","prueffrage":"Wie sah die Aufgabe aus, an der der Erfolg des Spiels gemessen wurde, und wer hat sie bearbeitet?","rueckmeldung":[{"option":1,"text":"Dass Selbstangewendetes lange haftet, ist denkbar. Hier wurde aber nur direkt nach dem Spiel gemessen, nach Wochen schaute niemand nach. Ob der Schutz so lange anhält, zeigt die Studie also nicht."},{"option":2,"text":"Wer Techniken erkennt, teilt vielleicht wirklich weniger. Gemessen wurde aber nur das Erkennen an erfundenen Beiträgen, nicht das Verhalten im Alltag. Dass beides zusammenhängt, ist eine Annahme, die erst eine Verhaltensmessung belegen könnte."},{"option":3,"text":"Eine Online-Plattform erreicht viele Menschen, ihre Nutzenden sind aber nicht automatisch ein Abbild aller Internetnutzenden. Nach Angabe der Autoren ist die Stichprobe wohl nicht repräsentativ, daher lässt sich der Effekt nicht auf alle übertragen."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Basol, M.; Roozenbeek, J.; van der Linden, S. (2020): Good News about Bad News: Gamified Inoculation Boosts Confidence and Cognitive Immunity Against Fake News. Journal of Cognition 3(1)","oeffentlich":true,"doi":"10.5334/joc.91"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"e85fc18a0f58ba90"}},{"id":"qx-e-067","clusterId":"E","werkstueckRef":"E.4.2","stufe":1,"question":"Welche Frage bringt am schnellsten ans Licht, womit sich dieses Angebot finanziert?","options":["Wie viele Nutzer hat die App schon, und wie schnell wächst sie im Vergleich zu anderen Gratis-Apps?","Wer bezahlt dem Unternehmen Geld, damit es Angestellte und Rechenzentren unterhält, und was bekommt er dafür?","Wofür gibt das Unternehmen sein Geld aus, und welche Lieferanten bekommen es für Rechenzentren und Technik?","Wie viele Nutzer würden später für Zusatzfunktionen oder ein Abo zahlen, und was bekämen sie dafür?"],"correctIndex":1,"explanation":"Ein Unternehmen mit hohen Kosten muss Einnahmen haben. Wenn die Nutzer nichts zahlen, muss das Geld von jemand anderem kommen. Beim bekanntesten Geschäftsmodell solcher Gratisdienste sind das Werbetreibende, die für die Aufmerksamkeit der Nutzer bezahlen. Für die Plattform sind dann nicht die Nutzer die Kunden, sondern ihre Aufmerksamkeit und ihr vorhersagbares Verhalten die Ware. Die Frage nach Zahlungsströmen deckt das Geschäftsmodell auf, und aus dem Geschäftsmodell folgt, worauf der Dienst ausgelegt ist: Das Design zielt auf maximale Verweildauer, denn gebundene Aufmerksamkeit wird an Werbetreibende verkauft. Nutzerzahlen und Wachstum sagen etwas über den Erfolg, nicht darüber, wer das Geld liefert. Die Frage, wofür das Unternehmen Geld ausgibt, zeigt den Geldbedarf, den du schon kennst, aber nicht, woher das Geld kommt. Zusatzfunktionen bringen heute kein Geld, weil die App keine Bezahlfunktionen hat; was später kommen könnte, erklärt das heutige Angebot nicht.","coreRule":"⚡ Frag bei jedem Gratisdienst: Wer bezahlt hier – und was bekommt er dafür?","beleg":"Werkstück E.4.2 (Kernidee; Kontext & Tiefe: Das Geschäftsmodell; Du bist nicht der Kunde)","status":"entwurf","scenario":"Eine neue Video-App ist komplett kostenlos, ohne Abo und ohne Bezahlfunktionen. Trotzdem beschäftigt das Unternehmen Hunderte Angestellte und betreibt riesige Rechenzentren. Eine Freundin sagt: „Ist doch super, das kostet mich gar nichts.“ Du willst herausfinden, wie das Geschäftsmodell funktioniert.","kurz":"Wer Kosten trägt, muss Einnahmen haben, und von den Nutzern kommen sie hier nicht. Wer also zahlt und was er dafür bekommt, deckt das Modell auf; naheliegend ist, bei Nutzerzahlen oder Ausgaben zu suchen.","prueffrage":"Angenommen, die App hätte morgen doppelt so viele Nutzer: Hätte das Unternehmen dann mehr Geld, und von wem?","rueckmeldung":[{"option":0,"text":"Nutzerzahlen und Wachstum zeigen, wie erfolgreich die App ist. Sie sagen aber nicht, wer das Geld liefert. Auch eine sehr beliebte App braucht irgendwo Einnahmen, und danach fragt dieser Vergleich nicht."},{"option":2,"text":"Die Ausgaben zeigen, wie hoch der Geldbedarf ist, und den kennst du durch die Angestellten und Rechenzentren schon. Offen bleibt, woher das Geld kommt, und genau das fragt diese Antwort nicht."},{"option":3,"text":"Ein Blick auf spätere Abos klingt nach einem Geschäftsmodell. Die App hat aber heute keine Bezahlfunktionen, also kommt von dort derzeit kein Geld. Was später kommen könnte, erklärt das heutige Angebot nicht."}],"familie":"anreize-durchschauen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Montag, C.; Lachmann, B.; Herrlich, M.; Zweig, K. (2019): Addictive Features of Social Media/Messenger Platforms and Freemium Games against the Background of Psychological and Economic Theories. IJERPH 16(14), 2612","oeffentlich":true,"doi":"10.3390/ijerph16142612","abruf":"2026-10-12"},{"typ":"url","kurz":"Franck, G. (1999): The Economy of Attention. Telepolis, 7.12.1999","oeffentlich":true,"url":"https://archiv.telepolis.de/features/The-Economy-of-Attention-3444929.html"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"f44e65fee23a4d0f"}},{"id":"qx-e-068","clusterId":"E","werkstueckRef":"E.4.2","stufe":2,"question":"Welche Gestaltung ist bei diesem Erfolgsmaßstab am wahrscheinlichsten, und warum?","scenario":"Eine kostenlose App finanziert sich ausschließlich über Werbung. Ihr Produktteam erhält eine einzige Kennzahl als Erfolgsmaßstab: die durchschnittliche Zeit, die Nutzer pro Tag in der App verbringen. Nun muss das Team entscheiden, wie der Feed gestaltet werden soll.","options":["Ein Feed, der immer weiterlädt, mit Aktualisieren per Wischgeste und roten Hinweispunkten, weil jede Unterbrechung des Scrollens Nutzungszeit kostet.","Ein Feed mit festem Ende nach 20 Beiträgen und einem Hinweis, dass alles Neue gesehen wurde, weil zufriedene Nutzer später wiederkommen.","Ein Feed, der nur auf ausdrückliche Suche Beiträge anzeigt, weil Nutzer dann genau das finden, was sie brauchen.","Ein Feed ohne Benachrichtigungen und ohne automatische Aktualisierung, weil weniger Reize den Nutzern mehr Ruhe verschaffen."],"correctIndex":0,"explanation":"Die App verdient ihr Geld mit Werbung: Ihre Dienste wirken kostenlos, doch die gesammelte Aufmerksamkeit der Nutzer ist die eigentliche Ware, die an Werbetreibende verkauft wird. Deshalb ist jede Design-Entscheidung darauf ausgerichtet, den Nutzer so lange wie möglich auf der Plattform zu halten. Wird Nutzungszeit zum einzigen Erfolgsmaßstab, passen genau die Mechanismen dazu, die das Aufhören erschweren: Feeds ohne Ende, Aktualisieren per Wischgeste und rote Hinweispunkte, die zur Rückkehr locken. Die anderen Gestaltungen mögen für Nutzer angenehmer sein, würden aber genau diese Kennzahl senken. Gratis bedeutet hier nicht, dass es nichts kostet: Bezahlt wird mit Aufmerksamkeit, und das Ziel der App ist nicht automatisch dein eigenes Ziel.","coreRule":"⚡ Wenn ein Dienst gratis ist, frag, was er misst: Die Kennzahl verrät, wofür das Design gebaut ist.","beleg":"Werkstück E.4.2 (Kontext & Tiefe: Das Geschäftsmodell, Das Ziel ist die Maximierung der Verweildauer; Red Flags). Fachbegriffe Infinite Scroll und Pull-to-Refresh bewusst durch Beschreibungen ersetzt.","status":"entwurf","kurz":"Wenn nur die Nutzungszeit zählt, passt alles, was das Aufhören erschwert: endloses Scrollen, Wischen zum Aktualisieren, rote Hinweispunkte. Angenehmere Feeds mit Ende oder mehr Ruhe senken diese Kennzahl, und von ihr lebt eine App, die Aufmerksamkeit verkauft.","prueffrage":"Wie würde sich die durchschnittliche Zeit pro Tag verändern, wenn der Feed nach einer festen Zahl von Beiträgen endet?","rueckmeldung":[{"option":1,"text":"Zufriedene Nutzer, die später wiederkommen, sind ein gutes Ziel. Gemessen wird hier aber die Zeit pro Tag, und ein Feed mit Ende nach 20 Beiträgen verkürzt sie, weil die Nutzung dann von selbst aufhört."},{"option":2,"text":"Wer gezielt sucht, findet schnell, was er braucht, und das ist für Nutzer angenehm. Danach ist die Sitzung aber meist zu Ende, die Nutzungszeit bleibt also kurz, und genau sie gilt als Erfolgsmaßstab."},{"option":3,"text":"Weniger Reize können den Nutzern mehr Ruhe verschaffen. Doch ohne Hinweise und automatische Aktualisierung fehlt, was zur Rückkehr lockt und das Aufhören erschwert, und die Nutzungszeit sinkt."}],"familie":"anreize-durchschauen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Montag, C.; Lachmann, B.; Herrlich, M.; Zweig, K. (2019): Addictive Features of Social Media/Messenger Platforms and Freemium Games against the Background of Psychological and Economic Theories. IJERPH 16(14), 2612","oeffentlich":true,"doi":"10.3390/ijerph16142612","abruf":"2026-10-12"},{"typ":"url","kurz":"Franck, G. (1999): The Economy of Attention. Telepolis, 7.12.1999","oeffentlich":true,"url":"https://archiv.telepolis.de/features/The-Economy-of-Attention-3444929.html"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"00e7b23a7a0009e5"}},{"id":"qx-e-069","clusterId":"E","werkstueckRef":"E.4.2","stufe":3,"question":"Eine Nutzerin wundert sich, warum sie kaum aufhören kann zu scrollen: Mal erscheint ein lustiges Video, mal eine langweilige Anzeige, mal etwas Spannendes – nie vorhersehbar. Welche Erklärung trifft den Mechanismus am besten?","options":["Unvorhersehbare Inhalte wecken Neugier, und wer nicht weiß, was als Nächstes kommt, will es eben herausfinden.","Langweilige Inhalte zwischendurch werten die guten auf, weil ein Treffer im Kontrast stärker wirkt als allein.","Nach mehreren Nieten scheint ein Treffer fällig zu sein, darum fällt das Aufhören vor dem nächsten Wisch schwer.","Gelegentliche, unvorhersehbare Belohnungen halten ein Verhalten stärker am Laufen als verlässliche Belohnungen."],"correctIndex":3,"explanation":"Entscheidend ist das Muster der Belohnung: Sie kommt unregelmäßig und lässt sich nicht vorhersagen. Genau darauf baut der Sog auf, denn jeder weitere Wisch könnte der Treffer sein, und jede kleine Belohnung nährt den Drang, weiterzurollen. Fachlich spricht man von operanter Konditionierung mit variablen Belohnungen; Plattformen können dieses Prinzip nutzen, um Menschen möglichst lange zu halten.","coreRule":"⚡ Unvorhersehbare Belohnungen sind der Haken, an dem das Weiterscrollen hängt.","beleg":"Werkstück E.4.2 (Einstieg: Der Daumen des Sisyphos; Verbindungen; Schmiede-Übung)","status":"entwurf","kurz":"Entscheidend ist das Muster: Belohnungen, die unregelmäßig und unvorhersehbar kommen, halten ein Verhalten stärker am Laufen als verlässliche. Naheliegend ist, die Wirkung allein im einzelnen Inhalt zu suchen, doch der Sog entsteht daraus, dass jeder Wisch der Treffer sein könnte.","prueffrage":"Was tut die Nutzerin jeweils selbst, und was folgt unmittelbar darauf?","rueckmeldung":[{"option":0,"text":"Neugier spielt sicher mit, und Unvorhersehbarkeit ist hier tatsächlich im Spiel. Erklärt wird damit aber nur das Interesse am Nächsten, nicht, warum sich das Weiterscrollen selbst festigt. Dafür ist das Muster der Belohnung entscheidend."},{"option":1,"text":"Kontraste können einen Treffer durchaus stärker wirken lassen. Das erklärt aber nicht, warum das Scrollen anhält. Der Sog kommt daher, dass Belohnungen unregelmäßig und unvorhersehbar eintreffen, nicht daher, dass Langweiliges Gutes aufwertet."},{"option":2,"text":"Wer so denkt, erwartet nach Nieten einen Treffer, und diese Erwartung treibt das Weiterwischen an. Fällig ist er aber nie, denn jeder Wisch ist unabhängig vom vorigen. Gerade dass er jederzeit kommen könnte, hält das Verhalten am Laufen."}],"familie":"anreize-durchschauen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Montag, C.; Lachmann, B.; Herrlich, M.; Zweig, K. (2019): Addictive Features of Social Media/Messenger Platforms and Freemium Games against the Background of Psychological and Economic Theories. IJERPH 16(14), 2612","oeffentlich":true,"doi":"10.3390/ijerph16142612","abruf":"2026-10-12"},{"typ":"doi","kurz":"Lindström, B. u. a. (2021): A computational reward learning account of social media engagement. Nature Communications 12, 1311","oeffentlich":true,"doi":"10.1038/s41467-020-19607-x","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"5f219666c2a3421f"}},{"id":"qx-e-070","clusterId":"E","werkstueckRef":"E.4.3","stufe":2,"question":"Welche Erklärung für die Veränderung ihres Feeds ist am sparsamsten?","scenario":"Ein Mitarbeiter einer Plattform erklärt: „Unser Empfehlungssystem versteht keine Inhalte. Es misst nur, wie lange Nutzer bleiben und ob sie klicken, kommentieren oder teilen, und zeigt mehr von dem, was diese Werte erhöht.“ Eine Nutzerin hat bisher meist Yoga-Videos geliked. Dann teilt sie zum ersten Mal einen politischen Beitrag mit einem empörten Kommentar. Danach sieht sie in ihrem Feed deutlich mehr empörende politische Beiträge.","options":["Ihr empörter Kommentar hat mehr Engagement erzeugt als ihre Yoga-Likes, deshalb zeigt ihr das System mehr von dem, was solches Engagement auslöst.","Das System hat aus ihrem Teilen geschlossen, dass sie sich jetzt mehr für Politik als für Yoga interessiert, deshalb zeigt es ihr mehr Politik.","Die Plattform will Nutzer mit Empörung möglichst lange halten, deshalb hat ihr System nach dem Kommentar gezielt aufwühlende Beiträge nach vorn geholt.","Das System hat aus dem empörten Kommentar ihre politische Einstellung abgelesen, deshalb zeigt es ihr nun Beiträge, die zu dieser Einstellung passen."],"correctIndex":0,"explanation":"Ein System, das nur Klicks, Kommentare, Shares und Verweildauer misst, braucht keine Absicht und kein Verständnis von Inhalten, um sein Verhalten zu ändern. Ihre Wut erzeugt viel mehr Engagement als ihre sanfte Zuneigung für Yoga, also lernt das System, ihr mehr davon zu zeigen. Die einfachste Erklärung braucht keine zusätzliche Annahme. Daraus folgt aber nicht, dass sie automatisch radikalisiert wird: Wie stark solche Feeds Einstellungen tatsächlich verändern, ist empirisch umstritten. Ein Schluss von Yoga-Likes auf Gesundheit und Gesellschaft verlangt ein Verständnis von Inhalten, das das System nach der Beschreibung nicht hat. Dass sie politische Interessen eingetragen hätte, steht nirgends und müsste zusätzlich angenommen werden. Eine Absicht, sie umzustimmen, setzt ein Verständnis von Haltungen voraus, das das System ebenfalls nicht hat.","coreRule":"⚡ Erkläre Verhalten mit der einfachsten Annahme, die zu den Daten passt: Ein System, das nur Engagement misst, folgt dem Engagement, nicht der Wahrheit oder einem Plan.","beleg":"Werkstück E.4.3 (Einstieg: Der unsichtbare Gott in der Maschine; Kontext & Tiefe: Der Mechanismus)","status":"entwurf","kurz":"Das System misst nur Klicks, Kommentare, Shares und Verweildauer, und ihre Empörung erzeugt davon mehr als Yoga-Likes. Das reicht als Erklärung. Dass es Inhalte versteht oder Interessen erkennt, wäre eine unnötige Zusatzannahme.","prueffrage":"Welche Signale kann das System laut Beschreibung überhaupt sehen, und was davon hat sich bei ihr nach dem Teilen verändert?","rueckmeldung":[{"option":1,"text":"Das Teilen hat den Feed tatsächlich verändert, aber „Interesse an Politik“ ist ein Begriff über Inhalte, den das System laut Beschreibung gar nicht kennt. Diese Deutung braucht eine Zusatzannahme, die der Messwert allein nicht liefert."},{"option":2,"text":"Empörung bindet tatsächlich Aufmerksamkeit, und das System profitiert davon. Dafür muss aber niemand etwas planen: Ein Verfahren, das Werte erhöht, findet solche Beiträge von selbst. Eine gezielte Absicht ist eine zusätzliche, unbelegte Annahme."},{"option":3,"text":"Eine Einstellung aus einem Kommentar „abzulesen“ setzt voraus, dass das System den Inhalt versteht, und das tut es laut Beschreibung nicht. Es zeigt ihr nicht, was zu ihrer Haltung passt, sondern was Engagement hervorbringt."}],"familie":"anreize-durchschauen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Rathje, S.; Van Bavel, J. J.; van der Linden, S. (2021): Out-group animosity drives engagement on social media. PNAS 118(26)","oeffentlich":true,"doi":"10.1073/pnas.2024292118"},{"typ":"doi","kurz":"Gauthier, G.; Hodler, R.; Widmer, P.; Zhuravskaya, E. (2026): The political effects of X's feed algorithm. Nature 652(8109)","oeffentlich":true,"doi":"10.1038/s41586-026-10098-2"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"4893947c37e87d1a"}},{"id":"qx-e-071","clusterId":"E","werkstueckRef":"E.4.3","stufe":3,"question":"Eine Auswertung von rund 2,7 Millionen Beiträgen von Medienkonten und Abgeordneten zeigte, dass Posts über die politische Gegenseite etwa doppelt so oft geteilt wurden wie Posts über die eigene Seite. Was darfst du daraus schließen?","options":["Dass gewöhnliche Nutzer Beiträge über die Gegenseite bevorzugt teilen, weil sie sich damit von ihr abgrenzen wollen.","Dass Beiträge dieser Konten über die Gegenseite öfter geteilt wurden als solche über die eigene Seite.","Dass Plattform-Algorithmen Beiträge über die Gegenseite bevorzugt ausspielen und dadurch die Spaltung vertiefen.","Dass Empörung der Grund ist, warum Beiträge über die Gegenseite öfter geteilt wurden als andere."],"correctIndex":1,"explanation":"Die Auswertung zeigt nur, dass Beiträge dieser Konten über die Gegenseite häufiger geteilt wurden als solche über die eigene Seite. Untersucht wurden Beiträge von Medienkonten und Abgeordneten: Was gewöhnliche Nutzer selbst teilen und aus welchen Motiven, bleibt offen. Ob Feed-Algorithmen Haltungen verändern, zeigen erst Experimente mit gezielt veränderten Feeds; die größten fanden keine messbare Polarisierung durch den Feed-Algorithmus, ein kleineres eine geringe, kurzfristige Wirkung. Über die Ursache des häufigeren Teilens sagt die beschriebene Auswertung nichts; in der Studie selbst sagten Wörter über die andere Gruppe das Teilen rund 4,8-mal so stark voraus wie negative Gefühlswörter allgemein, negative Gefühle allein erklären es also nicht.","coreRule":"⚡ Frag bei einer Studie nicht nur, was sie zeigt, sondern auch, wen sie untersucht hat und was ihr Design überhaupt beweisen kann.","beleg":"Werkstück E.4.3 (Kontext & Tiefe: Die emotionale Asymmetrie); Fn. gl-e-empoerung (Rathje, Van Bavel, van der Linden 2021, PNAS 118(26))","status":"entwurf","kurz":"Gemessen wurde nur, was diese Konten posteten und wie oft es geteilt wurde: Beiträge über die Gegenseite öfter als über die eigene Seite. Wer daraus Motive, Algorithmen oder Ursachen liest, geht über die Daten hinaus.","prueffrage":"Von wem stammten die ausgewerteten Beiträge, und was genau wurde an ihnen gezählt?","rueckmeldung":[{"option":0,"text":"Abgrenzung als Motiv klingt plausibel. Untersucht wurden aber nur Beiträge von Medienkonten und Abgeordneten; was gewöhnliche Nutzer teilen und warum, zeigt die Auswertung nicht."},{"option":2,"text":"Die Auswertung misst, was geteilt wurde, nicht, was Algorithmen ausspielen. Ob Feeds Haltungen verändern, prüfen erst Experimente mit veränderten Feeds; sie fanden keine oder nur eine geringe, kurzfristige Wirkung."},{"option":3,"text":"Empörung kann mitspielen, doch die Auswertung sagt über die Ursache nichts. In der Studie sagten Wörter über die andere Gruppe das Teilen fast fünfmal stärker voraus als negative Gefühlswörter allgemein. Gefühle allein erklären es nicht."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Rathje, S.; Van Bavel, J. J.; van der Linden, S. (2021): Out-group animosity drives engagement on social media. PNAS 118(26)","oeffentlich":true,"doi":"10.1073/pnas.2024292118"},{"typ":"doi","kurz":"Guess, A. M. u. a. (2023): How Do Social Media Feed Algorithms Affect Attitudes and Behavior in an Election Campaign? Science 381(6656)","oeffentlich":false,"doi":"10.1126/science.abp9364"},{"typ":"doi","kurz":"Piccardi, T. u. a. (2025): Reranking partisan animosity in algorithmic social media feeds alters affective polarization. Science 390(6776)","oeffentlich":false,"doi":"10.1126/science.adu5584"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"00052054ce7fe4f6"}},{"id":"qx-e-072","clusterId":"E","werkstueckRef":"E.4.3","stufe":4,"question":"Ein Beitrag behauptet: „Der Empfehlungs-Algorithmus einer Videoplattform führt Nutzer Schritt für Schritt in den Extremismus – ganz ohne dass sie es wollen.“ Wie sicher darfst du dieser Behauptung glauben, wenn du die Datenlage kennst?","options":["Die Behauptung ist weitgehend widerlegt: Umgestellte Feeds brachten 2023 keine messbare Polarisierung, der Algorithmus spielt beim Weg in den Extremismus kaum eine Rolle.","Die Behauptung ist eher zutreffend: Dass die meisten über Abonnements kamen, schließt nicht aus, dass Empfehlungen sie zuvor erst auf diese Kanäle gebracht haben.","Die Behauptung ist als Bild eingängig, aber in den Felddaten schwächer belegt: Ein Verstärker-Effekt ist möglich, der erste Schritt war oft eine eigene Entscheidung.","Die Behauptung lässt sich kaum prüfen: Die Experimente maßen Polarisierung durch Feeds, nicht den Weg in den Extremismus, die Datenlage passt also nicht zur Frage."],"correctIndex":2,"explanation":"Eine eingängige Geschichte ist noch kein Beleg. Die Daten sprechen gegen die starke Version der Behauptung: Wer extremistische Kanäle nutzt, kommt meist über Abonnements und Links dorthin, und große Feldexperimente fanden keine messbare Polarisierung durch den Feed-Algorithmus. Auch ein siebenwöchiges Experiment auf X fand keine Wirkung auf Polarisierung. Ganz widerlegt ist die Behauptung damit nicht: Ein kleineres Experiment mit umsortierten X-Feeds zeigte eine leichte, kurzfristige Verschiebung der Haltung zur Gegenpartei, ob sie anhält, ist offen. Die vorsichtigste, belegbare Einordnung lautet daher: Ein Verstärker ist plausibel, aber der erste Schritt ist meist eine eigene Entscheidung.","coreRule":"⚡ Ein eingängiges Bild ist kein Beleg: Prüfe die Daten, bevor du eine Behauptung glaubst – und halte dein Urteil so stark wie die Belege, nicht stärker.","beleg":"Werkstück E.4.3 (Kontext & Tiefe: Der Kaninchenbau-Effekt, Hinweis zur Beleglage); Fn. gl-e-kaninchenbau (Chen u. a. 2023; Hosseinmardi u. a. 2021; Guess u. a. 2023; Piccardi u. a. 2025)","status":"entwurf","scenario":"Der Beitrag verbreitet sich schnell, weil das Bild vom „Kaninchenbau“ so eingängig ist. Du kennst folgende Befunde: Nutzer extremistischer Kanäle kamen laut Auswertungen großer Datensätze überwiegend über Abonnements und externe Links dorthin, nicht über Empfehlungen. Große Feldexperimente mit umgestellten Feed-Algorithmen (2023) fanden keine messbare Polarisierung. Ein kleineres Experiment mit gezielt umsortierten Feeds (2025, zehn Tage) zeigte eine leichte, kurzfristige Veränderung der Haltung zur Gegenpartei.","kurz":"Eine eingängige Geschichte ist noch kein Beleg: Die meisten kamen über Abonnements und Links, große Feed-Experimente fanden keine Polarisierung. Ein Verstärker bleibt möglich, die starke Version „ohne eigenes Zutun“ trägt aber nicht.","prueffrage":"Auf welchem Weg sind Nutzer extremistischer Kanäle laut den Daten überhaupt dorthin gekommen?","rueckmeldung":[{"option":0,"text":"Die Feldexperimente von 2023 und die Zugangswege sprechen tatsächlich gegen die starke Version. „Weitgehend widerlegt“ geht aber zu weit: Ein kleineres Experiment zeigte eine leichte, kurzfristige Verschiebung, ob sie anhält, ist offen."},{"option":1,"text":"Dass Empfehlungen vor dem Abonnement eine Rolle gespielt haben könnten, lässt sich aus den Zugangswegen nicht ausschließen. Aus „möglich“ folgt aber nicht „eher zutreffend“, denn die Daten sprechen gegen die starke Version, besonders gegen „ganz ohne dass sie es wollen“."},{"option":3,"text":"Die Experimente maßen tatsächlich Polarisierung durch Feeds und nicht direkt den Weg in extremistische Kanäle. Zu den Zugangswegen gibt es aber eigene Auswertungen, die Datenlage erlaubt also eine vorsichtige Einordnung statt „kaum prüfbar“."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Chen, A. Y.; Nyhan, B.; Reifler, J.; Robertson, R. E.; Wilson, C. (2023): Subscriptions and External Links Help Drive Resentful Users to Alternative and Extremist YouTube Channels. Science Advances 9(35)","oeffentlich":true,"doi":"10.1126/sciadv.add8080"},{"typ":"doi","kurz":"Gauthier, G.; Hodler, R.; Widmer, P.; Zhuravskaya, E. (2026): The political effects of X's feed algorithm. Nature 652(8109)","oeffentlich":true,"doi":"10.1038/s41586-026-10098-2"},{"typ":"doi","kurz":"Piccardi, T. u. a. (2025): Reranking partisan animosity in algorithmic social media feeds alters affective polarization. Science 390(6776)","oeffentlich":false,"doi":"10.1126/science.adu5584"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"34d7e4f56d5054dd"}},{"id":"qx-e-073","clusterId":"E","werkstueckRef":"E.4.3","stufe":4,"question":"Du liest: „Eine Studie mit Twitter-Daten zeigt, dass Falschnachrichten sich weiter verbreiten als wahre. Der Algorithmus der Plattform ist also schuld.“ Wo liegt der Denkfehler, und was müsstest du dafür wissen?","options":["Der Schluss ist voreilig: Die Studie zeigt, dass Menschen Falsches häufiger teilten; zur Rolle des Algorithmus sagt sie dagegen nichts.","Der Schluss ist berechtigt: Wenn sich Falsches weiter verbreitet, muss die Plattform es begünstigen, und das leistet vor allem ihr Algorithmus.","Der Schluss ist verkehrt: Die Studie zeigt, dass Menschen Falsches häufiger teilten; damit ist der Algorithmus als Ursache weitgehend entlastet.","Der Schluss ist voreilig: Eine einzelne Studie genügt nicht; erst wenn weitere Studien dasselbe zeigen, ist der Algorithmus wirklich belastet."],"correctIndex":0,"explanation":"Ein Unterschied in der Verbreitung zeigt noch nicht, wodurch er entsteht. In der Auswertung von rund 126.000 Geschichten (Vosoughi, Roy, Aral 2018) teilten Menschen Falsches häufiger als Wahres, während Bots beide Sorten gleichermaßen beschleunigten. Ob Feed-Algorithmen mitwirkten, wurde nicht untersucht; dazu sagt die Studie also nichts. Wer „der Algorithmus ist schuld“ behauptet, schließt von einem gemessenen Effekt auf eine Ursache, die gar nicht geprüft wurde. Ein plausibler Mechanismus (Plattformen leben von Aufmerksamkeit) ersetzt keinen Beleg. Die Technik kann ein Verstärker sein, getragen wird die Verbreitung laut der Studie aber von Menschen.","coreRule":"⚡ Ein gemessener Effekt beweist keine Ursache, die nicht untersucht wurde: Frage immer, was die Studie tatsächlich geprüft hat.","beleg":"Werkstück E.4.3 (Anwendung & Relevanz: Bei Verschwörungsmythen & Desinformation); Fn. gl-e-vosoughi (Vosoughi, Roy, Aral 2018, Science 359(6380), S. 1146–1151)","status":"entwurf","scenario":"Eine Studie wertete rund 126.000 Geschichten auf Twitter aus und stellte fest: Falsche Nachrichten verbreiteten sich weiter als wahre. Beim Auswerten zeigte sich, dass Menschen Falsches häufiger teilten und dass Bots wahre und falsche Nachrichten gleichermaßen beschleunigten. Ob die Feed-Algorithmen der Plattform etwas dazu beitrugen, war nicht Gegenstand der Untersuchung.","quote":"","quoteLabel":"","kurz":"Die Studie misst, dass sich Falsches weiter verbreitet und dass vor allem Menschen es teilten. Wodurch das zustande kommt, zeigt sie nicht: Den Algorithmus hat sie nicht untersucht. Von einem gemessenen Effekt auf eine ungeprüfte Ursache zu schließen, ist der Fehler.","prueffrage":"Welche möglichen Ursachen hat die Studie tatsächlich untersucht, und welche kommt in den Befunden gar nicht vor?","rueckmeldung":[{"option":1,"text":"Dass Plattformen von Aufmerksamkeit leben, macht den Verdacht plausibel, und Technik kann Verbreitung durchaus verstärken. Ein plausibler Mechanismus ersetzt aber keinen Beleg, und gemessen wurde der Algorithmus nicht; getragen wurde die Verbreitung laut Studie von Menschen."},{"option":2,"text":"Dass Menschen Falsches häufiger teilten, stimmt. Daraus folgt aber keine Entlastung, denn der Algorithmus wurde gar nicht untersucht; die Studie kann ihn weder belasten noch freisprechen. Auch das wäre ein Schluss auf eine ungeprüfte Ursache, nur in die Gegenrichtung."},{"option":3,"text":"Vorsicht bei einer einzelnen Studie ist oft angebracht, doch hier liegt die Lücke woanders: Die Studie hat die Frage nach dem Algorithmus nie gestellt. Weitere Studien, die nur die Verbreitung messen, würden daran nichts ändern; nötig wäre eine, die den Algorithmus selbst betrachtet."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"MIT News (Dizikes, P., 8.3.2018): Study: On Twitter, false news travels faster than true stories","oeffentlich":true,"url":"https://news.mit.edu/2018/study-twitter-false-news-travels-faster-true-stories-0308","abruf":"2026-10-12"},{"typ":"doi","kurz":"Vosoughi, S.; Roy, D.; Aral, S. (2018): The spread of true and false news online. Science 359(6380)","oeffentlich":false,"doi":"10.1126/science.aap9559"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"c1fe379469c9b1d4"}},{"id":"qx-e-074","clusterId":"E","werkstueckRef":"E.4.3","stufe":1,"question":"Du liest die Behauptung: „Die Plattform zeigt Nutzern absichtlich Wut-Posts, also muss jemand das so geplant haben.“ Was spricht gegen diesen Schluss?","options":["Ein einfaches Optimierungsziel kann ein Verhalten hervorbringen, das niemand eigens geplant hat; dass Wut im Feed auftaucht, setzt keine menschliche Absicht voraus.","Wenig spricht dagegen: Menschen haben das Ziel des Algorithmus festgelegt, und wer dieses Ziel festlegt, hat auch dessen Folgen im Feed so geplant und auch gewollt.","Der Algorithmus lernt selbstständig, statt menschlichen Vorgaben zu folgen; was er im Feed anrichtet, liegt daher nicht mehr in der Verantwortung der Plattform selbst.","Die Nutzer klicken selbst auf Empörendes, und die Plattform zeigt nur, was gefragt ist; sie bevorzugt keine Inhalte, sondern spiegelt bloß die Nachfrage der Nutzer."],"correctIndex":0,"explanation":"Aus dem Verhalten eines Systems lässt sich nicht auf die Absicht seiner Entwickler schließen. Ein selbstlernender Algorithmus, der nur Aufmerksamkeit maximiert, findet von allein heraus, dass empörende Inhalte besonders viele Reaktionen auslösen. Solche Eigenschaften, die aus dem Zusammenspiel von Ziel und Nutzerverhalten entstehen, ohne dass jemand sie angelegt hat, heißen emergent. Gleichzeitig ist das Ergebnis kein Zufall, denn es folgt zuverlässig aus dem Ziel, Aufmerksamkeit zu maximieren.","coreRule":"⚡ Ein Ergebnis ist nicht automatisch geplant: Prüfe das Optimierungsziel, bevor du nach einem Schuldigen mit Absicht suchst.","beleg":"Werkstück E.4.3 (Kontext & Tiefe: Emergente Eigenschaft; Der Mechanismus)","status":"entwurf","scenario":"Ein Empfehlungsalgorithmus lernt selbstständig aus dem Verhalten der Nutzer. Sein einziges Ziel: Verweildauer und Interaktionen steigern. Er „weiß“ nicht, was Wut oder Wahrheit ist, sondern nur, welche Inhalte zu mehr Klicks, Kommentaren und Shares führen. Empörende Beiträge lösen davon besonders viele aus, und so tauchen sie immer häufiger in den Feeds auf.","kurz":"Aus dem, was ein System bewirkt, lässt sich nicht auf die Absicht seiner Entwickler schließen. Wer Aufmerksamkeit maximiert, findet von allein, dass Empörung besonders viele Reaktionen bringt. Das ist kein Zufall, aber auch kein Plan.","prueffrage":"Was genau wurde dem Algorithmus als Ziel vorgegeben, und woher weiß er, welche Beiträge er öfter zeigen soll?","rueckmeldung":[{"option":1,"text":"Dass Menschen das Ziel festgelegt haben, stimmt. Daraus folgt aber nicht, dass sie auch dessen Folgen im Feed so geplant haben; vom Ergebnis auf die Absicht zu schließen, ist gerade der Fehlschluss."},{"option":2,"text":"Der Algorithmus lernt zwar selbstständig, aber auf ein Ziel hin, das Menschen ihm vorgegeben haben. Die Frage nach der Verantwortung ist außerdem eine andere als die, ob jemand die Wut-Posts geplant hat."},{"option":3,"text":"Dass Empörung viele Klicks bringt, stimmt. Weil der Algorithmus daraufhin genau diese Beiträge häufiger zeigt, bevorzugt er sie aber tatsächlich. Ob dahinter eine Absicht steckt, beantwortet das nicht."}],"familie":"anreize-durchschauen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Rathje, S.; Van Bavel, J. J.; van der Linden, S. (2021): Out-group animosity drives engagement on social media. PNAS 118(26)","oeffentlich":true,"doi":"10.1073/pnas.2024292118"},{"typ":"doi","kurz":"Brady, W. J.; McLoughlin, K.; Doan, T. N.; Crockett, M. J. (2021): How social learning amplifies moral outrage expression in online social networks. Science Advances 7(33)","oeffentlich":true,"doi":"10.1126/sciadv.abe5641","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"6ae77e6597d27551"}},{"id":"qx-e-075","clusterId":"E","werkstueckRef":"E.4.4","stufe":1,"question":"Was ist hier das eigentliche Problem – und was prüfst du als Erstes?","options":["Das Material ist echt, aber sein Zusammenhang ist falsch. Du suchst zuerst die Originalquelle und die ganze Aufnahme der Rede.","Das Material ist echt, der Satz also gefallen. Du prüfst zuerst, ob die Stadträtin ihn inzwischen öffentlich erklärt hat.","Das Material ist echt, aber drei Jahre alt. Du prüfst zuerst, ob das Video gerade als neue Aufnahme ausgegeben und verbreitet wird.","Das Material ist echt, aber die Überschrift übertreibt. Du prüfst zuerst, ob der Satz im Video wirklich wörtlich so zu hören ist."],"correctIndex":0,"explanation":"Ob eine Aufnahme echt ist und ob sie das zeigt, was behauptet wird, sind zwei getrennte Fragen. Hier ist das Material echt, aber der Kontext falsch: Der Satz stammt aus einer Rede über ein ganz anderes Thema und wurde mit einer neuen Überschrift versehen. Solche einfachen Manipulationen mit echtem Material sind viel leichter herzustellen als KI-Fälschungen und deshalb häufiger. Im Bild findet sich nichts Gefälschtes. Wer nur nach Bildfehlern sucht, übersieht sie. Wirksam ist die Frage nach der Herkunft: Wo stammt die Aufnahme ursprünglich her, wann wurde sie gemacht, und was kam davor und danach? Die Suche nach der Originalquelle und der vollständigen Aufnahme klärt das am schnellsten.","coreRule":"⚡ Echtes Material kann täuschen: Prüfe nicht nur, ob ein Bild echt ist, sondern ob es das zeigt, was behauptet wird.","beleg":"Werkstück E.4.4 (Kernidee, Absatz zu „Cheap Fakes“)","status":"entwurf","scenario":"Ein Video zeigt eine Stadträtin bei einer Rede, in der sie scheinbar sagt: „Das ist mir alles egal.“ Es verbreitet sich rasant. Ein Faktencheck stellt fest: Bild und Ton sind echt und nicht per KI erzeugt. Das Video stammt aus einer Rede von vor drei Jahren, in der sie über ein ganz anderes Thema sprach; der Satz ist aus einem längeren Zusammenhang herausgeschnitten und mit einer neuen Überschrift versehen.","kurz":"Echt heißt nicht aussagekräftig: Der Satz ist gefallen, stammt aber aus einer Rede über ein anderes Thema. Wer nur das Material prüft, übersieht das. Am schnellsten klärt die Originalquelle samt vollständiger Aufnahme, was davor und danach kam.","prueffrage":"Was hat der Faktencheck über Bild und Ton herausgefunden, und was über die Überschrift?","rueckmeldung":[{"option":1,"text":"Dass der Satz gefallen ist, stimmt. Doch das sagt noch nichts darüber, wovon die Rede war. Eine spätere Erklärung der Stadträtin ersetzt nicht den Blick auf die Herkunft: ob und wie der Satz damals in den Zusammenhang passte."},{"option":2,"text":"Das Alter des Videos ist ein wichtiger Teil des Problems. Der Kern liegt aber tiefer: Der Satz wurde aus einer Rede über ein anderes Thema herausgeschnitten und neu betitelt. Der Zeitpunkt allein klärt nicht, was er ursprünglich bedeutete."},{"option":3,"text":"Die Überschrift ist tatsächlich neu, und das ist ein Teil des Problems. Ob der Satz zu hören ist, steht aber schon fest: Bild und Ton sind echt. Die Frage ist nicht, ob er gesagt wurde, sondern in welchem Zusammenhang."}],"familie":"bild-und-video-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Brennen, J. S.; Simon, F.; Howard, P. N.; Nielsen, R. K. (2020): Types, Sources, and Claims of COVID-19 Misinformation. Reuters Institute Factsheet","oeffentlich":true,"doi":"10.60625/risj-awvq-sr55"},{"typ":"url","kurz":"Dufour, N. u. a. (2024): AMMeBa: A Large-Scale Survey and Dataset of Media-Based Misinformation In-The-Wild. arXiv:2405.11697v2 (Preprint)","oeffentlich":true,"url":"https://arxiv.org/abs/2405.11697"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"6f5ec6d20978cb91"}},{"id":"qx-e-076","clusterId":"E","werkstueckRef":"E.4.4","stufe":2,"question":"Du siehst ein Video, in dem ein Politiker etwas Schockierendes sagt. Dein Puls rast, und du willst es sofort teilen. Was ist der klügste erste Schritt?","options":["Zunächst warten, bis sich der Puls beruhigt hat, und das Video dann teilen, weil Entscheidungen im Ruhezustand verlässlicher ausfallen als im Affekt.","Zunächst nichts teilen, sondern nach Originalquelle und unabhängiger Bestätigung suchen, weil die Quelle mehr Sicherheit gibt als der Eindruck.","Zunächst auf Blinzeln, Hautglätte und Lippensynchronität achten und erst bei Auffälligem zweifeln, weil sich viele Fälschungen daran verraten.","Zunächst nachsehen, wie viele Menschen das Video schon gesehen haben, und bei großer Reichweite teilen, weil eine Fälschung vielen Zuschauern auffallen würde."],"correctIndex":1,"explanation":"Dein rasender Puls ist selbst ein Warnsignal: Genau auf solche Gefühle zielen Fälschungen. Ein aufrührerisches Video ist zunächst nur eine Behauptung, kein Beweis. Der Blick aufs Bild trägt wenig: In Experimenten erkannten Menschen Deepfakes kaum besser als der Zufall, hielten Fälschungen eher für echt als umgekehrt und überschätzten ihre Trefferquote. Typische Merkmale wie Blinzeln oder wachsartige Haut verschwinden zudem mit besserer Technik. Auch mit Fragezeichen geteilt, erreicht das Video viele Menschen; das spätere Dementi erreicht nur einen Bruchteil, und selbst ein Fälschungshinweis nimmt der Wirkung nur einen Teil. Mehr Sicherheit gibt die Frage nach der Originalquelle und ob unabhängige, seriöse Stellen das Video bestätigen. Die anderen Wege klingen vernünftig, klären aber nicht, ob das Video echt ist: Abwarten beruhigt zwar den Puls, prüft aber nichts. Auf Bildmerkmale zu achten hilft wenig, weil sich Fälschungen kaum noch daran verraten. Eine große Reichweite sagt nichts über Echtheit, denn viele Betrachter erkennen Fälschungen ebenso schlecht wie du.","coreRule":"⚡ Je stärker ein Video auf dich wirkt, desto wichtiger ist die Frage nach seiner Quelle.","beleg":"Werkstück E.4.4 (Das Anti-Denkmuster: Aktivierungs-Fragen 1 und 2; Red Flags)","status":"entwurf","scenario":"","kurz":"Ein schockierendes Video ist zunächst nur eine Behauptung. Ob es echt ist, zeigen Originalquelle und unabhängige Bestätigung, nicht dein Eindruck: Den lenken Fälschungen gezielt, und selbst auf Bildmerkmale kannst du dich kaum verlassen.","prueffrage":"Was genau macht dich gerade so sicher, dass der Politiker das wirklich gesagt hat?","rueckmeldung":[{"option":0,"text":"Erst abzukühlen ist sinnvoll, denn der rasende Puls ist selbst ein Warnsignal. Nur steht danach noch immer nicht fest, ob das Video echt ist: Ruhe beruhigt den Puls, prüft aber nichts."},{"option":2,"text":"Früher verrieten sich manche Fälschungen an Blinzeln oder wachsartiger Haut. Menschen erkennen Deepfakes aber kaum besser als der Zufall und halten Fälschungen eher für echt; mit besserer Technik verschwinden diese Merkmale zudem. Ein unauffälliger Blick gibt also falsche Sicherheit."},{"option":3,"text":"Viele Aufrufe wirken wie eine Bestätigung durch die Menge. Doch erkennen die meisten Betrachter Fälschungen ebenso schlecht wie du, Reichweite sagt also nichts über Echtheit."}],"familie":"bild-und-video-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Diel, A. u. a. (2024): Human Performance in Detecting Deepfakes: A Systematic Review and Meta-Analysis of 56 Papers. Computers in Human Behavior Reports 16","oeffentlich":true,"doi":"10.1016/j.chbr.2024.100538"},{"typ":"doi","kurz":"Köbis, N. C.; Doležalová, B.; Soraperra, I. (2021): Fooled Twice: People Cannot Detect Deepfakes but Think They Can. iScience 24(11)","oeffentlich":true,"doi":"10.1016/j.isci.2021.103364"},{"typ":"doi","kurz":"Clark, S.; Lewandowsky, S. (2026): The Continued Influence of AI-Generated Deepfake Videos Despite Transparency Warnings. Communications Psychology 4, 13","oeffentlich":true,"doi":"10.1038/s44271-025-00381-9"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"ddabc6500601b840"}},{"id":"qx-e-077","clusterId":"E","werkstueckRef":"E.4.4","stufe":3,"question":"Ein Kollege folgert: „Dann prüfe ich eben jedes verdächtige Video genau und vertraue danach meinem Eindruck.“ Welche Schlussfolgerung ist angemessen?","options":["Die schwache Erkennung liegt vermutlich an zu geringer Anstrengung; wer sich bemüht und genau hinsieht, darf seinem Eindruck deshalb weitgehend trauen.","Bei unbekannten Personen kann der Augenschein allein eine Fälschung nicht sicher verraten; sicherer ist es, die Herkunft des Videos zu prüfen.","Die Selbstüberschätzung ist das eigentliche Problem; wer vorab seine Trefferquote testet und nur bei hohem Selbstvertrauen urteilt, darf seinem Eindruck dann trauen.","Einzelurteile liegen zwar kaum über dem Zufall, in der Gruppe gleichen sich Fehler aber aus; Videos sollten deshalb im Team beurteilt werden, bis die Mehrheit zustimmt."],"correctIndex":1,"explanation":"Eine Metaanalyse von 56 Arbeiten (Diel u. a. 2024) ergab eine Trefferquote von 55,5 %, also kaum über dem Zufall. Im Versuch mit 210 Teilnehmenden (Köbis u. a. 2021) wurden Fälschungen eher für echt gehalten als umgekehrt, und die Teilnehmenden überschätzten ihre Trefferquote. Wenn weder ein Warntext noch eine Prämie für richtige Antworten die Erkennung verbessern, ist das Gefühl „sieht echt aus“ keine brauchbare Prüfung. Wer das Urteil auf die Herkunft stützt (Originalquelle, unabhängige Bestätigung), umgeht die Schwäche des Augenscheins. Ein Training mit Rückmeldung verbesserte die Erkennung in den meisten Experimenten, bloße Hinweise auf typische Fehler brachten gemischte Ergebnisse. Die anderen Gedanken klingen vernünftig, passen aber nicht zu den Befunden: Mangelnde Anstrengung erklärt sie nicht, denn auch die bezahlte Gruppe schnitt nicht besser ab. Das Selbstvertrauen taugt nicht als Gütesiegel, denn die Selbsteinschätzung lag deutlich über der tatsächlichen Trefferquote. Liegen schon die Einzelurteile kaum über dem Zufall, werden sie in der Gruppe nicht zu einem verlässlichen Urteil.","coreRule":"⚡ Dein Gefühl für „echt“ trügt – verlass dich auf Quellenprüfung statt auf Augenschein.","beleg":"Werkstück E.4.4 (Red Flags); Fn. gl-e-erkennung (Köbis u. a. 2021; Diel u. a. 2024, S. 7); Fn. gl-e-deepfake (Diel u. a. 2024, 55,5 %)","status":"entwurf","scenario":"Ein Forschungsteam zeigte 210 Online-Teilnehmenden 16 kurze Videos unbekannter Personen; die Hälfte war gefälscht. Bei den meisten Clips lag die Erkennung nicht verlässlich über dem Zufall. Wer vorab einen Text über die Gefahren von Deepfakes las oder für richtige Antworten bezahlt wurde, schnitt nicht besser ab als die übrigen. Die Selbsteinschätzung lag deutlich über der tatsächlichen Trefferquote.","kurz":"Wenn nicht einmal Warntext oder Geld die Erkennung verbessern, ist das Gefühl „sieht echt aus“ keine brauchbare Prüfung. Das genaue Hinsehen schützt nicht, die Herkunft des Videos lässt sich dagegen nachprüfen.","prueffrage":"Wie gut lagen die Teilnehmenden tatsächlich, und wie gut glaubten sie selbst zu liegen?","rueckmeldung":[{"option":0,"text":"Mehr Mühe liegt als Erklärung nahe. Die für richtige Antworten bezahlte Gruppe schnitt aber nicht besser ab, obwohl sie Grund zur Anstrengung hatte. Dem Eindruck zu trauen, bleibt daher unbegründet."},{"option":2,"text":"Dass die Selbsteinschätzung zu hoch lag, stimmt. Hohes Selbstvertrauen sagt aber nichts über die tatsächliche Treffsicherheit; wer sich sicher fühlt, liegt deshalb nicht öfter richtig. Als Filter für den Eindruck taugt es nicht."},{"option":3,"text":"Teamarbeit schadet nicht, und Gruppenurteile gelten oft als robuster. Hier liegen aber schon die Einzelurteile kaum über dem Zufall, und Zustimmung der Mehrheit macht sie nicht zuverlässiger. Es fehlt weiter eine Prüfung, die nicht auf dem Eindruck beruht."}],"familie":"bild-und-video-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Diel, A. u. a. (2024): Human Performance in Detecting Deepfakes: A Systematic Review and Meta-Analysis of 56 Papers. Computers in Human Behavior Reports 16","oeffentlich":true,"doi":"10.1016/j.chbr.2024.100538"},{"typ":"doi","kurz":"Köbis, N. C.; Doležalová, B.; Soraperra, I. (2021): Fooled Twice: People Cannot Detect Deepfakes but Think They Can. iScience 24(11)","oeffentlich":true,"doi":"10.1016/j.isci.2021.103364"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"9701e733d1b65809"}},{"id":"qx-e-078","clusterId":"E","werkstueckRef":"E.4.4","stufe":4,"question":"Welche Prüffrage trifft die Schwachstelle der Behauptung am besten?","options":["Wie groß ist der Anteil von KI-Bildern unter allen gezählten Bildfälschungen insgesamt?","Wie hat sich die Zahl der gezählten KI-Bilder in sozialen Netzwerken seit dem Vorjahr verändert?","Wie viele Fachleute für Desinformation halten KI-Bilder inzwischen für die häufigste Art der Fälschung?","Wie groß ist der Anteil von KI-Bildern unter allen Bildern, die in sozialen Netzwerken geteilt werden?"],"correctIndex":0,"explanation":"Die Behauptung betrifft einen Anteil, und dafür braucht es eine systematische Zählung aller Bildfälschungen; auffällige Einzelfälle reichen nicht, denn spektakuläre KI-Bilder bleiben besser im Gedächtnis als unscheinbare Fälschungen. Die vorhandenen Zählungen sprechen gegen die Behauptung: In 225 englischsprachigen Covid-19-Falschmeldungen (Januar bis März 2020) fand sich kein einziger Deepfake, alle manipulierten Bilder und Videos waren mit einfachen Mitteln bearbeitet (Brennen u. a. 2020). Auch in englischsprachigen Faktenchecks bis November 2023 überwogen einfache Mittel, vor allem echte Bilder in falschem Zusammenhang, obwohl KI-Bilder ab Frühjahr 2023 rasch zunahmen (Dufour u. a. 2024, Preprint). Wie es seither steht, ist offen. Die anderen Fragen klingen interessant, klären den Anteil aber nicht: Dass KI-Bilder zunehmen, sagt nichts darüber, ob andere Fälschungen noch häufiger sind. Die Meinung von Fachleuten ist kein Beleg für die tatsächliche Verteilung. Und der Anteil unter allen Bildern misst etwas anderes als den Anteil unter den Fälschungen.","coreRule":"⚡ Auffälligkeit ist keine Häufigkeit: Wer „die meisten“ behauptet, braucht eine Zählung, keinen Eindruck.","beleg":"Werkstück E.4.4 (Werkbank-Frage); Fn. gl-e-haeufiger (Brennen u. a. 2020, Factsheet S. 4; Dufour u. a. 2024, Preprint); Anm. anm-gl-e-haeufiger","status":"entwurf","scenario":"Du liest einen Artikel über Desinformation. Er behauptet, die meisten Bildfälschungen im Netz seien heute KI-erzeugt. Als einzigen Beleg führt der Verfasser an, dass ihm in letzter Zeit auffällig viele KI-Bilder in sozialen Netzwerken begegnet sind.","quote":"","quoteLabel":"","kurz":"Die Behauptung betrifft einen Anteil, und den kann nur eine systematische Zählung aller Bildfälschungen zeigen. Wer sich auf auffällige Einzelfälle stützt, überschätzt leicht, was im Gedächtnis bleibt: spektakuläre KI-Bilder statt unscheinbarer Fälschungen.","prueffrage":"Worauf stützt sich der Verfasser, und in welchem Ausschnitt des Netzes hat er seine Beobachtungen gemacht?","rueckmeldung":[{"option":1,"text":"Dass KI-Bilder zunehmen, kann stimmen und wirkt wie ein Hinweis in die richtige Richtung. Die Zunahme sagt aber nichts über den Anteil: Andere Fälschungen können weiterhin häufiger sein, auch wenn sie weniger auffallen."},{"option":2,"text":"Fachleute kennen sich aus, daher wirkt ihre Einschätzung gewichtig. Eine Meinung ist jedoch keine Zählung: Sie sagt nicht, wie sich die Fälschungen tatsächlich verteilen, und kann selbst von auffälligen Fällen geprägt sein."},{"option":3,"text":"Hier steckt etwas Richtiges: Gefragt wird nach einem Anteil. Der Nenner passt aber nicht: Behauptet wird etwas über Bildfälschungen, nicht über alle geteilten Bilder, und beides sind verschiedene Anteile."}],"familie":"basisrate-beachten","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Brennen, J. S.; Simon, F.; Howard, P. N.; Nielsen, R. K. (2020): Types, Sources, and Claims of COVID-19 Misinformation. Reuters Institute Factsheet","oeffentlich":true,"doi":"10.60625/risj-awvq-sr55"},{"typ":"url","kurz":"Dufour, N. u. a. (2024): AMMeBa: A Large-Scale Survey and Dataset of Media-Based Misinformation In-The-Wild. arXiv:2405.11697v2 (Preprint)","oeffentlich":true,"url":"https://arxiv.org/abs/2405.11697"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"f420c074a5f474a2"}}]`);export{t as n,n as t};